insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إنَّ الْمُقْسِطِينَ عِنْدَ اللهِ تَعَالَى عَلَى مَنَابِرَ مِنْ نُورٍ، عَلَى يَمِينِ الرَّحْمَنِ، وَفِي رِوَايَةٍ: وَكِلْتَا يَدَيْهِ يَمِينٌ، الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറയുന്നു: "നീതിമാൻമാർ അല്ലാഹുവിന്റെയടുക്കൽ, റഹ്മാന്റെ വലതുഭാഗത്തുള്ള പ്രകാശത്താലുള്ള പീഠത്തിൻമേലായിരിക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ: "അവന്റെ ഇരു കരങ്ങളും വലത് തന്നെയാണ്. തന്റെ വിധികളിലും കുടുംബത്തിലും താൻ ഏറ്റെടുത്തതിലും നീതി നടപ്പാക്കുന്നവരാണവർ." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 405, 405, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=1), 1, 'وَفِي رِوَايَةٍ: وَكِلْتَا يَدَيْهِ يَمِينٌ، الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا". (ن)', 'മറ്റൊരു നിവേദനിൽ: "അവന്റെ ഇരു കരങ്ങളും വലത് തന്നെയാണ്. തന്റെ വിധികളിലും കുടുംബത്തിലും താൻ ഏറ്റെടുത്തതിലും നീതി നടപ്പാക്കുന്നവരാണവർ." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَبْعَةٌ يُظِلُّهُمُ اللهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ، يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللهِ عَزَّ وَجَلَّ، وَرَجُلٌ ذَكَرَ اللهَ فِي خَلَاءٍ فَفَاضَتْ عَيْنَاهُ، وَرَجُلٌ كَانَ قَلْبُهُ مُعَلَّقًا فِي الْمَسْجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللهِ عَزَّ وَجَلَّ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ إِلَى نَفْسِهَا فَقَالَ: إِنِّي أَخَافُ اللهَ عَزَّ وَجَلَّ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا صَنَعَتْ يَمِينُهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ അല്ലാഹുവിന്റെ തണൽ മാത്രമുള്ള ദിവസം അല്ലാഹു ഏഴ് പേർക്ക് തണൽ നൽകും: നീതിമാനായ ഭരണാധികാരി, മഹോന്നതനായ അല്ലാഹുവിന്റെ ഇബാദത്തിലായി വളർന്ന യുവാവ്, ഏകാന്തതയിലിരുന്ന് അല്ലാഹുവിനെ ഓർക്കുകയും തന്റെ രണ്ട് കണ്ണുകൾ നിറഞ്ഞൊഴുകുകയും ചെയ്തവൻ, മസ്ജിദുമായി തന്റെ ഹൃദയം എപ്പോഴും ബന്ധപ്പെടുത്തിയവൻ, മഹോന്നതനായ അല്ലാഹുവിനു വേണ്ടി പരസ്പരം സ്നേഹിച്ച രണ്ട് വ്യക്തികൾ, ഭംഗിയും തറവാടിത്തവുമുള്ള ഒരു പെണ്ണ് തന്നിലേക്ക് വിളിച്ചപ്പോൾ ഉന്നതനായ അല്ലാഹുവിനെ ഞാൻ പേടിക്കുന്നു എന്ന് പറഞ്ഞവൻ, തന്റെ വലത് കൈ ചെയ്തത് ഇടത് കൈ അറിയാതെ രഹസ്യമായി ദാനം ചെയ്തവൻ. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 405, 405, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إنَّ أَحَبَّ النَّاسِ إِلَى اللهِ يَوْمَ الْقِيَامَةِ، وَأَدْنَاهُمْ مِنْهُ مَجْلِسًا، إِمَامٌ عَادِلٌ. وَأَبْغَضَ النَّاسِ إِلَى اللهِ، وَأَبْعَدَهُمْ مِنْهُ مَجْلِسًا، إِمَامٌ جَائِرٌ". حسن. (ت)', 'അബൂസഇൗദ്(റ): റസൂൽ(സ) പറയുന്നു: "അവസാന നാളിൽ അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ടവനും അവനോട് ഏറ്റവും അടുത്തിരിക്കുന്നവനും, നീതിമാനായ ഭരണാധികാരിയാണ്. അല്ലാഹുവിന് ഏറ്റവും ദേഷ്യമുള്ളവനും അവനിൽ നിന്ന് ഏറ്റവും വിദൂരത്തായിരിക്കുന്നവനും അക്രമിയായ ഭരണാധികാരിയാണ്." (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 405, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إنَّ اللهَ مَعَ الْقَاضِي مَا لَمْ يَجُرْ، فَإِذَا جَارَ تَخَلَّى عَنْهُ وَلَزِمَهُ الشَّيْطَانُ". حسن. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫ(റ): റസൂൽ(സ) പറയുന്നു: "അക്രമം കാണിക്കാത്ത കാലത്തോളം വിധികർത്താവിന്റെ കൂടെയാണ് അല്ലാഹു. അവൻ അക്രമം ചെയ്താൽ അല്ലാഹു അവനിൽ നിന്ന് മാറി നിൽക്കുകയും പിശാച് അവനെ വിടാതെ പിന്തുടരുകയും ചെയ്യും." (തു,ജ)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَبْدِ اللهِ بْنِ مَوْهَبٍ: أَنَّ عُثْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ لِابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: اذْهَبْ فَاقْضِ بَيْنَ النَّاسِ. قَالَ: أَوْ تُعافِينِي يَا أَمِيرَ الْمُؤْمِنِينَ. قَالَ: فَمَا تَكْرَهُ مِنْ ذَلِكَ، وَقَدْ كَانَ أَبُوكَ يَقْضِي؟ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ قَاضِيًا، فَقَضَى بِالْعَدْلِ، فَبِالْحَرِيِّ أَنْ يَنْقَلِبَ مِنْهُ كَفَافًا". فَمَا أَرْجُو بَعْدَ ذَلِكَ؟ (ت)', 'അബ്ദുല്ലാഹിബ്നു മൗഹിബ്(റ): ഉസ്മാൻ(റ) ഇബ്നുഉമർ(റ)വിനോട് പറഞ്ഞു: താങ്കൾ പോയി ജനങ്ങൾക്കിടയിൽ വിധി കൽപിക്കുക. അദ്ദേഹം ചോദിച്ചു: അമീറുൽ മുഅ്മിനീൻ, എന്നെ രക്ഷപ്പെടുത്തിക്കൂടേ? ഉസ്മാൻ(റ) ചോദിച്ചു: അതിൽ നിന്ന് എന്താണ് താങ്കൾക്ക് ഇഷ്ടപ്പെടാത്തത്, താങ്കളുടെ പിതാവ് വിധി കൽപിക്കാറുണ്ടായിരുന്നില്ലേ? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും ഭരണാധികാരിയായി നീതികൊണ്ട് വിധിച്ചാൽ അവനോട് (അനുകൂലമായോ പ്രതികൂലമായോ) പ്രതികരിക്കാതെ പിരിഞ്ഞു പോരുകയാണ് വേണ്ടത്." ഇങ്ങനെയെങ്കിൽ ഞാനെന്താണാഗ്രഹിക്കുക? (തു)', 'عَبْدِ اللهِ بْنِ مَوْهَبٍ', 'അബ്ദുല്ലാഹിബ്നു മൗഹിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْقُضَاةُ ثَلَاثَةٌ، قَاضِيَانِ فِي النَّارِ، وَقَاضٍ فِي الْجَنَّةِ: رَجُلٌ قَضَى بِغَيْرِ الْحَقِّ فَعَلِمَ ذَاكَ، فَذَاكَ فِي النَّارِ. وَقَاضٍ لَا يَعْلَمُ، فَأَهْلَكَ حُقُوقَ النَّاسِ، فَهُوَ فِي النَّارِ. وَقَاضٍ قَضَى بِالْحَقِّ، فَذَلِكَ فِي الْجَنَّةِ". (د,ت,جه)', 'ബുറൈദ(റ): നബി(സ) പറയുന്നു: "ഭരണാധികാരികൾ മൂന്ന് വിധമാണ്: അതിൽ രണ്ട് പേർ നരകത്തിലാണ്, ഒരാൾ സ്വർഗ്ഗത്തിലുമാണ്. സത്യമല്ലാത്തത് കൊണ്ട് വിധിക്കുകയും അതറിയുകയും ചെയ്തു, അവൻ നരകത്തിലാണ്. അറിവില്ലാതെ വിധിച്ച് അങ്ങനെ ജനങ്ങളുടെ അവകാശങ്ങൾ ധ്വംസിച്ച ഭരണാധികാരിയും നരകത്തിലാകുന്നു. സത്യം കൊണ്ട് വിധിച്ച ഭരണാധികാരി, അവൻ സ്വർഗ്ഗത്തിലാകുന്നു." (ദ,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَمْرِو بْنِ مُرَّةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِمُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ إِمَامٍ يُغْلِقُ بَابَهُ دُونَ ذَوِي الْحَاجَةِ وَالْخَلَّةِ وَالْمَسْكَنَةِ، إِلَّا أَغْلَقَ اللهُ أَبْوَابَ السَّمَاءِ دُونَ خَلَّتِهِ وَحَاجَتِهِ وَمَسْكَنَتِهِ". فَجَعَلَ مُعَاوِيَةُ رَجُلًا عَلَى حَوَائِجِ النَّاسِ. (ت)', 'അംറുബ്നു മുർറ(റ): അദ്ദേഹം മുആവിയ(റ)യോട് പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ദാരിദ്ര്യമുള്ളവന്റെയും ആവശ്യമുള്ളവന്റെയും പാർപ്പിടാവശ്യവുമായി വരുന്നവന്റെയും മുന്നിൽ വാതിൽ അടക്കുന്ന എല്ലാ ഭരണാധികാരികളുടെ ദാരിദ്ര്യത്തിനും ആവശ്യത്തിനും പാർപ്പിടത്തിനും മുമ്പിൽ അല്ലാഹു ആകാശകവാടങ്ങൾ അടച്ചിടും." അപ്പോൾ മുആവിയ(റ) ജനങ്ങളുടെ ആവശ്യങ്ങൾ കൈകാര്യം ചെയ്യാൻ ഒരാളെ നിയമിച്ചു. (തു)', 'عَمْرِو بْنِ مُرَّةَ', 'അംറുബ്നു മുർറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 406, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ وَلِيَ الْقَضَاءَ، أَوْ جُعِلَ قَاضِيًا بَيْنَ النَّاسِ، فَقَدْ ذُبِحَ بِغَيْرِ سِكِّينٍ". حسن. (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും ഭരണാധികാരം ഏറ്റെടുത്താൽ, അല്ലെങ്കിൽ ജനങ്ങളുടെ ഭരണാധികാരിയാക്കപ്പെട്ടുവെങ്കിൽ അവൻ കത്തിയില്ലാതെ അറുക്കപ്പെട്ടിരിക്കുന്നു." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسْأَلِ الْإِمَارَةَ، فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا". (ن)', 'അബ്ദുർറഹ്മാനിബ്നു സമുറ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങൾ നേതൃത്വം ചോദിക്കരുത്. കാരണം, അത് ചോദിച്ച് നൽകപ്പെട്ടാൽ നിന്റെ മേൽ അത് ഏൽപിക്കപ്പെടും. ചോദിക്കാതെ നിനക്കത് നൽകപ്പെട്ടാൽ അതിൽ നീ സഹായിക്കപ്പെടും." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുർറഹ്മാനിബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إنَّكُمْ سَتَحْرِصُونَ عَلَى الْإِمَارَةِ، وَإِنَّهَا سَتَكُونُ نَدَامَةً وَحَسْرَةً يَوْمَ الْقِيَامَةِ، فَنِعْمَتِ الْمُرْضِعَةُ وَبِئْسَتِ الْفَاطِمَةُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അധികാരം കൊതിക്കുന്ന സമയം വരും. എന്നാൽ, അന്ത്യനാളിൽ അത് ദുഃഖവും ഖേദവുമാകും. സുഖകരമായ ജീവിതം എത്ര നല്ലത്! അധികാരത്തെ നശിപ്പിക്കുന്ന മരണം എത്ര ദുഷിച്ചത് (എന്ന് നിങ്ങൾ ചിന്തിക്കും)." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ بِشْرٍ الْأَنْصَارِيِّ الْأَزْرَقِ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَجُلَانِ مِنْ أَبْوَابِ كِنْدَةَ، وَأَبُو مَسْعُودٍ الْأَنْصَارِيُّ جَالِسٌ فِي حَلْقَةٍ، فَقَالَا: أَلَا رَجُلٌ يُنَفِّذُ بَيْنَنَا. فَقَالَ رَجُلٌ مِنَ الْحَلْقَةِ: أَنَا، فَأَخَذَ أَبُو مَسْعُودٍ كَفًّا مِنْ حَصًى فَرَمَاهُ بِهِ، وَقَالَ: مَهْ، إِنَّهُ كَانَ يُكْرَهُ التَّسَرُّعُ إِلَى الْحُكْمِ. (د)', 'അബ്ദുർറഹ്മാനിബ്നു ബിശ്റിൽ അൻസാരിൽ അസ്റഖ്(റ): കിന്ദ പർവ്വതത്തിന്റെ ഭാഗത്ത് കൂടെ രണ്ടാളുകൾ വന്നു. അബൂമസ്ഉൗദിൽ അൻസാരി(റ) ഹൽഖയിൽ ഇരിക്കുന്നുണ്ടായിരുന്നു. അപ്പോൾ അവർ രണ്ട് പേരും ചോദിച്ചു: ഞങ്ങൾക്കിടയിൽ തീരുമാനമെടുക്കുന്ന ആരെങ്കിലുമുണ്ടോ? അപ്പോൾ ഹൽഖയിൽ നിന്നൊരാൾ പറഞ്ഞു: ഞാൻ. അപ്പോൾ അബൂമസ്ഉൗദ്(റ) ഒരു പിടി കല്ലെടുത്ത് അദ്ദേഹത്തെ എറിഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: അരുത്, കാരണം വിധിയിൽ ധൃതി കാണിക്കൽ വെറുക്കപ്പെട്ടതാണ്. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ بِشْرٍ الْأَنْصَارِيِّ الْأَزْرَقِ', 'അബ്ദുർറഹ്മാനിബ്നു ബിശ്റിൽ അൻസാരിൽ അസ്റഖ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ طَلَبَ الْقَضَاءَ وَاسْتَعَانَ عَلَيْهِ وُكِلَ إِلَيْهِ، وَمَنْ لَمْ يَطْلُبْهُ وَلَمْ يَسْتَعِنْ عَلَيْهِ أَنْزَلَ اللهُ مَلَكًا يُسَدِّدُهُ". (د,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(റ) പറയുന്നത് ഞാൻ കേട്ടു: "ഭരണം ആരെങ്കിലും ചോദിച്ച് വാങ്ങുകയും അതിൽ സഹായം ആവശ്യപ്പെടുകയും ചെയ്താൽ അത് അവന്റെ മേൽ ഏൽപിക്കപ്പെട്ടു. ഭരണം ചോദിക്കാതിരിക്കുകയും അതിൽ സഹായം ആവശ്യപ്പെടാതിരിക്കുകയും ചെയ്താൽ അല്ലാഹു അവനെ ഭരണത്തിൽ സഹായിക്കാൻ ഒരു മലകിനെ നിയമിക്കും." (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِى هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ طَلَبَ قَضَاءَ الْمُسْلِمِينَ حَتَّى يَنَالَهُ: ثُمَّ غَلَبَ عَدْلُهُ جَوْرَهُ فَلَهُ الْجَنَّةُ، وَمَنْ غَلَبَ جَوْرُهُ عَدْلَهُ فَلَهُ النَّارُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "ആരെങ്കിലും മുസ്ലിംകളുടെ ഭരണം ആവശ്യപ്പെടുകയും അവനത് ലഭിക്കുകയും ശേഷം അവന്റെ നീതി അവന്റെ അക്രമത്തെ മറികടക്കുകയും ചെയ്താൽ അവന്ന് സ്വർഗ്ഗമുണ്ട്. ആരുടെയെങ്കിലും അക്രമം അവന്റെ നീതിയെ മറികടന്നാൽ അവന്ന് നരകവുമുണ്ട്." (ദ)', 'أَبِى هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 407, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانِي نَاسٌ مِنَ الْأَشْعَرِيِّينَ فَقَالُوا: اذْهَبْ مَعَنَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِنَّ لَنَا حَاجَةً، فَذَهَبْتُ مَعَهُمْ، فَقَالُوا: يَا رَسُولَ اللهِ، اسْتَعِنْ بِنَا فِي عَمَلِكَ. قَالَ أَبُو مُوسَى: فَاعْتَذَرْتُ مِمَّا قَالُوا، وَأَخْبَرْتُ أَنِّي لَا أَدْرِي مَا حَاجَتُهُمْ، فَصَدَّقَنِي وَعَذَرَنِي، فَقَالَ: "إِنَّا لَا نَسْتَعِينُ فِي عَمَلِنَا بِمَنْ سَأَلَنَا". (ن)', 'അബൂമൂസാ(റ): അശ്അരി ഗോത്രക്കാരിൽ നിന്ന് കുറച്ചാളുകൾ എന്റെയടുത്ത് വന്ന് പറഞ്ഞു: റസൂൽ(സ)യുടെ അടുത്തേക്ക് ഞങ്ങളുടെ കൂടെ വരിക. കാരണം ഞങ്ങൾക്കൊരു ആവശ്യമുണ്ട്. അപ്പോൾ ഞാൻ അവരുടെ കൂടെ പോയി. അവർ പറഞ്ഞു: തിരുദൂതരേ, അങ്ങയുടെ പ്രവർത്തനങ്ങളിൽ ഞങ്ങളെ സഹായത്തിനാവശ്യപ്പെട്ടാലും! അബൂമൂസാ(റ) പറയുന്നു: അവർ പറഞ്ഞതിന് ഞാൻ മാപ്പപേക്ഷിച്ചു. അവരുടെ ആവശ്യം എന്തായിരുന്നുവെന്ന് എനിക്കറിയില്ലായിരുന്നുവെന്നും ഞാനറിയിച്ചു. അപ്പോൾ തിരുമേനി(സ) എന്നെ ശരിവെക്കുകയും എന്റെ അപേക്ഷ സ്വീകരിക്കുകയും ചെയ്തു. എന്നിട്ടവിടന്ന് പറഞ്ഞു: "നമ്മോട് വന്ന് ചോദിക്കുന്നവരോട് നമ്മുടെ ജോലിയിൽ നാം സഹായം ആവശ്യപ്പെടുകയില്ല." (ന)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ جَاءَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا؟ قَالَ: "إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي أَثَرَةً، فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الْحَوْضِ". (ن)', 'ഉസൈദുബ്നു ഹുളൈർ(റ): അൻസാറുകളിൽപ്പെട്ട ഒരു വ്യക്തി റസൂൽ(സ)യുടെ അടുത്തുവന്ന് ചോദിച്ചു: അവിടന്ന് ഇന്നയാളെ നിയമിച്ചത് പോലെ എന്നെയും നിയമിക്കുന്നില്ലേ? തിരുമേനി(സ) പറഞ്ഞു: "എന്റെ ശേഷം നിങ്ങൾ ഒരുപാട് സ്വാർത്ഥ തൽപരരെ അഭിമുഖീകരിക്കും. അതുകൊണ്ട് നിങ്ങൾ എന്നെ ഹൗളിന്റെയരികെ കണ്ടുമുട്ടുന്നത് വരെ ക്ഷമിക്കുക." (ന)', 'أُسَيْدِ بْنِ حُضَيْرٍ', 'ഉസൈദുബ്നു ഹുളൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ قَاضِيًا، فَقُلْتُ: يَا رَسُولَ اللهِ، تُرْسِلُنِي وَأَنَا حَدِيثُ السِّنِّ وَلَا عِلْمَ لِي بِالْقَضَاءِ؟ فَقَالَ: "إِنَّ اللهَ سَيَهْدِي قَلْبَكَ، وَيُثَبِّتُ لِسَانَكَ. فَإِذَا جَلَسَ بَيْنَ يَدَيْكَ الْخَصْمَانِ فَلَا تَقْضِيَنَّ حَتَّى تَسْمَعَ مِنَ الْآخَرِ كَمَا سَمِعْتَ مِنَ الْأَوَّلِ، فَإِنَّهُ أَحْرَى أَنْ يَتَبَيَّنَ لَكَ الْقَضَاءُ". قَالَ: فَمَا زِلْتُ قَاضِيًا. أَوْ: مَا شَكَكْتُ فِي قَضَاءٍ بَعْدُ. (د,ت)', 'അലി(റ): റസൂൽ(സ) എന്നെ യമനിലേക്ക് ഭരണാധികാരിയായി അയച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: തിരുദൂതരേ, ഞാൻ യുവാവും വിധി അറിയാത്തവനുമായിരിക്കെ എന്നെ അങ്ങ് അയക്കുകയാണോ? അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു താങ്കളുടെ ഹൃദയത്തെ സന്മാർഗ്ഗത്തിലാക്കും, നാവിന് ദൃഢത നൽകും. താങ്കളുടെ മുമ്പിൽ തർക്കമുള്ള രണ്ടാളുകൾ വന്നാൽ ആദ്യത്തെയാളിൽ നിന്ന് കേട്ട പോലെ രണ്ടാമത്തവനെയും കേൾക്കുന്നത് വരെ നീ വിധിക്കരുത്. വിധി വ്യക്തമാകാൻ ഏറ്റവും അനുയോജ്യം അതാണ്." അലി(റ) പറയുന്നു: അതിന് ശേഷം ഞാൻ വിധികർത്താവായിരുന്നു. അല്ലെങ്കിൽ അതിന് ശേഷം ഒരു വിധിയിലും ഞാൻ സംശയിച്ചിട്ടില്ല. (ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 408, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ، فَقُلْتُ: يَا رَسُولَ اللهِ، تَبْعَثُنِي وَأَنَا شَابٌّ أَقْضِي بَيْنَهُمْ، وَلَا أَدْرِي مَا الْقَضَاءُ؟ قَالَ: فَضَرَبَ بِيَدِهِ فِي صَدْرِي، ثُمَّ قَالَ: "اللَّهُمَّ اهْدِ قَلْبَهُ وَثَبِّتْ لِسَانَهُ". قَالَ: فَمَا شَكَكْتُ بَعْدُ فِي قَضَاءٍ بَيْنَ اثْنَيْنِ. (جه)', 'അലി(റ): റസൂൽ(സ) എന്നെ യമനിലേക്കയച്ചു. അപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, യുവാവായ എന്നെ അവർക്കിടയിൽ വിധി പറയാൻ അവിടുന്ന് പറഞ്ഞയക്കുകയാണോ? എങ്ങനെ വിധിക്കണമെന്ന് പോലും എനിക്കറിയില്ല. അലി(റ) പറയുന്നു: അപ്പോൾ റസൂൽ(സ) എന്റെ നെഞ്ചിൽ അടിച്ചുകൊണ്ട് പറഞ്ഞു: "അല്ലാഹുവേ, നീ അവന്റെ ഹൃദയത്തെ സന്മാർഗത്തിലാക്കുകയും നാവിനെ ഉറപ്പിക്കുകയും ചെയ്യണേ." അലി(റ) പറയുന്നു: അതിനു ശേഷം രണ്ടാളുകൾക്കിടയിലുള്ള ഒരു വിധിയിലും ഞാൻ സംശയിച്ചിട്ടില്ല. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَرَادَ أَنْ يَبْعَثَهُ – وَفِي رِوَايَةٍ: لَمَّا بَعَثَهُ – إِلَى الْيَمَنِ قَالَ: "كَيْفَ تَقْضِي إِذَا عَرَضَ لَكَ قَضَاءٌ". قَالَ: أَقْضِي بِكِتَابِ اللهِ، قَالَ: "فَإِنْ لَمْ تَجِدْ فِي كِتَابِ اللهِ". قَالَ: فَبِسُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "فَإِنْ لَمْ تَجِدْ فِي سُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا فِي كِتَابِ اللهِ". قَالَ: أَجْتَهِدُ رَأْيِي وَلَا آلُو. فَضَرَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَدْرَهُ وَقَالَ: "الْحَمْدُ لِلَّهِ الَّذِي وَفَّقَ رَسُولَ رَسُولِ اللهِ لِمَا يُرْضِي رَسُولَ اللهِ". (د,ت)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ) അദ്ദേഹത്തെ യമനിലേക്ക് അയച്ചപ്പോൾ - അല്ലെങ്കിൽ അയക്കാനുദ്ദേശിച്ചപ്പോൾ - അദ്ദേഹത്തോട് ചോദിച്ചു: "താങ്കൾ പ്രശ്നങ്ങളിൽ എങ്ങനെയാണ് വിധിക്കുക?" മുആദ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ കിതാബനുസരിച്ച് വിധിക്കും. അവിടന്ന് ചോദിച്ചു: "അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ താങ്കൾ കണ്ടില്ലെങ്കിലോ?" അദ്ദേഹം പറഞ്ഞു: അപ്പോൾ റസൂൽ(സ)യുടെ തിരുചര്യ കൊണ്ട് ഞാൻ വിധിക്കും. നബി(സ) ചോദിച്ചു: "റസൂൽ(സ)യുടെ സുന്നത്തിലും അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലും കണ്ടില്ലെങ്കിലോ?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ വീഴ്ചവരുത്തുകയില്ല. ഞാൻ സ്വയം ഇജ്തിഹാദ് ചെയ്യും. അപ്പോൾ നബി(സ) അദ്ദേഹത്തിന്റെ നെഞ്ചിലടിച്ചു പറഞ്ഞു: "അല്ലാഹുവിന്റെ റസൂലിന്റെ ദൂതന് അല്ലാഹുവും റസൂലും ഇഷ്ടപ്പെടുന്ന കാര്യത്തിന് സൗഭാഗ്യം നൽകിയ അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും." (ദ,തു)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=18), 1, 'وَفِي رِوَايَةٍ: لَمَّا بَعَثَهُ – إِلَى الْيَمَنِ قَالَ: "كَيْفَ تَقْضِي إِذَا عَرَضَ لَكَ قَضَاءٌ". قَالَ: أَقْضِي بِكِتَابِ اللهِ، قَالَ: "فَإِنْ لَمْ تَجِدْ فِي كِتَابِ اللهِ". قَالَ: فَبِسُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "فَإِنْ لَمْ تَجِدْ فِي سُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا فِي كِتَابِ اللهِ". قَالَ: أَجْتَهِدُ رَأْيِي وَلَا آلُو. فَضَرَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَدْرَهُ وَقَالَ: "الْحَمْدُ لِلَّهِ الَّذِي وَفَّقَ رَسُولَ رَسُولِ اللهِ لِمَا يُرْضِي رَسُولَ اللهِ". (د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ مُلُوكٌ بَعْدَ عِيسَى بْنِ مَرْيَمَ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ بَدَّلُوا التَّوْرَاةَ وَالْإِنْجِيلَ، وَكَانَ فِيهِمْ مُؤْمِنُونَ يَقْرَءُونَ التَّوْرَاةَ، قِيلَ لِمُلُوكِهِمْ: مَا نَجِدُ شَتْمًا أَشَدَّ مِنْ شَتْمٍ يَشْتِمُونَا هَؤُلَاءِ، إِنَّهُمْ يَقْرَءُونَ: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ} [المائدة: ٤٤] وَهَؤُلَاءِ الْآيَاتُ مَعَ مَا يَعِيبُونَا بِهِ فِي أَعْمَالِنَا فِي قِرَاءَتِهِمْ، فَادْعُهُمْ فَلْيَقْرَءُوا كَمَا نَقْرَأُ، وَلْيُؤْمِنُوا كَمَا آمَنَّا. فَدَعَاهُمْ فَجَمَعَهُمْ وَعَرَضَ عَلَيْهِمُ الْقَتْلَ أَوْ يَتْرُكُوا قِرَاءَةَ التَّوْرَاةِ وَالْإِنْجِيلِ، إِلَّا مَا بَدَّلُوا مِنْهَا، فَقَالُوا: مَا تُرِيدُونَ إِلَى ذَلِكَ؟ دَعُونَا. فَقَالَتْ طَائِفَةٌ مِنْهُمْ: ابْنُوا لَنَا أُسْطُوَانَةً ثُمَّ ارْفَعُونَا إِلَيْهَا، ثُمَّ اعْطُونَا شَيْئًا نَرْفَعُ بِهِ طَعَامَنَا وَشَرَابَنَا، فَلَا نَرِدُ عَلَيْكُمْ. وَقَالَتْ طَائِفَةٌ مِنْهُمْ: دَعُونَا نَسِيحُ فِي الْأَرْضِ وَنَهِيمُ وَنَشْرَبُ كَمَا يَشْرَبُ الْوَحْشُ، فَإِنْ قَدَرْتُمْ عَلَيْنَا فِي أَرْضِكُمْ فَاقْتُلُونَا. وَقَالَتْ طَائِفَةٌ مِنْهُمْ: ابْنُوا لَنَا دُورًا فِي الْفَيَافِي، وَنَحْتَفِرُ الْآبَارَ وَنَحْتَرِثُ الْبُقُولَ، فَلَا نَرِدُ عَلَيْكُمْ وَلَا نَمُرُّ بِكُمْ. وَلَيْسَ أَحَدٌ مِنَ الْقَبَائِلِ إِلَّا وَلَهُ حَمِيمٌ فِيهِمْ. قَالَ: فَفَعَلُوا ذَلِكَ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَرَهْبَانِيَّةً ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ إِلَّا ابْتِغَاءَ رِضْوَانِ اللهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا} [الحديد: ٢٧]. وَالْآخَرُونَ قَالُوا: نَتَعَبَّدُ كَمَا تَعَبَّدَ فُلَانٌ، وَنَسِيحُ كَمَا سَاحَ فُلَانٌ، وَنَتَّخِذُ دُورًا كَمَا اتَّخَذَ فُلَانٌ، وَهُمْ عَلَى شِرْكِهِمْ، لَا عِلْمَ لَهُمْ بِإِيمَانِ الَّذِينَ اقْتَدَوْا بِهِ، فَلَمَّا بَعَثَ اللهُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَبْقَ مِنْهُمْ إِلَّا قَلِيلٌ انْحَطَّ رَجُلٌ مِنْ صَوْمَعَتِهِ، وَجَاءَ سَائِحٌ مِنْ سِيَاحَتِهِ، وَصَاحِبُ الدَّيْرِ مِنْ دَيْرِهِ، فَآمَنُوا بِهِ وَصَدَّقُوهُ، فَقَالَ اللهُ تَبَارَكَ وَتَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَآمِنُوا بِرَسُولِهِ يُؤْتِكُمْ كِفْلَيْنِ مِنْ رَحْمَتِهِ} [الحديد: ٢٨] أَجْرَيْنِ بِإِيمَانِهِمْ بِعِيسَى وَبِالتَّوْرَاةِ وَالْإِنْجِيلِ، وَبِإِيمَانِهِمْ بِمُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَتَصْدِيقِهِمْ، قَالَ: {يَجْعَلْ لَكُمْ نُورًا تَمْشُونَ بِهِ} الْقُرْآنَ وَاتِّبَاعَهُمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: {لِئَلَّا يَعْلَمَ أَهْلُ الْكِتَابِ} يَتَشَبَّهُونَ بِكُمْ: {أَنْ لَا يَقْدِرُونَ عَلَى شَيْءٍ مِنْ فَضْلِ اللهِ} الْآيَةَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഈസാ ബിൻ മർയം(അ)മിന്റെ ശേഷമുള്ള രാജാക്കന്മാർ തൗറാതും ഇൻജീലും മാറ്റിമറിച്ചിരുന്നു. അവരിൽ തൗറാത്തോതുന്ന വിശ്വാസികളുമുണ്ടായിരുന്നു. അങ്ങനെ അവരുടെ രാജാക്കന്മാരോട് പറയപ്പെട്ടു: ഇവർ (മുഅ്മിനുകൾ) ചീത്ത പറയുന്നതാണ് നമുക്കേറ്റവും ശക്തമായ ചീത്തപറയൽ. കാരണം അവർ ഓതുന്നു: ''അല്ലാഹു ഇറക്കിയതു കൊണ്ട് വിധിക്കാത്തവരാണ് യഥാർത്ഥ സത്യനിഷേധികൾ'' (മാഇദ: 44) ഈ സൂക്തങ്ങൾ, അതുകൊണ്ട് അവർ നമ്മെ ആക്ഷേപിക്കുന്നതോടൊപ്പം അവരുടെ പാരായണമനുസരിച്ച് നമ്മുടെ സുവിശേഷങ്ങളിൽ ഉള്ളതാണ് താനും. അതിനാൽ അവരെ വിളിക്കുക, നാം ഓതുന്നതു പോലെ അവരും ഓതട്ടെ. നാം വിശ്വസിക്കുന്നത് പോലെ അവരും വിശ്വസിക്കട്ടെ. അപ്പോൾ രാജാവ് അവരെ വിളിച്ച് ഒരുമിച്ചുകൂട്ടി വധശിക്ഷ പ്രഖ്യാപിച്ചു. അല്ലെങ്കിൽ ഇൻജീലും തൗറാത്തും മാറ്റിമറിച്ച രൂപത്തിലല്ലാതെ ഓതരുത്, അവർ ചോദിച്ചു: അതല്ലാതെ നിങ്ങൾ എന്താണുദ്ദേശിക്കുന്നത്? നിങ്ങൾ ഞങ്ങളെ ഒഴിവാക്കുക. അപ്പോൾ ഇവരിൽ നിന്നൊരു സംഘം പറഞ്ഞു: ഞങ്ങൾക്ക് മലയിൽ ഒരാശ്രമം ഉണ്ടാക്കുകയും ഞങ്ങളെ അങ്ങോട്ട് പറഞ്ഞയക്കുകയും ഞങ്ങളുടെ ഭക്ഷണത്തിനും വെള്ളത്തിനും വേണ്ടി വല്ലതും നൽകുകയും ചെയ്യുക. എന്നാൽ ഞങ്ങൾ നിങ്ങൾക്ക് പ്രതികൂലമായി വരികയില്ല. മറ്റൊരു സംഘം പറഞ്ഞു: ഞങ്ങളെ വിട്ടയക്കുക, ഞങ്ങൾ ഇവിടെ അലക്ഷ്യമായി നടന്നുകൊള്ളാം. മൃഗങ്ങളെപ്പോലെ ഭക്ഷിക്കാം, നിങ്ങളുടെ നാട്ടിൽവെച്ച് ഞങ്ങളെ പിടികൂടിയാൽ നിങ്ങൾക്ക് ഞങ്ങളെ വധിച്ചുകളയാം. മറ്റൊരു സംഘം പറഞ്ഞു: ഞങ്ങൾക്ക് മരുഭൂമിയിൽ വീടുണ്ടാക്കിത്തരിക. ഞങ്ങൾ കിണറുകൾ കുഴിക്കും. ചീരകൾ കൃഷിചെയ്യും. നിങ്ങളുടെയടുത്തേക്ക് വരികയോ നിങ്ങളുടെ അരികിലൂടെ നടക്കുകയോ ചെയ്യുകയുമില്ല. എല്ലാ ഗോത്രക്കാർക്കും അവരിൽ തന്നെ കൂട്ടുകാരുണ്ടാകും. നിവേദകൻ പറയുന്നു: അവർ അങ്ങനെ ചെയ്തു. അപ്പോൾ അല്ലാഹു ഇറക്കി: ''നാം അവർക്ക് കൽപിച്ചിട്ടാത്ത, അവർ സ്വയം ഉണ്ടാക്കിയ പൗരോഹിത്യം അല്ലാഹുവിന്റെ തൃപ്തി മാത്രം ആഗ്രഹിച്ച് കൊണ്ടുള്ളതായിരുന്നു. അവർ അതിനെ വേണ്ടപോലെ സൂക്ഷിച്ചില്ല.'' (ഹദീദ്: 27) മറ്റുള്ളവർ പറഞ്ഞു: ഇന്നവൻ ആരാധിക്കുന്നതു പോലെ ഞങ്ങൾ ആരാധിക്കുന്നു. ഇന്നവൻ പോയതുപോലെ ഞങ്ങളും പോകുന്നു. ഇന്നവർ വീടുണ്ടാക്കിയതു പോലെ ഞങ്ങളും ഉണ്ടാക്കുന്നു. അവർ അവരുടെ ശിർക്കിൽ തന്നെ നിലകൊണ്ടു. അവർ പിന്തുടരുന്നവരുടെ വിശ്വാസത്തെക്കുറിച്ച് അവർക്കൊരറിവുമില്ല. അങ്ങനെ നബി(സ) നിയോഗിക്കപ്പെട്ടപ്പോൾ അവരിൽ നിന്ന് കുറച്ചുപേർ അവശേഷിച്ചിരുന്നു. അവരിൽ നിന്നൊരാൾ തന്റെ ആശ്രമത്തിൽ നിന്നിറങ്ങിവന്നു. ചുറ്റിസഞ്ചരിക്കുന്നവർ അവരുടെ സഞ്ചാരം ഉപേക്ഷിച്ചുവന്നു. വീടിന്റെയാൾ വീട്ടിൽനിന്നിറങ്ങിവന്നു. അവർ നബി(സ)യെക്കൊണ്ട് വിശ്വസിക്കുകയും നബി(സ)യെ സത്യമാക്കുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു പറഞ്ഞു: ''സത്യവിശ്വാസികളേ, നിങ്ങൾ അല്ലാഹുവിനെ ഭയപ്പെടുക, അവന്റെ റസൂലിനെക്കൊണ്ട് വിശ്വസിക്കുക. എന്നാൽ അവന്റെ റഹ്മത്തിന്റെ രണ്ടു ഭാഗവും നിങ്ങൾക്കവൻ നൽകും.'' (ഹദീദ്: 28) രണ്ട് കൂലികൾ തരുമെന്നതിൽ ഒന്ന് ഈസാ(അ)മിനെ കൊണ്ടും തൗറാത്ത്, ഇൻജീൽ എന്നിവയെക്കൊണ്ടുമുള്ള വിശ്വാസം കാരണത്താലും മറ്റൊന്ന് മുഹമ്മദ്(സ)യെ കൊണ്ടുള്ള വിശ്വാസവും വാസ്തവമാക്കലും കാരണത്താലുമാണ്. അല്ലാഹു പറഞ്ഞു: ''നിങ്ങൾക്ക് നടക്കാനുള്ള പ്രകാശം അവൻ ആക്കിത്തരും''. ഖുർആനും നബി(സ)യോടുള്ള പിന്തുടരലുമാണത്. അല്ലാഹു പറയുന്നു: ''യാതൊന്നും അധീനപ്പെടുത്താൻ തങ്ങൾക്ക് കഴിവില്ലെന്നും തീർച്ചയായും അനുഗ്രഹം അല്ലാഹുവിന്റെ കയ്യിലാണെന്നും അവൻ ഉദ്ദേശിച്ചവർക്ക് നൽകുമെന്നും വേദക്കാർ അറിയാൻ വേണ്ടിയാണിത് (അവർ നിങ്ങളെപ്പോലെയാകാൻ വേണ്ടി).'' (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الحديد: ٢٨', null, 409, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ} إِلَى قَوْلِهِ: {الْفَاسِقُونَ} هَؤُلَاءِ الْآيَاتِ الثَّلَاثِ نَزَلَتْ فِي الْيَهُودِ خَاصَّةً: فِي قُرَيْظَةَ وَالنَّضِيرِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അല്ലാഹു അവതരിപ്പിച്ചത് കൊണ്ട് വിധിക്കാത്തവൻ നിഷേധികളാണ്'' എന്ന് തുടങ്ങി ''തെമ്മാടികളാണ്'' എന്നത് വരെയുള്ള മൂന്ന് ആയതുകൾ ഖുറൈള, നളീർ എന്നീ യഹൂദീ ഗോത്രക്കാരുടെ വിഷയത്തിൽ മാത്രമായി അവതരിച്ചതാണ്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ ثُمَّ أَصَابَ فَلَهُ أَجْرَانِ، وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ". (م)', 'അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ഭരണാധികാരി ഗവേഷണം നടത്തി വിധിക്കുകയും അങ്ങനെ ശരിയാവുകയും ചെയ്താൽ അവന് രണ്ട് കൂലിയുണ്ട്. വിധി തെറ്റാണെങ്കിൽ അവന് ഒരു കൂലിയുണ്ട്." (മു)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ – رَضِيَ اللهُ عَنْهُمَا – قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا أَنَا بَشَرٌ، وَإِنَّكُمْ تَخْتَصِمُونَ إِلَيَّ، وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ، فَأَقْضِيَ لَهُ عَلَى نَحْوِ مَا أَسْمَعُ مِنْهُ، فَمَنْ قَضَيْتُ لَهُ مِنْ حَقِّ أَخِيهِ بِشَيْءٍ فَلَا يَأْخُذْ مِنْهُ شَيْئًا، فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنَ النَّارِ". (ق,د,ت,ن,جه)', 'സൈനബ് ബിൻത് ഉമ്മുസലമ(റ): ഉമ്മുസലമ(റ) പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ മനുഷ്യൻ മാത്രമാണ്. നിങ്ങൾ തർക്കിച്ച് എന്റെ അടുത്ത് വരുന്നു. നിങ്ങളിൽ ചിലർ തന്റെ തെളിവുകളെക്കുറിച്ച് നന്നായി സംസാരിക്കാൻ കഴിവുള്ളവരായിരിക്കും. അവനിൽ നിന്ന് കേൾക്കുന്നതനുസരിച്ചായിരിക്കും ഞാൻ വിധിക്കുക. ആർക്കെങ്കിലും തന്റെ സഹോദരന്റെ അവകാശത്തിൽ നിന്ന് ഞാൻ വീതിച്ച് തരുന്നുവെങ്കിൽ അവനത് എടുക്കരുത്, കാരണം അവന് ഞാൻ മുറിച്ച് കൊടുക്കുന്നത് നരകത്തിൽ നിന്നുള്ള ഒരു കഷ്ണമാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ –', 'സൈനബ് ബിൻത് ഉമ്മുസലമ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلَانِ يَخْتَصِمَانِ فِي مَوَارِيثَ لَهُمَا، لَمْ تَكُنْ لَهُمَا بَيِّنَةٌ إِلَّا دَعْوَاهُمَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ... فَذَكَرَتْ مِثْلَهُ، فَبَكَى الرَّجُلَانِ وَقَالَ كُلُّ وَاحِدٍ مِنْهُمَا: حَقِّي لَكَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا إِذْ فَعَلْتُمَا مَا فَعَلْتُمَا فَاقْتَسِمَا، وَتَوَخَّيَا الْحَقَّ، ثُمَّ اسْتَهِمَا، ثُمَّ تَحَالَّا". وَفِي رِوَايَةٍ: يَخْتَصِمَانِ فِي مَوَارِيثَ وَأَشْيَاءَ قَدْ دَرَسَتْ، فَقَالَ: "إِنِّي إِنَّمَا أَقْضِي بَيْنَكُمْ بِرَأْيِي فِيمَا لَمْ يُنْزَلْ عَلَيَّ فِيهِ". (د)', 'ഉമ്മുസലമ(റ): അനന്തര സ്വത്തിൽ തർക്കിക്കുന്ന രണ്ടാളുകൾ റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. അവരുടെ വാദമല്ലാതെ അവർക്കൊരു തെളിവുമില്ല. അപ്പോൾ നബി(സ) മേലുദ്ധരിച്ചപോലെ പറഞ്ഞു. അപ്പോൾ രണ്ടുപേരും കരഞ്ഞു, ഓരോരുത്തരും പറഞ്ഞു: എന്റെ അവകാശം നിനക്കാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ചെയ്തതെല്ലാം ചെയ്തു, നിങ്ങളിത് ഭാഗിക്കുക, എന്നിട്ട് അവകാശത്തിൽ മറ്റേയാളുടെ സംതൃപ്തി നേടുക. പിന്നെ നറുക്കിട്ട് ഓരോരുത്തരുടെ ഓഹരിയും മറ്റവന്റെ ഓഹരിയിൽ നിന്ന് മുക്തമാക്കുക." മറ്റൊരു നിവേദനം: നശിച്ചുപോയ ചില സാധനങ്ങളിലും അനന്തരസ്വത്തിലും അവർ തർക്കിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എനിക്കവതരിക്കപ്പെടാത്ത വിഷയത്തിൽ എന്റെ അഭിപ്രായമനുസരിച്ച് മാത്രമാണ് ഞാൻ വിധിക്കുന്നത്." (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 411, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=23), 1, 'وَفِي رِوَايَةٍ: يَخْتَصِمَانِ فِي مَوَارِيثَ وَأَشْيَاءَ قَدْ دَرَسَتْ، فَقَالَ: "إِنِّي إِنَّمَا أَقْضِي بَيْنَكُمْ بِرَأْيِي فِيمَا لَمْ يُنْزَلْ عَلَيَّ فِيهِ". (د)', 'മറ്റൊരു നിവേദനം: നശിച്ചുപോയ ചില സാധനങ്ങളിലും അനന്തരസ്വത്തിലും അവർ തർക്കിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എനിക്കവതരിക്കപ്പെടാത്ത വിഷയത്തിൽ എന്റെ അഭിപ്രായമനുസരിച്ച് മാത്രമാണ് ഞാൻ വിധിക്കുന്നത്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ وَهُوَ عَلَى الْمِنْبَرِ: يَا أَيُّهَا النَّاسُ، إِنَّ الرَّأْيَ إِنَّمَا كَانَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُصِيبًا، لِأَنَّ اللهَ كَانَ يُرِيهِ، وَإِنَّمَا هُوَ مِنَّا الظَّنُّ وَالتَّكَلُّفُ. (د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ) മിമ്പറിൽ കയറി പറഞ്ഞു: ജനങ്ങളേ, റസൂൽ(സ)യുടെ അഭിപ്രായം ശരിമാത്രമായിരുന്നു. കാരണം അല്ലാഹു റസൂൽ(സ)ക്ക് കാണിച്ചുകൊടുക്കുമായിരുന്നു. എന്നാൽ നമ്മിൽ നിന്നുണ്ടാകുന്ന അഭിപ്രായം ഊഹവും സംശയവും മാത്രമാണ്. (ദ)', 'عُمَرَ بْنَ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَ جَلَبَةَ خَصْمٍ بِبَابِ حُجْرَتِهِ، فَخَرَجَ إِلَيْهِمْ، فَقَالَ: "إِنَّمَا أَنَا بَشَرٌ، وَإِنَّهُ يَأْتِينِي الْخَصْمُ، فَلَعَلَّ بَعْضَهُمْ أَنْ يَكُونَ أَبْلَغَ مِنْ بَعْضٍ، فَأَحْسِبُ أَنَّهُ صَادِقٌ فَأَقْضِي لَهُ، فَمَنْ قَضَيْتُ لَهُ بِحَقِّ مُسْلِمٍ فَإِنَّمَا هِيَ قِطْعَةٌ مِنَ النَّارِ، فَلْيَحْمِلْهَا أَوْ يَذَرْهَا". (م)', 'നബി(സ)യുടെ ഭാര്യ ഉമ്മുസലമ(റ): നബി(സ)യുടെ വാതിലിൽ ഒരു തർക്കത്തിന്റെ പിടിവലി അവിടുന്ന് കേട്ടു. റസൂൽ(സ) അവരുടെയടുത്തേക്ക് ചെന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ മനുഷ്യൻ മാത്രമാണ്, തർക്കിക്കുന്നവർ എന്റെ നേരെ വരുന്നു. ഒരുപക്ഷേ, നിങ്ങളിൽ ചിലർ ചിലരേക്കാൾ വാഗ്വൈഭവമുള്ളവരായിരിക്കും. അപ്പോൾ അവനാണ് സത്യസന്ധനെന്ന് എനിക്ക്തോന്നും. അവനനുസരിച്ച് ഞാൻ വിധിക്കുകയും ചെയ്യും. നിങ്ങളിലാർക്കെങ്കിലും ഞാൻ ഒരു മുസ്‌ലിമിന്റെ അവകാശം വിധിച്ചുവെങ്കിൽ അത് നരകത്തിലെ ഭാഗമാണ്. അതിനാൽ ഒന്നുകിൽ അവനത് എടുക്കട്ടെ. അല്ലെങ്കിൽ അതിനെ ഒഴിവാക്കിക്കൊള്ളട്ടെ." (മു)', 'أُمِّ سَلَمَةَ', 'നബി(സ)യുടെ ഭാര്യ ഉമ്മുസലമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: عَصَمَنِي اللهُ بِشَيْءٍ سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، لَمَّا هَلَكَ كِسْرَى قَالَ: "مَنِ اسْتَخْلَفُوا". قَالُوا: بِنْتَهُ. قَالَ: "لَنْ يُفْلِحَ قَوْمٌ وَلَّوْا أَمْرَهُمُ امْرَأَةً". (ن)', 'അബൂബക്റ(റ): റസൂൽ(സ)യിൽ നിന്നും ഞാൻ കേട്ടൊരു സംഭവം എന്നെ കാത്തു. കിസ്റ മരിച്ചപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ആരെയാണവർ അധികാരം ഏൽപിച്ചത്?" അവർ പറഞ്ഞു: കിസ്റയുടെ മകളെ. റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീയെ ഭരണമേൽപിച്ച ഒരു സമൂഹവും വിജയിക്കില്ല." (ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِرَضِيَ اللهُ عَنْهُمَا: أَنَّهُ قَدِمَ رَكْبٌ مِنْ بَنِي تَمِيمٍ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ أَبُو بَكْرٍرَضِيَ اللهُ عَنْهُ: أَمِّرِ الْقَعْقَاعَ بْنَ مَعْبَدٍ. وَقَالَ عُمَرُ رَضِي اللهُ عَنْهُ: بَلْ أَمِّرِ الْأَقْرَعَ بْنَ حَابِسٍ. فَتَمَارَيَا حَتَّى ارْتَفَعَتْ أَصْوَاتُهُمَا، فَنَزَلَتْ فِي ذَلِكَ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا بَيْنَ يَدَيِ اللهِ وَرَسُولِهِ} حَتَّى انْقَضَتِ الْآيَةُ [الحجرات: ١]. {وَلَوْ أَنَّهُمْ صَبَرُوا حَتَّى تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَهُمْ} [الحجرات: ٥]. (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ബനൂതമീമിൽ നിന്നൊരു സംഘം റസൂൽ(സ)യുടെ അടുത്തുവന്നു. അബൂബകർ(റ) പറഞ്ഞു: ഖഅ്ഖാഉബ്നു മഅ്ബദിനെ അങ്ങ് നേതാവാക്കുക. ഉമർ(റ) പറഞ്ഞു: അല്ല, അഖ്റഉബ്നു ഹാബിസിനെ അങ്ങ് അമീറാക്കുക. അവർ തർക്കിച്ചു ശബ്ദമുയർന്നു. അപ്പോൾ ഈ വിഷയകമായി സൂക്തമവതരിച്ചു: ''സത്യവിശ്വാസികളേ, നിങ്ങൾ അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും മുന്നിൽ മുൻകടന്നു പ്രവർത്തിക്കരുത്. അല്ലാഹുവിന് നിങ്ങൾ തഖ്‌വ ചെയ്യുക. നിശ്ചയം അല്ലാഹു കേൾക്കുന്നവനും അറിയുന്നവനുമാണ്.'' (ഹുജുറാത്ത്: 1) ''അങ്ങ് അവരുടെ അടുത്തേക്ക് പുറപ്പെട്ട് ചെല്ലുന്നതുവരെ അവർ ക്ഷമിക്കുകയാണെങ്കിൽ അതാണവർക്കുത്തമം.'' (ഹുജുറാത്ത്: 5) (ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الحجرات: ٥', null, 412, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ هَانِئِ بْنِ يَزِيد رَضِيَ اللهُ عَنْهُ: أَنَّهُ لَمَّا وَفَدَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَهُ وَهُمْ يَكْنُونَ هَانِئًا أَبَا الْحَكَمِ، فَدَعَاهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ: "إِنَّ اللهَ هُوَ الْحَكَمُ، وَإِلَيْهِ الْحُكْمُ، فَلِمَ تُكَنَّى أَبَا الْحَكَمِ". فَقَالَ: إِنَّ قَوْمِي إِذَا اخْتَلَفُوا فِي شَيْءٍ أَتَوْنِي فَحَكَمْتُ بَيْنَهُمْ، فَرَضِيَ كِلَا الْفَرِيقَيْنِ. قَالَ: "مَا أَحْسَنَ مِنْ هَذَا، فَمَا لَكَ مِنَ الْوُلْدِ". قَالَ: لِي شُرَيْحٌ، وَعَبْدُ اللهِ، وَمُسْلِمٌ. قَالَ: "فَمَنْ أَكْبَرُهُمْ". قَالَ: شُرَيْحٌ. قَالَ: "فَأَنْتَ أَبُو شُرَيْحٍ". فَدَعَا لَهُ وَلِوَلَدِهِ. (ن)', 'ഹാനിഉബ്നു യസീദ്(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നപ്പോൾ ജനങ്ങൾ അദ്ദേഹത്തെ അബുൽ ഹകം എന്ന് ഉപനാമം വിളിക്കുന്നതായി റസൂൽ(സ) കേട്ടു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തെ വിളിച്ച് പറഞ്ഞു: "അല്ലാഹുവാണ് വിധിക്കുന്നവൻ, അവനിലേക്കാണ് വിധി, പിന്നെയെന്തുകൊണ്ടാണ് അബുൽഹകം (വിധികർത്താവിന്റെ പിതാവ്) എന്ന് നീ വിളിക്കപ്പെടുന്നത്." അദ്ദേഹം പറഞ്ഞു: എന്റെ ജനതയിൽ വല്ല തർക്കവുമുണ്ടാകുമ്പോൾ അവർ എന്റെ അടുത്തുവരും. ഞാൻ അവർക്കിടയിൽ വിധിക്കുകയും ചെയ്യും. അപ്പോൾ രണ്ട് വിഭാഗവും സംതൃപ്തരാകും. റസൂൽ(സ): "ഇതിനേക്കാൾ നല്ലതെന്താ, നിനക്ക് സന്താനങ്ങളില്ലേ." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് ശുറൈഹ്, അബ്ദുല്ല, മുസ്‌ലിം എന്നീ മൂന്ന് സന്താനങ്ങളുണ്ട്. റസൂൽ(സ) ചോദിച്ചു: "അതിൽ മുതിർന്നവൻ ആരാണ്?" അദ്ദേഹം പറഞ്ഞു: ശുറൈഹ്. റസൂൽ(സ) പറഞ്ഞു: "അപ്പോൾ നീ അബൂശുറൈഹാണ്." അദ്ദേഹത്തിനും സന്താനത്തിനും വേണ്ടി റസൂൽ(സ) പ്രാർത്ഥിക്കുകയും ചെയ്തു. (ന)', 'هَانِئِ بْنِ يَزِيد', 'ഹാനിഉബ്നു യസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ، عَنِ الْفَضْلِ بْنِ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُمْ – أَنَّهُ كَانَ رَدِيفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَدَاةَ النَّحْرِ، فَأَتَتْهُ امْرَأَةٌ مِنْ خَثْعَمَ فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ فَرِيضَةَ اللهِ عَزَّ وَجَلَّ فِي الْحَجِّ عَلَى عِبَادِهِ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا، لَا يَسْتَطِيعُ أَنْ يَرْكَبَ إِلَّا مُعْتَرِضًا، أَفَأَحُجُّ عَنْهُ؟ قَالَ: "نَعَمْ، حُجِّي عَنْهُ، فَإِنَّهُ لَوْ كَانَ عَلَيْهِ دَيْنٌ قَضَيْتِيهِ". وَفِي رِوَايَةٍ: قَالَتْ: فَهَلْ يُجْزِئُ – يَقْضِي – أَنْ أَحُجَّ عَنْهُ؟ وَفِي رِوَايَةٍ: وَكَانَتِ امْرَأَةً حَسْنَاءَ – فَجَعَلَ الْفَضْلُ يَنْظُرُ إِلَيْهَا وَتَنْظُرُ إِلَيْهِ، وَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَرِّفُ وَجْهَ الْفَضْلِ إِلَى الشِّقِّ الْآخَرِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഫള്ലുബ്നു അബ്ബാസ്(റ)വിനെ സംബന്ധിച്ച് പറയുന്നു: ബലിപെരുന്നാൾ ദിനം രാവിലെ അദ്ദേഹം റസൂൽ(സ)യുടെ പിന്നിലിരിക്കുകയാണ്. അപ്പോൾ ഖസ്അം ഗോത്രത്തിൽ പെട്ട ഒരു സ്ത്രീ വന്നുപറഞ്ഞു: റസൂലേ, അല്ലാഹു തന്റെ അടിമകൾക്ക് നിർബന്ധമാക്കിയ ഹജ്ജ് എന്റെ പിതാവിനെത്തിയത് അദ്ദേഹം വളരെയധികം പ്രായമായപ്പോഴാണ്. ശരിക്ക് വാഹനം കയറാൻ അദ്ദേഹത്തിന് കഴിയില്ല. ഞാൻ അദ്ദേഹത്തിന് വേണ്ടി ഹജ്ജ് ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, അദ്ദേഹത്തിന് വേണ്ടി നീ ഹജ്ജ് ചെയ്യുക, കാരണം അദ്ദേഹത്തിന് കടമുണ്ടെങ്കിൽ വീട്ടേണ്ടത് നീയല്ലേ." മറ്റൊരു നിവേദനത്തിൽ: സ്ത്രീ ചോദിച്ചത് ഞാൻ ഖളാഅ് വീട്ടിയാൽ മതിയാകുമോ എന്നാണ്. മറ്റൊരു നിവേദനം: ആ സ്ത്രീ സുന്ദരിയായിരുന്നു. അപ്പോൾ ഫള്ൽ(റ) ആ സ്ത്രീയെയും ആ സ്ത്രീ ഫള്ൽ(റ)വിനെയും നോക്കാൻ തുടങ്ങി. റസൂൽ(സ) ഫള്ൽ(റ)വിന്റെ മുഖത്തെ മറുഭാഗത്തേക്ക് തിരിച്ചുകൊണ്ടിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ، عَنِ الْفَضْلِ بْنِ عَبَّاسٍ –', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 413, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=29), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: فَهَلْ يُجْزِئُ – يَقْضِي – أَنْ أَحُجَّ عَنْهُ؟', 'മറ്റൊരു നിവേദനത്തിൽ: സ്ത്രീ ചോദിച്ചത് ഞാൻ ഖളാഅ് വീട്ടിയാൽ മതിയാകുമോ എന്നാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=29), 2, 'وَفِي رِوَايَةٍ: وَكَانَتِ امْرَأَةً حَسْنَاءَ – فَجَعَلَ الْفَضْلُ يَنْظُرُ إِلَيْهَا وَتَنْظُرُ إِلَيْهِ، وَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَرِّفُ وَجْهَ الْفَضْلِ إِلَى الشِّقِّ الْآخَرِ. (ن)', 'മറ്റൊരു നിവേദനം: ആ സ്ത്രീ സുന്ദരിയായിരുന്നു. അപ്പോൾ ഫള്ൽ(റ) ആ സ്ത്രീയെയും ആ സ്ത്രീ ഫള്ൽ(റ)വിനെയും നോക്കാൻ തുടങ്ങി. റസൂൽ(സ) ഫള്ൽ(റ)വിന്റെ മുഖത്തെ മറുഭാഗത്തേക്ക് തിരിച്ചുകൊണ്ടിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّهُ قَدْ أَتَى عَلَيْنَا زَمَانٌ وَلَسْنَا نَقْضِي وَلَسْنَا هُنَالِكَ، ثُمَّ إِنَّ اللهَ عَزَّ وَجَلَّ قَدَّرَ عَلَيْنَا أَنْ بَلَغْنَا مَا تَرَوْنَ، فَمَنْ عَرَضَ لَهُ مِنْكُمْ قَضَاءٌ بَعْدَ الْيَوْمِ فَلْيَقْضِ بِمَا فِي كِتَابِ اللهِ، فَإِنْ جَاءَ أَمْرٌ لَيْسَ فِي كِتَابِ اللهِ فَلْيَقْضِ بِمَا قَضَى بِهِ نَبِيُّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِنْ جَاءَ أَمْرٌ لَيْسَ فِي كِتَابِ اللهِ وَلَا قَضَى بِهِ نَبِيُّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلْيَقْضِ بِمَا قَضَى بِهِ الصَّالِحُونَ، فَإِنْ جَاءَ أَمْرٌ لَيْسَ فِي كِتَابِ اللهِ وَلَا قَضَى بِهِ نَبِيُّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا قَضَى بِهِ الصَّالِحُونَ فَلْيَجْتَهِدْ رَأْيَهُ، وَلَا يَقُولُ: إِنِّي أَخَافُ وَإِنِّي أَخَافُ، فَإِنَّ الْحَلَالَ بَيِّنٌ وَالْحَرَامَ بَيِّنٌ، وَبَيْنَ ذَلِكَ أُمُورٌ مُشْتَبِهَاتٌ، فَدَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ വിധിക്കുകയോ ഞങ്ങൾക്ക് വിധിക്കാനർഹതയോ ഇല്ലാത്തൊരു കാലമുണ്ടായിരുന്നു. പിന്നെ അല്ലാഹു നിങ്ങളീ കാണുന്നപോലെ ഞങ്ങൾക്ക് കഴിവേകി. അതുകൊണ്ട് ഇന്നേ ദിവസത്തിന് ശേഷം നിങ്ങളിലാർക്കെങ്കിലും വല്ല വിധിയും വിധിക്കേണ്ടി വന്നാൽ അവൻ അല്ലാഹുവിന്റെ കിത്താബിലുള്ളത് പ്രകാരം വിധിച്ചുകൊള്ളുക. ഇനി അല്ലാഹുവിന്റെ കിതാബിലില്ലാത്ത കാര്യമാണ് വന്നതെങ്കിൽ അവൻ നബി(സ) വിധിച്ചത് കൊണ്ട് വിധിക്കട്ടെ. ഇനി അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലുള്ളതോ നബി(സ) വിധിച്ചതോ അല്ലാത്തൊരു വിഷയമാണ് വന്നതെങ്കിൽ സ്വാലിഹീങ്ങൾ വിധിച്ചതനുസരിച്ച് അവൻ വിധിക്കട്ടെ. ഇനി അല്ലാഹുവിന്റെ കിതാബിലുള്ളതോ നബി(സ) വിധിച്ചതോ സ്വാലിഹീങ്ങൾ വിധിച്ചതോ അല്ലാത്തൊരു വിഷയമാണ് വന്നതെങ്കിൽ അവൻ സ്വന്തം വിശകലനം ചെയ്യട്ടെ. എനിക്ക് പേടിയാണ്, എനിക്ക് പേടിയാണ് എന്ന് അവൻ പറയരുത്. കാരണം അനുവദനീയമായവ (ഹലാൽ) വ്യക്തമാണ്. ഹറാമായതും വ്യക്തമാണ്. അതിനിടയിൽ കുറച്ച് അവ്യക്തമായ കാര്യങ്ങളുണ്ട്. അതുകൊണ്ട് തന്നെ സംശയം ജനിപ്പിക്കുന്നതിനെ വിട്ട് നീ സംശയമില്ലാത്തതിനെ പിടിക്കുക. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ شُرَيْحِ بْنِ حَارِثٍ الْقَاضِي: أَنَّهُ كَتَبَ إِلَى عُمَرَ رَضِيَ اللهُ عَنْهُ يَسْأَلُهُ، فَكَتَبَ إِلَيْهِ: أَنِ اقْضِ بِمَا فِي كِتَابِ اللهِ، فَإِنْ لَمْ يَكُنْ فِي كِتَابِ اللهِ فَبِسُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِنْ لَمْ يَكُنْ فِي كِتَابِ اللهِ وَلَا فِي سُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاقْضِ بِمَا قَضَى بِهِ الصَّالِحُونَ، فَإِنْ لَمْ يَكُنْ فِي كِتَابِ اللهِ وَلَا فِي سُنَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَقْضِ بِهِ الصَّالِحُونَ: فَإِنْ شِئْتَ فَتَقَدَّمْ، وَإِنْ شِئْتَ فَتَأَخَّرْ، وَلَا أَرَى التَّأَخُّرَ إِلَّا خَيْرًا لَكَ، وَالسَّلَامُ عَلَيْكُمْ. (ن)', 'ശുറൈഹുബ്നുൽ ഹാരിസുൽ ഖാളീ(റ): അദ്ദേഹം ഉമർ(റ)വിന് ചില വിഷയങ്ങൾ ചോദിച്ചുകൊണ്ട് കത്തെഴുതി. അപ്പോൾ ഉമർ(റ) അദ്ദേഹത്തിന് മറുപടിയായി ഇപ്രകാരം എഴുതി: നീ അല്ലാഹുവിന്റെ കിതാബിലുള്ളതനുസരിച്ച് വിധിക്കുക. ഇനി അല്ലാഹുവിന്റെ കിതാബിലില്ലെങ്കിൽ റസൂലുല്ലാഹി(സ)യുടെ സുന്നത്തുകൊണ്ട് വിധിക്കുക. ഇനി അല്ലാഹുവിന്റെ കിത്താബിലോ റസൂൽ(സ)യുടെ സുന്നത്തിലോ ഇല്ലെങ്കിൽ സ്വാലിഹീങ്ങൾ വിധിച്ചതനുസരിച്ച് വിധിക്കുക. ഇനി അല്ലാഹുവിന്റെ കിത്താബിലോ റസൂലിന്റെ സുന്നത്തിലോ സ്വാലിഹീങ്ങൾ വിധിച്ചതിലോ ഇല്ലെങ്കിൽ നിനക്കിഷ്ടമെങ്കിൽ മുന്നോട്ടു പോകാം. നിനക്കിഷ്ടമെങ്കിൽ പിന്നോട്ട് നിൽക്കുകയും ചെയ്യാം. പിന്നിട്ട് നിൽക്കലാണ് നിനക്കുത്തമമായി ഞാൻ കാണുന്നത്. നിനക്ക് അല്ലാഹുവിന്റെ രക്ഷയുണ്ടായിരിക്കട്ടെ. (ന)', 'شُرَيْحِ بْنِ حَارِثٍ الْقَاضِي', 'ശുറൈഹുബ്നുൽ ഹാരിസുൽ ഖാളീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 414, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ قَالَ: كَتَبَ أَبِي وَكَتَبْتُ لَهُ إِلَى عُبَيْدِ اللهِ بْنِ أَبِي بَكْرَةَ، وَهُوَ قَاضٍ بِسِجِسْتَانَ: أَنْ لَا تَحْكُمَ بَيْنَ اثْنَيْنِ وَأَنْتَ غَضْبَانُ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَحْكُمْ أَحَدٌ بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ". (م)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്റ(റ): സിജിസ്താനിലെ ഖാളിയായ ഉബൈദില്ലാഹിബ്നു അബീബക്റ(റ)വിന് എന്റെ പിതാവ് ഒരു കത്തെഴുതി. പിതാവിന് വേണ്ടി ഞാനാണതെഴുതിയത്: നീ ദേഷ്യപ്പെട്ടവനായിരിക്കെ രണ്ട് ആളുകളുടെ ഇടയിൽ വിധി പറയരുത്. കാരണം റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ദേഷ്യപ്പെട്ടവനായിരിക്കെ ഒരാളും രണ്ടാളുകൾക്കിടയിൽ വിധി പറയരുത്." (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ قَالَ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്റ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا، عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ خَاصَمَ رَجُلًا مِنَ الْأَنْصَارِ – قَدْ شَهِدَ بَدْرًا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فِي شِرَاجِ الْحَرَّةِ، كَانَا يَسْقِيَانِ بِهِ كِلَاهُمَا النَّخْلَ، فَقَالَ الْأَنْصَارِيُّ: سَرِّحِ الْمَاءَ يَمُرُّ عَلَيْهِ، فَأَبَى عَلَيْهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ". فَغَضِبَ الْأَنْصَارِيُّ وَقَالَ: يَا رَسُولَ اللهِ، أَنْ كَانَ ابْنَ عَمَّتِكَ. فَتَلَوَّنَ وَجْهُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "يَا زُبَيْرُ، اسْقِ، ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ". فَاسْتَوْفَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلزُّبَيْرِ حَقَّهُ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ ذَلِكَ أَشَارَ عَلَى الزُّبَيْرِ بِرَأْيٍ فِيهِ السَّعَةُ لَهُ وَلِلْأَنْصَارِيِّ، فَلَمَّا أَحْفَظَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْأَنْصَارِيُّ اسْتَوْفَى لِلزُّبَيْرِ حَقَّهُ فِي صَرِيحِ الْحُكْمِ، قَالَ الزُّبَيْرُ: لَا أَحْسَبُ هَذِهِ الْآيَةَ أُنْزِلَتْ إِلَّا فِي ذَلِكَ: {فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ} [النساء: ٦٥]. (ن)', 'സുബൈറുബ്നുൽ അവ്വാം(റ)വിൽ നിന്നും അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ''ഹർറ''യിലെ (കറുത്ത ചരൽ നിറഞ്ഞ പ്രദേശത്തെ) വെള്ളച്ചാലിന്റെ വിഷയത്തിൽ റസൂൽ(സ)യോടൊപ്പം ബദ്റിൽ പങ്കെടുത്ത അൻസാരികളിലൊരാളോട് അദ്ദേഹം തർക്കിച്ചു. അവർ രണ്ടുപേരും അതിൽനിന്നായിരുന്നു ഈത്തപ്പനകൾ നനച്ചിരുന്നത്. അൻസാരി പറഞ്ഞു: വെള്ളത്തെ ഒഴുകാനനുവദിക്ക്. പക്ഷേ, സുബൈർ(റ) വിസമ്മതിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "സുബൈറേ, നീ നനച്ച ശേഷം നിന്റെ അയൽക്കാരനിലേക്ക് വിട്ടയക്കുക." അപ്പോൾ അൻസാരിക്ക് ദേഷ്യം പിടിച്ചു. അദ്ദേഹം റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ അമ്മായിയുടെ മകനായതു കൊണ്ടാണോ ഇങ്ങനെ വിധിച്ചത്? റസൂൽ(സ)യുടെ മുഖം വിവർണ്ണമായി. ശേഷം അവിടുന്ന് പറഞ്ഞു: "സുബൈറേ, നീ നനക്കുക. പിന്നെ ഈത്തപ്പനയുടെ തടത്തിലേക്ക് വരുന്നതു വരെ വെള്ളം തടഞ്ഞുനിർത്തുക." നബി(സ) സുബൈർ(റ)വിന് തന്റെ അവകാശം പൂർണ്ണമായി കൊടുത്തു. റസൂൽ(സ) അതിനു മുമ്പ് സുബൈർ(റ)വിനോട് തനിക്കും അൻസാരിക്കും സൗകര്യപ്രദമായൊരു രീതി ചൂണ്ടിക്കാണിച്ചിരുന്നു. പക്ഷേ, അൻസാരി നബി(സ)യെ ദേഷ്യംപിടിപ്പിച്ചപ്പോൾ വ്യക്തമായ വിധിയിൽ സുബൈർ(റ)വിന് തന്റെ അവകാശം പൂർണ്ണമായി കൊടുത്തു. സുബൈർ(റ) പറഞ്ഞു: ഈ വിഷയം സംബന്ധിച്ചു തന്നെയാണ് ''അല്ല, അങ്ങയുടെ രക്ഷിതാവിനെത്തന്നെയാണ് സത്യം, അവരുടെ ഇടയിൽ ഉടലെടുത്തൊരു വിഷയത്തിൽ അവിടത്തെ വിധികർത്താവാക്കുന്നതു വരെ അവർ മുഅ്മിനാവുകയില്ല.'' (നിസാഅ്: 65) എന്ന സൂക്തമവതരിച്ചതെന്നാണ് ഞാൻ കരുതുന്നത്. (ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'സുബൈറുബ്നുൽ അവ്വാം(റ)', null, null, array['ن']::text[], array['ന']::text[], 'النساء: ٦٥', null, 415, 416, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عُمَارَةَ بْنِ خُزَيْمَةَ: أَنَّ عَمَّهُ حَدَّثَهُ، وَهُوَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ابْتَاعَ فَرَسًا مِنْ أَعْرَابِيٍّ، فَاسْتَتْبَعَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيَقْضِيَهُ ثَمَنَ فَرَسِهِ، فَأَسْرَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَشْيَ وَأَبْطَأَ الْأَعْرَابِيُّ، فَطَفِقَ رِجَالٌ يَعْتَرِضُونَ الْأَعْرَابِيَّ فَيُسَاوِمُونَهُ بِالْفَرَسِ، وَلَا يَشْعُرُونَ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ابْتَاعَهُ، فَنَادَى الْأَعْرَابِيُّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنْ كُنْتَ مُبْتَاعًا هَذَا الْفَرَسَ وَإِلَّا بِعْتُهُ. فَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ سَمِعَ نِدَاءَ الْأَعْرَابِيِّ فَقَالَ: "أَوَ لَيْسَ قَدِ ابْتَعْتُهُ مِنْكَ". فَقَالَ الْأَعْرَابِيُّ: لَا، وَاللهِ مَا بِعْتُكَهُ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَلَى قَدِ ابْتَعْتُهُ مِنْكَ". فَطَفِقَ الْأَعْرَابِيُّ يَقُولُ: هَلُمَّ شَهِيدًا، فَقَالَ خُزَيْمَةُ بْنُ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: أَنَا أَشْهَدُ أَنَّكَ قَدْ بَايَعْتَهُ. فَأَقْبَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى خُزَيْمَةَ فَقَالَ: "بِمَ تَشْهَدُ". فَقَالَ: بِتَصْدِيقِكَ يَا رَسُولَ اللهِ. فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهَادَةَ خُزَيْمَةَ بِشَهَادَةِ رَجُلَيْنِ. (د,ن)', 'ഉമാറതുബ്നു ഖുസൈമ(റ): നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട അദ്ദേഹത്തിന്റെ പിതൃവ്യപുത്രൻ അദ്ദേഹത്തോട് പറഞ്ഞു: നബി(സ) ഒരു അഅ്റാബിയിൽ നിന്നും ഒരു കുതിരയെ വാങ്ങി. നബി(സ) അയാളോട് അതിന്റെ വിലയെടുക്കാൻ വേണ്ടി തന്നെ പിന്തുടരാൻ ആവശ്യപ്പെട്ടു. റസൂൽ(സ) വേഗം നടന്നു. പക്ഷേ, അഅ്റാബി പതുക്കെയാണ് പോയത്. അപ്പോൾ കുറച്ചാളുകൾ അയാളുടെ അടുത്തുവന്ന് കുതിരയെ വിലപേശാൻ തുടങ്ങി. നബി(സ) ഇതിനെ വാങ്ങിയ വിവരം അവരറിയില്ല. അപ്പോൾ അഅ്റാബി ഉച്ചത്തിൽ നബി(സ)യെ വിളിച്ചു പറഞ്ഞു: അങ്ങ് ഈ കുതിരയെ വാങ്ങുന്നുവോ? ഇല്ലെങ്കിൽ ഞാൻ ഈ കുതിരയെ വിൽക്കുകയാണ്. അഅ്റാബിയുടെ വിളി കേട്ടപ്പോൾ നബി(സ) നിന്നു. എന്നിട്ട് ചോദിച്ചു: "ഞാനിതിനെ നിന്നിൽ നിന്ന് വാങ്ങിയിട്ടില്ലേ?" അഅ്റാബി പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ് സത്യം, ഞാനിത് അങ്ങേക്ക് വിറ്റിട്ടില്ല. നബി(സ) പറഞ്ഞു: "അല്ല, ഞാനതിനെ നിന്നിൽ നിന്നും വാങ്ങിയിട്ടുണ്ട്." അഅ്റാബി പറയാൻ തുടങ്ങി: സാക്ഷിയെ കൊണ്ടുവരൂ. അപ്പോൾ ഖുസൈമതുബ്നു സാബിത്(റ) പറഞ്ഞു: അങ്ങത് വാങ്ങിയിട്ടുണ്ടെന്നതിന് ഞാൻ സാക്ഷി നിൽക്കുന്നു. അപ്പോൾ ഖുസൈമയിലേക്ക് തിരിഞ്ഞ് നബി(സ) ചോദിച്ചു: "എന്തുകൊണ്ടാണ് നീ സാക്ഷിനിൽക്കുന്നത്?" ഖുസൈമ(റ) പറഞ്ഞു: റസൂലേ, അങ്ങയെ വാസ്തവമാക്കിക്കൊണ്ടാണ്. അപ്പോൾ റസൂൽ(സ) ഖുസൈമ(റ)വിന്റെ സാക്ഷിത്വം രണ്ട് സാക്ഷികളുടെ സ്ഥാനത്താക്കി. (ദ,ന)', 'عُمَارَةَ بْنِ خُزَيْمَةَ', 'ഉമാറതുബ്നു ഖുസൈമ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 416, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا امْرَأَتَانِ مَعَهُمَا ابْنَاهُمَا جَاءَ الذِّئْبُ فَذَهَبَ بِابْنِ إِحْدَاهُمَا، فَقَالَتْ هَذِهِ لِصَاحِبَتِهَا: إِنَّمَا ذَهَبَ بِابْنِكِ. وَقَالَتِ الْأُخْرَى: إِنَّمَا ذَهَبَ بِابْنِكِ. فَتَحَاكَمَتَا إِلَى دَاوُدَ عَلَيْهِ السَّلَامِ، فَقَضَى بِهِ لِلْكُبْرَى، فَخَرَجَتَا إِلَى سُلَيْمَانَ بْنِ دَاوُدَ فَأَخْبَرَتَاهُ، فَقَالَ: ائْتُونِي بِالسِّكِّينِ أَشُقُّهُ بَيْنَهُمَا. فَقَالَتِ الصُّغْرَى: لَا تَفْعَلْ يَرْحَمُكَ اللهُ، هُوَ ابْنُهَا. فَقَضَى بِهِ لِلصُّغْرَى". قَالَ أَبُو هُرَيْرَةَ: وَاللهِ مَا سَمِعْتُ بِالسِّكِّينِ قَطُّ إِلَّا يَوْمَئِذٍ، مَا كُنَّا نَقُولُ إِلَّا الْمُدْيَةَ. وَفِي رِوَايَةٍ: "قَالَ سُلَيْمَانُ: أَقْطَعُهُ بِنِصْفَيْنِ: لِهَذِهِ نِصْفٌ وَلِهَذِهِ نِصْفٌ. قَالَتِ الْكُبْرَى: نَعَمِ اقْطَعُوهُ. فَقَالَتِ الصُّغْرَى: لَا تَقْطَعْهُ، هُوَ وَلَدُهَا. فَقَضَى بِهِ لِلَّتِي أَبَتْ أَنْ يَقْطَعَهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് സ്ത്രീകൾ തങ്ങളുടെ കുട്ടികളുമായി പോകുമ്പോൾ ചെന്നായ വന്ന് ഒരുത്തിയുടെ കുട്ടിയെ കൊണ്ടുപോയി. അപ്പോൾ ആ സ്ത്രീ തന്റെ കൂട്ടുകാരിയോട് പറഞ്ഞു: നിന്റെ കുട്ടിയെയാണ് ചെന്നായ കൊണ്ടുപോയത്. മറ്റെ സ്ത്രീ പറഞ്ഞു: നിന്റെ കുട്ടിയെയാണ് കൊണ്ടുപോയത്. അവർ രണ്ടുപേരും ദാവൂദ്(അ)മിന്റെ അടുത്തേക്ക് വിധി തേടി ചെന്നു. ദാവൂദ്(അ) അവരിലെ വലിയവൾക്ക് കുട്ടിയെ വിധിച്ചു. അങ്ങനെ അവർ സുലൈമാൻ നബി(അ)മിന്റെ സന്നിധിയിൽ ചെന്ന് വിവരം പറഞ്ഞു. സുലൈമാൻ(അ) പറഞ്ഞു: നിങ്ങൾ കത്തി കൊണ്ടുവരൂ, കുട്ടിയെ ഞാനവർക്കിടയിൽ മുറിച്ച് വീതിക്കാം. അപ്പോൾ ചെറിയവൾ പറഞ്ഞു: അങ്ങത് ചെയ്യരുത്. അല്ലാഹു അങ്ങേക്ക് റഹ്മത്ത് ചെയ്യട്ടെ. അത് അവളുടെ കുട്ടിയാണ്. അപ്പോൾ സുലൈമാൻ(അ) കുട്ടിയെ ചെറിയവൾക്ക് വിധിച്ചു." അബൂഹുറൈറ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, സിക്കീൻ എന്ന പദം ആ സമയത്തല്ലാതെ അതുവരെ ഞാൻ കേട്ടിട്ടില്ല. ഞങ്ങൾ കത്തിക്ക് മുദ്‌യ എന്നാണ് പറയാറ്. മറ്റൊരു നിവേദനം: "സുലൈമാൻ(അ) പറഞ്ഞു: അവനെ പകുതിയായി ഞാൻ മുറിക്കുകയാണ്. പകുതി ഇവൾക്ക്, പകുതി അവൾക്ക്. വലിയവൾ പറഞ്ഞു: അങ്ങ് മുറിച്ചോളൂ. ചെറിയവൾ പറഞ്ഞു: അങ്ങ് അവനെ മുറിക്കരുത്. അത് അവളുടെ കുട്ടിയാണ്. അപ്പോൾ വെട്ടാൻ വിസമ്മതിച്ചവൾക്ക് കുട്ടിയെ വിധിച്ചു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=35), 1, 'وَفِي رِوَايَةٍ: "قَالَ سُلَيْمَانُ: أَقْطَعُهُ بِنِصْفَيْنِ: لِهَذِهِ نِصْفٌ وَلِهَذِهِ نِصْفٌ. قَالَتِ الْكُبْرَى: نَعَمِ اقْطَعُوهُ. فَقَالَتِ الصُّغْرَى: لَا تَقْطَعْهُ، هُوَ وَلَدُهَا. فَقَضَى بِهِ لِلَّتِي أَبَتْ أَنْ يَقْطَعَهُ". (ن)', 'മറ്റൊരു നിവേദനം: "സുലൈമാൻ(അ) പറഞ്ഞു: അവനെ പകുതിയായി ഞാൻ മുറിക്കുകയാണ്. പകുതി ഇവൾക്ക്, പകുതി അവൾക്ക്. വലിയവൾ പറഞ്ഞു: അങ്ങ് മുറിച്ചോളൂ. ചെറിയവൾ പറഞ്ഞു: അങ്ങ് അവനെ മുറിക്കരുത്. അത് അവളുടെ കുട്ടിയാണ്. അപ്പോൾ വെട്ടാൻ വിസമ്മതിച്ചവൾക്ക് കുട്ടിയെ വിധിച്ചു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَالِدَ بْنَ الْوَلِيدِ إِلَى بَنِي جَذِيمَةَ فَدَعَاهُمْ إِلَى الْإِسْلَامِ، فَلَمْ يُحْسِنُوا أَنْ يَقُولُوا: أَسْلَمْنَا، فَجَعَلُوا يَقُولُونَ: صَبَأْنَا، وَجَعَلَ خَالِدٌ قَتْلًا وَأَسْرًا، قَالَ: فَدَفَعَ إِلَى كُلِّ رَجُلٍ أَسِيرَهُ، حَتَّى إِذَا أَصْبَحَ يَوْمُنَا أَمَرَ خَالِدُ بْنُ الْوَلِيدِ أَنْ يَقْتُلَ كُلُّ رَجُلٍ مِنَّا أَسِيرَهُ، قَالَ ابْنُ عُمَرَ: فَقُلْتُ: وَاللهِ لَا أَقْتُلُ أَسِيرِي وَلَا يَقْتُلُ أَحَدٌ وَقَالَ بِشْرٌ مِنْ أَصْحَابِي أَسِيرَهُ. قَالَ: فَقَدِمْنَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذُكِرَ لَهُ صُنْعُ خَالِدٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَفَعَ يَدَيْهِ: "اللَّهُمَّ إِنِّي أَبْرَأُ إِلَيْكَ مِمَّا صَنَعَ خَالِدٌ" مَرَّتَيْنِ. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഖാലിദുബ്നുൽ വലീദ്(റ)വിനെ ബനൂജദീമയിലേക്കയച്ചു. അദ്ദേഹമവരെ ഇസ്‌ലാമിലേക്ക് ക്ഷണിച്ചു. പക്ഷേ, അവർ ഞങ്ങൾ മുസ്‌ലിമായി എന്ന് വ്യക്തമായി പറയാൻ തയ്യാറായില്ല. മറിച്ച് അവർ പറയാൻ തുടങ്ങി: ''സ്വബഅ്നാ'' (പ്രപിതാക്കന്മാരുടെ മതത്തിൽ നിന്നും ഞങ്ങൾ മാറിയിരിക്കുന്നു). അനന്തരം ഖാലിദ്(റ) കൊല്ലാനും ബന്ധിയാക്കാനും തുടങ്ങി. ഇബ്നുഉമർ(റ) പറയുന്നു: അങ്ങനെ ഓരോരുത്തർക്കും ഓരോ ബന്ധിയെ നൽകി. ശേഷം ഞങ്ങളുടെ ദിവസമായപ്പോൾ ഖാലിദ്(റ) ഓരോരുത്തരോടും അവരവരുടെ ബന്ധിയെ വധിക്കാൻ കൽപിച്ചു. ഇബ്നുഉമർ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹു സത്യം, ഞാനോ എന്റെ അനുചരരിലൊരാളോ തന്റെ ബന്ധിയെ കൊല്ലുകയില്ല. അങ്ങനെ ഞങ്ങൾ നബി(സ)യുടെ അടുത്തുചെന്നു. ഖാലിദ്(റ) ചെയ്തത് തിരുമേനി(സ)യോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) തന്റെ കൈ ഉയർത്തി രണ്ട് പ്രാവശ്യം ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവേ, ഖാലിദ്(റ) ചെയ്തതിൽ നിന്നും നിന്നോട് ഞാൻ മോക്ഷം തേടുന്നു." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 417, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدِ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَحَدُهُمَا: اقْضِ بَيْنَنَا بِكِتَابِ اللهِ. وَقَالَ الْآخَرُ، وَهُوَ أَفْقَهُهُمَا: أَجَلْ يَا رَسُولَ اللهِ، وَأْذَنْ لِي فِي أَنْ أَتَكَلَّمَ. قَالَ: إِنَّ ابْنِي كَانَ عَسِيفًا عَلَى هَذَا، فَزَنَى بِامْرَأَتِهِ، فَأَخْبَرُونِي أَنَّ عَلَى ابْنِي الرَّجْمَ، فَافْتَدَيْتُ بِمِائَةِ شَاةٍ وَبِجَارِيَةٍ لِي، ثُمَّ إِنِّي سَأَلْتُ أَهْلَ الْعِلْمِ فَأَخْبَرُونِي: أَنَّمَا عَلَى ابْنِي جَلْدُ مِائَةٍ وَتَغْرِيبُ عَامٍ، وَإِنَّمَا الرَّجْمُ عَلَى امْرَأَتِهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ لَأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللهِ: أَمَّا غَنَمُكَ وَجَارِيَتُكَ فَرَدٌّ إِلَيْكَ". وَجَلَدَ ابْنَهُ مِائَةً وَغَرَّبَهُ عَامًا، وَأَمَرَ أُنَيْسًا أَنْ يَأْتِيَ امْرَأَةَ الْآخَرِ: "فَإِنِ اعْتَرَفَتْ فَارْجُمْهَا". فَاعْتَرَفَتْ فَرَجَمَهَا. (ن)', 'അബൂഹുറൈറ(റ), സൈദുബ്നു ഖാലിദുൽ ജുഹനി(റ): രണ്ടാളുകൾ തർക്കിച്ചുകൊണ്ട് റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്നു. ഒരാൾ പറഞ്ഞു: ഞങ്ങൾക്കിടയിൽ അങ്ങ് അല്ലാഹുവിന്റെ കിതാബനുസരിച്ച് വിധിക്കുക. അവരിൽ ഏറ്റവും വിവരമുള്ള മറ്റെയാൾ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കൊന്ന് സംസാരിക്കാനവസരം തന്നാലും. അയാൾ പറഞ്ഞുതുടങ്ങി: എന്റെ മകൻ ഇയാളുടെ കൂലിപ്പണിക്കാരനായിരുന്നു. അവൻ ഇയാളുടെ ഭാര്യയെ വ്യഭിചരിച്ചു. എന്റെ മകന്റെ ശിക്ഷ അവനെ കല്ലെറിഞ്ഞുകൊല്ലലാണെന്നവർ എന്നോട് പറഞ്ഞു. അപ്പോൾ ഞാൻ നഷ്ടപരിഹാരമായി (ഭർത്താവിന്) നൂറ് ആടിനെയും എന്റെ ഒരു അടിമസ്ത്രീയെയും നൽകി. പിന്നെ ഞാൻ വിവരമുള്ളവരോട് ചോദിച്ചപ്പോൾ അവർ പറഞ്ഞു: എന്റെ മകനുള്ള ശിക്ഷ നൂറ് അടിയും ഒരു വർഷം നാടുകടത്തലുമാണ്. കല്ലെറിഞ്ഞുകൊല്ലേണ്ടത് ഇവന്റെ ഭാര്യയെയാണെന്ന്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കരങ്ങളിലാണോ അവനാണ് സത്യം, നിശ്ചയം നിങ്ങൾക്കിടയിൽ ഞാൻ അല്ലാഹുവിന്റെ കിതാബ് കൊണ്ട് വിധിക്കുന്നു: അതായത് നിന്റെ ആടിനെയും അടിമസ്ത്രീയെയും നീ തിരിച്ചെടുക്കുക." അയാളുടെ മകനെ നൂറ് അടി അടിക്കുകയും ഒരു വർഷത്തേക്ക് നാട് കടത്തുകയും ചെയ്തു. മറ്റെയാളുടെ ഭാര്യയെ കൊണ്ടുവരാൻ കൂട്ടുകാരനോട് കൽപിച്ചു: "അവൾ സമ്മതിച്ചാൽ അവളെ എറിഞ്ഞുകൊല്ലുക." അവൾ സമ്മതിച്ചപ്പോൾ അവളെ എറിഞ്ഞുകൊന്നു. (ന)', 'أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدِ الْجُهَنِيِّ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 418, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الصُّلْحُ جَائِزٌ بَيْنَ الْمُسْلِمِينَ، إِلَّا صُلْحًا حَرَّمَ حَلَالًا أَوْ أَحَلَّ حَرَامًا. وَالْمُسْلِمُونَ عَلَى شُرُوطِهِمْ، إِلَّا شَرْطًا حَرَّمَ حَلَالًا أَوْ أَحَلَّ حَرَامًا". حَسَنٌ صَحِيحٌ. (ت,جه)', 'അംറുബ്നു ഔഫിൽ മുസ്നീ(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രശ്നപരിഹാരം മുസ്‌ലിംകൾക്കിടയിൽ അനുവദനീയമാണ്, ഹലാലിനെ ഹറാമാക്കുകയോ ഹറാമിനെ ഹലാലാക്കുകയോ ചെയ്യുന്ന പരിഹാരമൊഴിച്ച്. മുസ്‌ലിംകൾ അവരുടെ നിബന്ധനകളോട് കൂടെയാണ്, ഹറാമിനെ ഹലാലോ ഹലാലിനെ ഹറാമോ ആക്കുന്ന ഉപാധികളൊഴിച്ച്." (തു,ജ)', 'عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ', 'അംറുബ്നു ഔഫിൽ മുസ്നീ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 418, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ تَقَاضَى ابْنَ أَبِي حَدْرَدٍ دَيْنًا كَانَ عَلَيْهِ، فَارْتَفَعَتْ أَصْوَاتُهُمَا حَتَّى سَمِعَهُمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي بَيْتِهِ، فَخَرَجَ إِلَيْهِمَا، فَكَشَفَ سِتْرَ حُجْرَتِهِ فَنَادَى: "يَا كَعْبُ". قَالَ: لَبَّيْكَ يَا رَسُولَ اللهِ، قَالَ: "ضَعْ مِنْ دَيْنِكَ هَذَا" وَأَوْمَأَ إِلَى الشَّطْرِ، قَالَ: قَدْ فَعَلْتُ. قَالَ: "قُمْ فَاقْضِهِ". (ن)', 'കഅ്ബുബ്നു മാലിക്(റ): അദ്ദേഹത്തിന് ഇബ്നുഅബീഹ്ദ്റദ് കൊടുക്കാനുണ്ടായിരുന്ന കടം അദ്ദേഹം തിരിച്ചുചോദിച്ചു. രണ്ടുപേരുടെയും ശബ്ദം ഉച്ചത്തിലായപ്പോൾ നബി(സ) വീട്ടിലിരിക്കെ അതുകേട്ടു. നബി(സ) അവരെ ലക്ഷ്യമാക്കി പുറപ്പെട്ടു. വീടിന്റെ വിരി നീക്കി വിളിച്ചു: "കഅ്ബേ." കഅ്ബ്(റ) പറഞ്ഞു: റസൂലേ, അങ്ങേക്ക് ഞാനുത്തരം നൽകുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ കടത്തിൽ നിന്ന് ഇത്ര നീ ചുരുക്കിനൽകുക" പകുതി ഭാഗത്തേക്ക് ചൂണ്ടിപ്പറഞ്ഞു. കഅ്ബ്(റ) പറഞ്ഞു: അത് ഞാൻ ചെയ്തോളാം. റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ നീ എണീറ്റ് അതു വീട്ടുക." (ന)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 419, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبَّادِ بْنِ شُرَحْبِيلَ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ مَعَ عُمُومَتِي الْمَدِينَةَ، فَدَخَلْتُ حَائِطًا مِنْ حِيطَانِهَا، فَفَرَكْتُ مِنْ سُنْبُلِهِ، فَجَاءَ صَاحِبُ الْحَائِطِ فَأَخَذَ كِسَائِي وَضَرَبَنِي، فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَسْتَعْدِي عَلَيْهِ، فَأَرْسَلَ إِلَى الرَّجُلِ فَجَاءُوا بِهِ، فَقَالَ: "مَا حَمَلَكَ عَلَى هَذَا". فَقَالَ: يَا رَسُولَ اللهِ، إِنَّهُ دَخَلَ حَائِطِي فَأَخَذَ مِنْ سُنْبُلِهِ فَفَرَكَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا عَلَّمْتَهُ إِذْ كَانَ جَاهِلًا، وَلَا أَطْعَمْتَهُ إِذْ كَانَ جَائِعًا. ارْدُدْ عَلَيْهِ كِسَاءَهُ". وَأَمَرَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِوَسْقٍ أَوْ نِصْفِ وَسْقٍ. (ن)', 'അബ്ബാദുബ്നു ശുറഹ്ബീൽ(റ): ഞാനെന്റെ എളാപ്പയോടു കൂടെ മദീനയിൽ വന്നപ്പോൾ അവിടത്തെ തോട്ടങ്ങളിലൊരു തോട്ടത്തിൽ പ്രവേശിച്ച് ഒരു കുലയിൽ നിന്നും പറിച്ചു. അപ്പോൾ തോട്ടക്കാരൻ വന്ന് എന്റെ മുണ്ട് പിടിക്കുകയും എന്നെ അടിക്കുകയും ചെയ്തു. സഹായം തേടി ഞാൻ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്നു. അപ്പോൾ അവിടുന്ന് അയാളെ കൊണ്ടുവരാൻ ആളെ അയക്കുകകയും കൊണ്ടുവരികയും ചെയ്തു. റസൂൽ(സ) ആ തോട്ടക്കാരനോട് ചോദിച്ചു: "നിന്നെ ഇപ്രകാരം ചെയ്യാൻ പ്രേരിപ്പിച്ചതെന്താണ്?" അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, ഇവൻ എന്റെ തോട്ടത്തിൽ കടന്ന് അതിലെ കുലയിൽ നിന്നും പറിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൻ അറിയാതിരുന്ന സമയത്ത് നീ അവനെ പഠിപ്പിച്ചില്ല. വിശന്ന സമയത്ത് നീ അവനെ ഭക്ഷിപ്പിച്ചതുമില്ല. ഇവന്റെ മുണ്ട് നീ തിരിച്ചുകൊടുക്കുക." ഒരു വസ്ഖോ അല്ലെങ്കിൽ അര വസ്ഖോ എനിക്ക് നൽകാൻ അവിടുന്ന് കൽപിക്കുകയും ചെയ്തു. (ന)', 'عَبَّادِ بْنِ شُرَحْبِيلَ', 'അബ്ബാദുബ്നു ശുറഹ്ബീൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 419, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَجُلًا يَقْرَأُ آيَةً سَمِعْتُ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خِلَافَهَا، فَأَخَذْتُ بِيَدِهِ فَأَتَيْتُ بِهِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "كِلَاكُمَا مُحْسِنٌ، لَا تَخْتَلِفُوا فَإِنَّ مَنْ كَانَ قَبْلَكُمُ اخْتَلَفُوا فَهَلَكُوا". (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരു മനുഷ്യൻ ഖുർആനിലെ ഒരു കാര്യം ഓതുന്നത് ഞാൻ കേട്ടു. തിരുമേനി(സ) അതിൽനിന്ന് തികച്ചും വ്യത്യസ്തമായാണ് ഓതിയിരുന്നത്. അയാളുടെ കൈ പിടിച്ച്കൊണ്ട് ഞാൻ തിരുമേനി(സ)യുടെ അടുക്കൽ ചെന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ട്പേരും ഓതിയത് ശരിതന്നെയാണ്. പരസ്പരം ഭിന്നിക്കരുത്. നിങ്ങൾക്ക് മുമ്പുള്ളവർ നശിച്ചത് ഭിന്നിപ്പ് കാരണത്താലാണ്." (ബു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 420, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَبَّ رَجُلَانِ, رَجُلٌ مِنَ الْمُسْلِمِينَ، وَرَجُلٌ مِنَ الْيَهُودِ, قَالَ الْمُسْلِمُ: وَالَّذِي اصْطَفَى مُحَمَّدًا عَلَى الْعَالَمِينَ، فَقَالَ الْيَهُودِيُّ: وَالَّذِي اصْطَفَى مُوسَى عَلَى الْعَالَمِينَ، فَرَفَعَ الْمُسْلِمُ يَدَهُ عِنْدَ ذَلِكَ فَلَطَمَ وَجْهَ الْيَهُودِيِّ، فَذَهَبَ الْيَهُودِيُّ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِمَا كَانَ مِنْ أَمْرِهِ وَأَمْرِ الْمُسْلِمِ، فَدَعَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمَ فَسَأَلَهُ عَنْ ذَلِكَ فَأَخْبَرَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُخَيِّرُونِي عَلَى مُوسَى، فَإِنَّ النَّاسَ يَصْعَقُونَ يَوْمَ الْقِيَامَةِ فَأَصْعَقُ مَعَهُمْ، فَأَكُونُ أَوَّلَ مَنْ يُفِيقُ فَإِذَا مُوسَى بَاطِشٌ جَانِبَ الْعَرْشِ فَلَا أَدْرِي أَكَانَ فِيمَنْ صَعِقَ فَأَفَاقَ قَبْلِي، أَوْ كَانَ مِمَّنِ اسْتَثْنَى اللهُ". (خ)', 'അബൂഹുറൈറ(റ): ഒരു ജൂതനും ഒരു മുസ്‌ലിമും പരസ്പരം ശകാരിച്ചു. ലോകരിൽവെച്ച് മുഹമ്മദ്(സ)യെ ഉൽകൃഷ്ടരായി തെരഞ്ഞെടുത്തവനെത്തന്നെ സത്യം എന്ന് മുസ്‌ലിം സത്യം ചെയ്തു. അത് കേട്ടപ്പോൾ ലോകരിൽവെച്ച് മൂസാ(അ)നെ ഉൽകൃഷ്ടരായി തെരഞ്ഞെടുത്തവനെത്തന്നെ സത്യം എന്ന് ജൂതനും സത്യം ചെയ്തു. ഉടനെ മുസ്‌ലിം കൈ പൊക്കി ജൂതന്റെ മുഖത്തടിച്ചു. ജൂതൻ നബി(സ)യുടെ മുമ്പിൽ ചെന്ന് പരാതി പറയുകയും സംഭവങ്ങൾ വിവരിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) മുസ്‌ലിമിനെ വിളിക്കുകയും കാര്യം തിരക്കുകയും അദ്ദേഹം സംഭവങ്ങൾ വിവരിക്കുകയും ചെയ്തു. അന്നേരം നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എന്നെ മൂസാ(അ)നെക്കാൾ ശ്രേഷ്ഠനാക്കി വെക്കരുത്. പുനരുത്ഥാന നാളിൽ ജനങ്ങളെല്ലാം ബോധരഹിതരായി വീഴുമ്പോൾ അക്കൂട്ടത്തിൽ ഞാനും വീഴും. ഏറ്റവുമാദ്യം ബോധം തിരിച്ചുകിട്ടുന്നത് എനിക്കായിരിക്കും. അപ്പോൾ മൂസാ(അ) അർശിന്റെ ഒരു ഭാഗം പിടിച്ചുകൊണ്ട് നിൽക്കുന്നുണ്ടാകും. ബോധരഹിതനായി എന്റെ മുമ്പുതന്നെ ബോധം തിരിച്ചുകിട്ടിയതോ, അതല്ല ബോധരഹിതനാകുന്നതിൽ നിന്ന് അല്ലാഹു അദ്ദേഹത്തെ ഒഴിച്ചുനിർത്തിയതോ എന്താണെന്ന് എനിക്ക് അറിയില്ല." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 420, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ يَهُودِيًّا رَضَّ رَأْسَ جَارِيَةٍ بَيْنَ حَجَرَيْنِ، قِيلَ: مَنْ فَعَلَ هَذَا بِكِ؟ أَفُلَانٌ؟ أَفُلَانٌ؟ حَتَّى سُمِّيَ الْيَهُودِيُّ فَأَوْمَأَتْ بِرَأْسِهَا، فَأُخذَ الْيَهُودِيُّ فَاعْتَرَفَ، فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرُضَّ رَأْسُهُ بَيْنَ حَجَرَيْنِ. (خ)', 'അനസ്(റ): ഒരു ജൂതൻ ഒരു പെൺകുട്ടിയുടെ തല രണ്ട് കല്ലുകൾക്കിടയിൽ വെച്ച് കുത്തിച്ചതച്ചു. നിന്നെ ഇപ്രകാരം ദ്രോഹിച്ചതാരാണ്? ഇന്നവനോ?... ഇന്നവനോ? എന്ന് ആ പെൺകുട്ടിയോട് ചോദിക്കപ്പെട്ടു. അവസാനം ജൂതന്റെ പേരെടുത്ത് ചോദിച്ചപ്പോൾ അവൻ തന്നെയെന്ന് അവൾ തല കൊണ്ട് ആംഗ്യം കാണിച്ചു. ഉടനെ ജൂതനെ പിടികൂടുകയും അവൻ കുറ്റം സമ്മതിക്കുകയും ചെയ്തു. അപ്പോൾ അവന്റെ തലയും രണ്ട് കല്ലിനിടയിൽ വെച്ച് ചതക്കാൻ നബി(സ) കൽപിച്ചു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 420, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اشْتَرَى رَجُلٌ مِنْ رَجُلٍ عَقَارًا لَهُ، فَوَجَدَ الرَّجُلُ الَّذِي اشْتَرَى الْعَقَارَ فِي عَقَارِهِ جَرَّةً فِيهَا ذَهَبٌ، فَقَالَ لَهُ الَّذِي اشْتَرَى الْعَقَارَ: خُذْ ذَهَبَكَ مِنِّي، إِنَّمَا اشْتَرَيْتُ مِنْكَ الْأَرْضَ وَلَمْ أَبْتَعْ مِنْكَ الذَّهَبَ، فَقَالَ الَّذِي شَرَى الْأَرْضَ: إِنَّمَا بِعْتُكَ الْأَرْضَ وَمَا فِيهَا. قَالَ: فَتَحَاكَمَا إِلَى رَجُلٍ، فَقَالَ الَّذِي تَحَاكَمَا إِلَيْهِ: أَلَكُمَا وَلَدٌ؟ فَقَالَ أَحَدُهُمَا: لِي غُلَامٌ، وَقَالَ الْآخَرُ: لِي جَارِيَةٌ، قَالَ: أَنْكِحُوا الْغُلَامَ الْجَارِيَةَ، وَأَنْفِقُوا عَلَى أَنْفُسِكُمَا مِنْهُ وَتَصَدَّقَا". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ മറ്റൊരാളിൽ നിന്ന് ഭൂമി വാങ്ങി. വാങ്ങിയവന് ആ ഭൂമിയിൽ നിന്ന് സ്വർണ്ണം നിറച്ച ഒരു കൊട്ട കിട്ടി. അയാൾ വിറ്റ ആളോട് പറഞ്ഞു: നിന്റെ സ്വർണ്ണം എന്നിൽ നിന്നെടുക്കുക. ഞാൻ നിന്റെ ഭൂമി മാത്രമാണ് വാങ്ങിയത്. സ്വർണ്ണം വാങ്ങിയിട്ടില്ല. അപ്പോൾ വിറ്റവൻ പറഞ്ഞു: ഞാൻ നിനക്ക് ഭൂമി വിറ്റത് അതിലെന്തൊക്കെയുണ്ടോ അതോടുകൂടിയാണ്. അങ്ങനെ അവർ വിധിതീർക്കാൻ ഒരാളുടെ അടുത്ത് പോയി. അയാൾ ചോദിച്ചു: നിങ്ങൾക്ക് സന്താനമുണ്ടോ? ഒരാൾ പറഞ്ഞു: എനിക്കൊരു ആൺകുട്ടിയുണ്ട്. മറ്റെയാൾ പറഞ്ഞു: എനിക്കൊരു പെൺകുട്ടിയുണ്ട്. അയാൾ പറഞ്ഞു: എന്നാൽ ഈ പെൺകുട്ടിയെ ആൺകുട്ടിയുമായി വിവാഹം കഴിപ്പിക്കുക. നിങ്ങൾ നിങ്ങൾക്ക് വേണ്ടി അതിൽ നിന്ന് ചെലവാക്കുകയും സ്വദഖ നൽകുകയും ചെയ്യുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَهْلَ قُبَاءٍ اقْتَتَلُوا حَتَّى تَرَامَوْا بِالْحِجَارَةِ، فَأُخْبِرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ، فَقَالَ: "اذْهَبُوا بِنَا نُصْلِحُ بَيْنَهُمْ". (خ)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): ഖുബാഅ് നിവാസികൾ പരസ്പരം പോരാടി. കല്ലേറ് വരെ എത്തിയപ്പോൾ നബി(സ)ക്ക് വിവരമറിയിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "നമ്മെ കൊണ്ടുപോവുക, നമുക്ക് അവർക്കിടയിൽ സന്ധിയുണ്ടാക്കാം." (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَوْتَ خُصُومٍ بِالْبَابِ عَالِيَةٍ أَصْوَاتُهُمَا، وَإِذَا أَحَدُهُمَا يَسْتَوْضِعُ الْآخَرَ وَيَسْتَرْفِقُهُ فِي شَيْءٍ، وَهُوَ يَقُولُ: وَاللهِ لَا أَفْعَلُ. فَخَرَجَ عَلَيْهِمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَيْنَ الْمُتَأَلِّي عَلَى اللهِ لَا يَفْعَلُ الْمَعْرُوفَ". فَقَالَ: أَنَا يَا رَسُولَ اللهِ، فَلَهُ أَيُّ ذَلِكَ أَحَبَّ. (خ)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ വീട്ടുവാതിലിനടുത്ത് രണ്ടാളുകൾ തർക്കിക്കുന്ന ഉച്ചത്തിലുള്ള ശബ്ദം കേട്ടു. അതിലൊരാൾ മറ്റെയാളോട് കടത്തിൽ അൽപം ഇളവ് ചെയ്യാനും ദയ കാണിക്കാനും ആവശ്യപ്പെടുന്നു. പക്ഷേ, മറ്റെയാൾ പറയുന്നു: അല്ലാഹുവാണ് സത്യം, ഞാനത് ചെയ്യില്ല. അപ്പോൾ നബി(സ) അവരുടെ ഇടയിലേക്ക് ചെന്ന് ചോദിച്ചു: "നന്മ ചെയ്യില്ലെന്ന് അല്ലാഹുവിന്റെ പേരിൽ സത്യം ചെയ്ത് പറയുന്നവനെവിടെ?" അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനാണ്. അവന് അതിൽ ആഗ്രഹിക്കുന്നതെന്തും ചെയ്യാം. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 421, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: وَقَعَ بَيْنَ حَيَّيْنِ مِنَ الْأَنْصَارِ كَلَامٌ حَتَّى تَرَامَوْا بِالْحِجَارَةِ، فَذَهَبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيُصْلِحَ بَيْنَهُمْ، فَحَضَرَتِ الصَّلَاةُ فَأَذَّنَ بِلَالٌ وَانْتُظِرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاحْتُبِسَ، فَأَقَامَ الصَّلَاةَ وَتَقَدَّمَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ، فَجَاءَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ يُصَلِّي بِالنَّاسِ، فَلَمَّا رَآهُ النَّاسُ صَفَّحُوا، وَكَانَ أَبُو بَكْرٍ لَا يَلْتَفِتُ فِي الصَّلَاةِ، فَلَمَّا سَمِعَ تَصْفِيحَهُمُ الْتَفَتَ فَإِذَا هُوَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَرَادَ أَنْ يَتَأَخَّرَ فَأَشَارَ إِلَيْهِ: أَنِ اثْبُتْ. فَرَفَعَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ يَعْنِي يَدَيْهِ ثُمَّ نَكَصَ الْقَهْقَرَى، وَتَقَدَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى، فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ قَالَ: "مَا مَنَعَكَ أَنْ تَثْبُتَ". قَالَ: مَا كَانَ اللهُ لِيَرَى ابْنَ أَبِي قُحَافَةَ بَيْنَ يَدَيْ نَبِيِّهِ. ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: "مَا لَكُمْ إِذَا نَابَكُمْ شَيْءٌ فِي صَلَاتِكُمْ صَفَّحْتُمْ؟ إِنَّ ذَلِكَ لِلنِّسَاءِ. مَنْ نَابَهُ شَيْءٌ فِي صَلَاتِهِ فَلْيَقُلْ: سُبْحَانَ اللهِ". (ن)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ): അൻസാറുകളിൽപ്പെട്ട രണ്ട് ഗോത്രങ്ങൾക്കിടയിൽ, പരസ്പരം കല്ലെടുത്തെറിയുമാറ് വാക്കേറ്റമുണ്ടായി. അവരുടെ ഇടയിൽ സന്ധിയുണ്ടാക്കാൻ റസൂൽ(സ) പോയി. നിസ്കാരത്തിന്റെ സമയമായപ്പോൾ ബിലാൽ(റ) ബാങ്ക് വിളിച്ചു. റസൂൽ(സ)യെ പ്രതീക്ഷിച്ചിരുന്നെങ്കിലും നബി(സ) വളരെ വൈകി. അങ്ങനെ നമസ്കാരത്തിന് ഇഖാമത്ത് കൊടുക്കുകയും അബൂബക്കർ(റ) ഇമാമായി നിൽക്കുകയും ചെയ്തു. അങ്ങനെ അബൂബക്കർ(റ) ജനങ്ങൾക്ക് ഇമാമായി നിസ്ക്കരിച്ചു കൊണ്ടിരിക്കെ റസൂൽ(സ) വന്നു. റസൂൽ(സ)യെ കണ്ടപ്പോൾ അവർ കയ്യടിച്ചു. അബൂബക്കർ(റ) നിസ്കാരത്തിൽ തിരിഞ്ഞ് നോക്കാറില്ലായിരുന്നു, അവരുടെ കയ്യടി കേട്ടപ്പോൾ തിരിഞ്ഞ് നോക്കി. അപ്പോഴതാ, റസൂൽ(സ) വന്നിരിക്കുന്നു. അബൂബക്കർ(റ) പിന്നോട്ട് നിൽക്കാൻ ഉദ്ദേശിച്ചെങ്കിലും അവിടെത്തന്നെ നിൽക്കാൻ റസൂൽ(സ) ആംഗ്യം കാണിച്ചു. അപ്പോൾ അബൂബക്കർ(റ) കൈകൾ രണ്ടുമുയർത്തി പിന്നോട്ടുനിന്നു. അങ്ങനെ റസൂൽ(സ) ഇമാമായി നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അവിടെത്തന്നെ നിൽക്കാതിരുന്നതെന്തിനായിരുന്നു?" അബൂബക്കർ(റ) പറഞ്ഞു: ഖുഹാഫയുടെ മകന് തന്റെ പ്രവാചകന് മുന്നിൽ നിൽക്കാൻ അല്ലാഹു യോഗ്യത നൽകിയിട്ടില്ല. പിന്നെ ജനങ്ങളിലേക്ക് തിരിഞ്ഞ് റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളുടെ നിസ്കാരത്തിൽ വല്ലതും സംഭവിച്ചാൽ എന്താ നിങ്ങൾ കയ്യടിക്കുന്നത്? അത് സ്ത്രീകൾക്കുള്ളതല്ലേ. ഒരുത്തന് തന്റെ നിസ്കാരത്തിൽ വല്ലതും സംഭവിച്ചാൽ അവൻ ''സുബ്ഹാനല്ലാ'' എന്ന് പറയട്ടെ." (ന)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَتَبَ إِلَى ابْنِهِ قَالَ: قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّ الْخَصْمَيْنِ يَقْعُدَانِ بَيْنَ يَدَيِ الْحَكَمِ. (د)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): അദ്ദേഹം തന്റെ മകനെഴുതി: ഇരു കക്ഷികളും വിധികർത്താവിന് മുന്നിൽ ഇരിക്കണമെന്ന് റസൂൽ(സ) വിധിച്ചിട്ടുണ്ട്. (ദ)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَقَاضَى إِلَيْكَ رَجُلَانِ فَلَا تَقْضِ لِلأَوَّلِ حَتَّى تَسْمَعَ كَلَامَ الآخَرِ، فَسَوْفَ تَدْرِي كَيْفَ تَقْضِي". قَالَ عَلِيٌّ: فَمَا زِلْتُ قَاضِيًا بَعْدُ. حَسَنٌ. (د,ت)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടാളുകൾ വിധി തേടി നിന്റെ അടുത്ത് വന്നാൽ രണ്ടാമത്തെയാളുടെ സംസാരം കേൾക്കാതെ ആദ്യത്തെയാൾക്ക് നീ വിധിക്കരുത്. (അത് കേട്ടാൽ) എങ്ങനെ വിധിക്കണമെന്ന് നിനക്കറിയാം." അലി(റ) പറഞ്ഞു: അതിനുശേഷം ഞാൻ വിധികർത്താവായി കൊണ്ടിരുന്നു. (ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِامْرَأَةٍ قَدْ زَنَتْ، فَقَالَ: "مِمَّنْ". قَالَتْ: مِنَ الْمُقْعَدِ الَّذِي فِي حَائِطِ سَعْدٍ. فَأَرْسَلَ إِلَيْهِ فَأُتِيَ بِهِ مَحْمُولًا. فَوُضِعَ بَيْنَ يَدَيْهِ، فَاعْتَرَفَ، فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِثْكَالٍ فَضَرَبَهُ، وَرَحِمَهُ لِزَمَانَتِهِ وَخَفَّفَ عَنْهُ. (ن)', 'അബൂഉമാമതുബ്നു സഹ്ൽ(റ): നബി(സ)യുടെ സമീപം വ്യഭിചരിച്ച ഒരു സ്ത്രീയെ കൊണ്ടുവന്നു. റസൂൽ(സ) ചോദിച്ചു: "ആരുമായാണ് വ്യഭിചരിച്ചത്?" അവൾ പറഞ്ഞു: സഅ്ദിന്റെ തോട്ടത്തിലെ ആ നടക്കാൻ കഴിയാത്ത മനുഷ്യനുമായി. അങ്ങനെ നബി(സ) അയാളിലേക്ക് ആളെ അയച്ചു. അയാളെ ചുമന്നുകൊണ്ടുവന്നു. റസൂൽ(സ) അയാളിലേക്ക് ആളെ അയച്ചു. അയാളെ ചുമന്നുകൊണ്ടുവന്നു. റസൂൽ(സ)യുടെ മുന്നിൽ വെച്ചു. അയാൾ കുറ്റം സമ്മതിച്ചു. അപ്പോൾ റസൂൽ(സ) ഈത്തപ്പനയുടെ കുല കൊണ്ടുവരാൻ പറഞ്ഞു. അതുകൊണ്ട് അയാളെ അടിക്കുകയും ചെയ്തു. അദ്ദേഹത്തിന്റെ നിത്യരോഗം കാരണം റസൂൽ(സ) അയാളോട് കരുണ കാണിക്കുകയും ശിക്ഷ ലഘൂകരിക്കുകയും ചെയ്തു. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلٍ', 'അബൂഉമാമതുബ്നു സഹ്ൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي أُمَامَةَ إِيَاسِ بْنِ ثَعْلَبَةَ الْبَلَوِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ، وَحَرَّمَ عَلَيْهِ الْجَنَّةَ". فَقَالَ لَهُ رَجُلٌ: وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ؟ قَالَ: "وَإِنْ كَانَ قَضِيبًا مِنْ أَرَاكٍ". (ن)', 'അബൂഉമാമ ഇയാസുബ്നു സഅ്ലബത്തിൽ ബലവി(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ വലതു കൈ കൊണ്ട് മുസ്ലിമായ ഒരാളുടെ വല്ല അവകാശവും അപഹരിച്ചാൽ നിശ്ചയം അവന് അല്ലാഹു നരകം നിർബന്ധമാക്കുകയും അവന്റെ മേൽ സ്വർഗ്ഗം നിഷിദ്ധമാക്കുകയും ചെയ്തിരിക്കുന്നു." അപ്പോൾ അവിടത്തോടൊരാൾ ചോദിച്ചു: അതൊരു നിസ്സാരകാര്യമാണെങ്കിലും അങ്ങനെത്തന്നെയാണോ റസൂലേ? അവിടന്ന് പറഞ്ഞു: "അത് അറാക്കിന്റെ കഷ്ണമാണെങ്കിലും ശരി." (ന)', 'أَبِي أُمَامَةَ إِيَاسِ بْنِ ثَعْلَبَةَ الْبَلَوِيِّ', 'അബൂഉമാമ ഇയാസുബ്നു സഅ്ലബത്തിൽ ബലവി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَتْ هِنْدٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ أَبَا سُفْيَانَ رَجُلٌ شَحِيحٌ، وَلَا يُنْفِقُ عَلَيَّ وَوَلَدِي مَا يَكْفِينِي، أَفَآخُذُ مِنْ مَالِهِ وَلَا يَشْعُرُ؟ قَالَ: "خُذِي مَا يَكْفِيكِ وَوَلَدَكِ بِالْمَعْرُوفِ". (ن)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് ഹിന്ദ്(റ) വന്നു. അവർ പറഞ്ഞു: റസൂലേ, നിശ്ചയം അബൂസുഫ്യാൻ പിശുക്കനായ ഒരാളാണ്. എനിക്കും എന്റെ കുഞ്ഞിനും കൂടി എനിക്ക് തികയുന്നത്ര പോലും ചെലവാക്കുന്നില്ല. അതിനാൽ അദ്ദേഹമറിയാതെ അദ്ദേഹത്തിന്റെ സമ്പത്തിൽ നിന്ന് ഞാൻ എടുക്കട്ടെയോ? അവിടന്നരുളി: "നിനക്കും നിന്റെ കുഞ്ഞിനും തികയുന്നത് നല്ല രീതിയിൽ നീ എടുക്കുക." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 423, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ، وَكَانَ عَامِلًا عَلَى سِجِسْتَانَ، قَالَ: كَتَبَ إِلَيَّ أَبُو بَكْرَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَقْضِيَنَّ أَحَدٌ فِي قَضَاءٍ بِقَضَاءَيْنِ، وَلَا يَقْضِي أَحَدٌ بَيْنَ خَصْمَيْنِ وَهُوَ غَضْبَانُ". (ن)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്റ(റ): അദ്ദേഹം സിജിസ്താനിലെ ഭരണാധികാരിയായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അബൂബക്റ(റ) എനിക്ക് ഇങ്ങനെ പറയുന്നതായി എഴുതി: റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാളും ഒരു പ്രശ്നത്തിൽ രണ്ട് വിധികൾ ഒരിക്കലും വിധിക്കരുത്. ഒരാളും രണ്ട് പ്രതിയോഗികൾക്കിടയിൽ ദേഷ്യപ്പെട്ടവനായി വിധിക്കരുത്." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ، وَكَانَ عَامِلًا عَلَى سِجِسْتَانَ، قَالَ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ وَائِلٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ جَاءَ بِالْقَاتِلِ يَقُودُهُ وَلِيُّ الْمَقْتُولِ فِي نِسْعَةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِوَلِيِّ الْمَقْتُولِ: "أَتَعْفُو". قَالَ: لَا. قَالَ: "فَتَأْخُذَ الدِّيَةَ". قَالَ: لَا. قَالَ: "فَتَقْتُلُهُ". قَالَ: نَعَمْ. قَالَ: "اذْهَبْ بِهِ". فَلَمَّا ذَهَبَ فَوَلَّى مِنْ عِنْدِهِ دَعَاهُ فَقَالَ: "أَتَعْفُو". قَالَ: لَا. قَالَ: "فَتَأْخُذُ الدِّيَةَ". قَالَ: لَا. قَالَ: "فَتَقْتُلُهُ". قَالَ: نَعَمْ. قَالَ: "اذْهَبْ بِهِ". فَلَمَّا ذَهَبَ فَوَلَّى مِنْ عِنْدِهِ دَعَاهُ فَقَالَ: "أَتَعْفُو". قَالَ: لَا. قَالَ: "فَتَأْخُذُ الدِّيَةَ". قَالَ: لَا. قَالَ: "فَتَقْتُلُهُ". قَالَ: نَعَمْ. قَالَ: "اذْهَبْ بِهِ". فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: "أَمَا إِنَّكَ إِنْ عَفَوْتَ عَنْهُ يَبُوءُ بِإِثْمِهِ وَإِثْمِ صَاحِبِكَ". فَعَفَا عَنْهُ وَتَرَكَهُ، فَأَنَا رَأَيْتُهُ يَجُرُّ نِسْعَتَهُ. (ن)', 'വാഇൽ(റ): ഒട്ടകപ്പട്ടയുടെ തോൽവാറിലായി ഘാതകനെ കൊല്ലപ്പെട്ടവന്റെ കൈകാര്യകർത്താക്കൾ കൊണ്ടുവന്നപ്പോൾ ഞാൻ റസൂൽ(സ)യെ കണ്ടു. റസൂൽ(സ) കൊല്ലപ്പെട്ടവന്റെ രക്ഷിതാവിനോട് ചോദിച്ചു: "നിങ്ങൾ മാപ്പ് നൽകുന്നോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് ചോദിച്ചു: "എന്നാൽ നഷ്ടപരിഹാരം വാങ്ങുന്നുവോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് ചോദിച്ചു: "അപ്പോൾ നിങ്ങൾ അവനെ കൊല്ലുന്നുവോ?" അയാൾ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "അവനെ നിങ്ങൾ കൊണ്ടുപോകുക." അയാൾ പോവുകയും തന്റയടുത്തുനിന്ന് തിരിയുകയും ചെയ്തപ്പോൾ അവിടന്ന് അയാളെ വിളിച്ചു. എന്നിട്ട് പറഞ്ഞു: "നിങ്ങൾ മാപ്പ് നൽകുന്നുവോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് ചോദിച്ചു: "എന്നാൽ നഷ്ടപരിഹാരം വാങ്ങുന്നുവോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അവിടന്ന് ചോദിച്ചു: "അപ്പോൾ അവനെ വധിക്കണമോ?" അയാൾ പറഞ്ഞു: അതെ. അവിടന്നരുളി: "എന്നാൽ നിങ്ങൾ അവനെ കൊണ്ടുപോവുക." അങ്ങനെ അയാൾ പോവുകയും അവിടത്തെ പിരിയുകയും ചെയ്തപ്പോൾ അവിടന്ന് അയാളെ വിളിച്ചു ചോദിച്ചു: "നിങ്ങൾ അവന് മാപ്പ്നൽകുന്നുവോ?" അയാൾ പറഞ്ഞു: ഇല്ല. തിരുമേനി(സ) ചോദിച്ചു: "എന്നാൽ നിങ്ങൾ നഷ്ടപരിഹാരം വാങ്ങുമോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് ചോദിച്ചു: "അപ്പോൾ നിങ്ങൾ അയാളെ വധിക്കുന്നുവോ?" അയാൾ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അവനെ കൊണ്ടുപോകുക." അന്നേരം നബി(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങൾ അവന് മാപ്പ് നൽകുകയാണെങ്കിൽ നിങ്ങളുടെയാളുടെ കുറ്റത്തിനും ഇവന്റെ കുറ്റത്തിനും അത് പകരമാകുന്നതാണ്." അപ്പോൾ അയാൾ അവന് മാപ്പ്നൽകുകയും വെറുതെവിടുകയും ചെയ്തു. അങ്ങനെ അയാൾ തന്റെ തോൽവാറ് വലിക്കുന്നത് വലിച്ചുപോകുന്നത് ഞാൻ കണ്ടു. (ന)', 'وَائِلٍ', 'വാഇൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 424, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ خَاصَمَ الزُّبَيْرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ، فَقَالَ الْأَنْصَارِيُّ: سَرِّحِ الْمَاءَ يَمُرُّ. فَأَبَى عَلَيْهِ، فَاخْتَصَمُوا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ". فَغَضِبَ الْأَنْصَارِيُّ فَقَالَ: يَا رَسُولَ اللَّهِ، أَنْ كَانَ ابْنَ عَمَّتِكَ. فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: "يَا زُبَيْرُ، اسْقِ ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ". قَالَ الزُّبَيْرُ: إِنِّي أَحْسَبُ أَنَّ هَذِهِ الْآيَةَ نَزَلَتْ فِي ذَلِكَ: {فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ} الْآيَةَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): അൻസാറുകളിൽപ്പെട്ട ഒരാൾ സുബൈർ(റ)വിനോട്, തങ്ങൾ ഈത്തപ്പന നനക്കാറുണ്ടായിരുന്ന കൽപ്രദേശത്തെ വെള്ളച്ചാലിന്റെ കാര്യത്തിൽ തർക്കിച്ച് റസൂലുല്ലാഹി(സ)യിലേക്കെത്തി. അപ്പോൾ ആ അൻസാരി പറഞ്ഞു: ആ വെള്ളം ഒഴുക്കിവിടുക. അപ്പോൾ അദ്ദേഹം അനുവദിച്ചില്ല. അങ്ങനെ റസൂൽ(സ)യുടെ അടുക്കൽ തർക്കിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "സുബൈറേ, നീ വെള്ളം നനക്കുക. പിന്നീട് ആ വെള്ളം നിന്റെ അയൽവാസിയിലേക്ക് ഒഴിക്കുക." അപ്പോൾ ആ അൻസാരി ദേഷ്യപ്പെട്ട് പറഞ്ഞു: റസൂലേ, അദ്ദേഹം അങ്ങയുടെ പിതൃസഹോദരി പുത്രനായതുകൊണ്ടല്ലയോ അപ്രകാരം വിധിച്ചത്? അപ്പോൾ റസൂലുല്ലാഹി(സ)യുടെ മുഖം വിവർണ്ണമായി. പിന്നീട് അവിടുന്ന് പറഞ്ഞു: "സുബൈറേ, നീ നനക്കുക. പിന്നീട് വേലികളിലേക്ക് മടങ്ങും വരെ ആ വെള്ളം പിടിച്ചുവെക്കുക." സുബൈർ(റ) പറഞ്ഞു: നിശ്ചയം ഈ വിഷയത്തിലാണ് ഈ സൂക്തമിറങ്ങിയതെന്ന് ഞാൻ വിചാരിക്കുന്നു: ''ഇല്ല നബിയേ, താങ്കളുടെ രക്ഷിതാവിനെ തന്നെ സത്യം, അവർ വിശ്വസിക്കുകയില്ല.'' (ന)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ حَاكِمٍ يَحْكُمُ بَيْنَ النَّاسِ إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ وَمَلَكٌ آخِذٌ بِقَفَاهُ، ثُمَّ يَرْفَعُ رَأْسَهُ إِلَى السَّمَاءِ، فَإِنْ قَالَ: أَلْقِهِ، أَلْقَاهُ فِي مَهْوَاةٍ أَرْبَعِينَ خَرِيفًا". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾക്കിടയിൽ വിധികൽപിക്കുന്ന ഒരു വിധികർത്താവുമില്ല, ഒരു മലക് തന്റെ പിരടി പിടിച്ച നിലയിൽ അന്ത്യനാളിൽ അവൻ വന്നിട്ടല്ലാതെ. പിന്നീട് ആ മലക് അവന്റെ തല ആകാശത്തിലേക്കുയർത്തും. അവനെ ഇടുക എന്ന് പറയപ്പെട്ടാൽ നാൽപത് വർഷക്കാലം (ദൈർഘ്യമുള്ള) പിളർപ്പിലേക്ക് അവനെ ഇടുന്നതാണ്." (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ مَعَ الْقَاضِي مَا لَمْ يَجُرْ، فَإِذَا جَارَ وَكَلَهُ إِلَى نَفْسِهِ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): റസൂൽ(സ) പറഞ്ഞു: "അക്രമം കാണിക്കാത്ത കാലമത്രയും അല്ലാഹു തീർച്ചയായും വിധികർത്താവിന്റെ കൂടെയാണ്. അയാൾ അക്രമം കാണിക്കുന്നുവെങ്കിൽ അയാളെ അല്ലാഹു അയാളിലേക്ക് തന്നെ ഏൽപിക്കുന്നതാണ്." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّاشِيَ وَالْمُرْتَشِيَ فِي الْحُكْمِ. حسن صحيح. (د,ت)', 'അബൂഹുറൈറ(റ): വിധിയിൽ കൈക്കൂലി നൽകുന്നവനെയും വാങ്ങുന്നവനെയും റസൂലുല്ലാഹി(സ) ശപിച്ചിരിക്കുന്നു. (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ، فَلَمَّا سِرْتُ أَرْسَلَ فِي أَثَرِي فَرُدِدْتُ، فَقَالَ: "أَتَدْرِي لِمَ بَعَثْتُ إِلَيْكَ؟ لَا تُصِيبَنَّ شَيْئًا بِغَيْرِ إِذْنِي، فَإِنَّهُ غُلُولٌ، وَمَنْ يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيَامَةِ، لِهَذَا دَعَوْتُكَ، فَامْضِ لِعَمَلِكَ". حسن. (ت)', 'മുആദുബ്നു ജബൽ(റ): റസൂലുല്ലാഹി(സ) എന്നെ യമനിലേക്ക് അയച്ചു. അങ്ങനെ ഞാൻ യാത്ര ചെയ്തപ്പോൾ അവിടന്ന് എന്റെ പിന്നിലായി ആളെ അയച്ചു. ഞാൻ തിരികെ വിളിക്കപ്പെട്ടു. അപ്പോൾ അവിടന്ന് എന്നോട് പറഞ്ഞു: "താങ്കൾക്കറിയാമോ ഞാനെന്തിനാണ് താങ്കളിലേക്ക് ആളെ അയച്ചതെന്ന്? താങ്കൾ എന്നോട് ചോദിക്കാതെ ഒന്നും സ്വീകരിക്കരുത്. കാരണം, നിശ്ചയം അത് ഒളിപ്പിച്ച് വെക്കലാണ്. ആരെങ്കിലും ഒളിപ്പിച്ചുവെച്ചാൽ അന്ത്യനാളിൽ താൻ ഒളിപ്പിച്ച വസ്തുവുമായി വരും. ഇതിനാണ് ഞാൻ നിങ്ങളെ വിളിപ്പിച്ചത്. ഇനി താങ്കൾ താങ്കളുടെ ജോലിക്കായി പൊയ്ക്കൊള്ളുക." (തു)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَدِيِّ بْنِ عُمَيْرَةَ الْكِنْدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا أَيُّهَا النَّاسُ، مَنْ عُمِّلَ مِنْكُمْ لَنَا عَلَى عَمَلٍ، فَكَتَمَنَا مِنْهُ مِخْيَطًا فَمَا فَوْقَهُ". فَهُوَ غُلٌّ يَأْتِي بِهِ يَوْمَ الْقِيَامَةِ". فَقَامَ رَجُلٌ مِنَ الْأَنْصَارِ أَسْوَدُ، كَأَنِّي أَنْظُرُ إِلَيْهِ، فَقَالَ: يَا رَسُولَ اللَّهِ، اقْبَلْ عَنِّي عَمَلَكَ. قَالَ: "وَمَا ذَاكَ". قَالَ: سَمِعْتُكَ تَقُولُ كَذَا وَكَذَا، قَالَ: "وَأَنَا أَقُولُ ذَلِكَ، مَنِ اسْتَعْمَلْنَاهُ عَلَى عَمَلٍ فَلْيَأْتِ بِقَلِيلِهِ وَكَثِيرِهِ، فَمَا أُوتِيَ مِنْهُ أَخَذَهُ، وَمَا نُهِيَ عَنْهُ انْتَهَى". (د)', 'അദിയ്യുബ്നു ഉമൈറതിനിൽ കിന്ദീ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ജനങ്ങളേ, നിങ്ങളിൽ നിന്ന് വല്ലവനും നമുക്ക് വേണ്ടി വല്ല ഉദ്യോഗത്തിലും നിയമിതനാവുകയും അങ്ങനെ അതിൽപ്പെട്ട ഒരു തുന്നൽ സൂചിയോ അതിനപ്പുറമുള്ളതോ നമ്മിൽ നിന്ന് മറച്ചുവെക്കുകയും ചെയ്താൽ അത് ഒളിപ്പിച്ച് വെക്കപ്പെട്ടതാണ്. അവൻ അന്ത്യനാളിൽ അത് കൊണ്ടുവരികയും ചെയ്യും." അപ്പോൾ അൻസാരികളിൽ പ്പെട്ട ഒരു കറുത്തയാൾ - ഇപ്പോഴും ഞാൻ അയാളിലേക്ക് നോക്കുന്നത് പോലെയുണ്ട് - എഴുന്നേറ്റ് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്നിൽ നിന്നും അവിടത്തെ ഉദ്യോഗം പിൻവലിച്ചാലും. അവിടന്ന് ചോദിച്ചു: "എന്തിന്?" അദ്ദേഹം പറഞ്ഞു: അങ്ങ് ഇന്നാലിന്നത് പറയുന്നത് ഞാൻ കേട്ടു. അവിടന്ന് പറഞ്ഞു: "ഞാൻ അക്കാര്യം പറയുന്നു: നാം വല്ലവരെയും വല്ല ഉദ്യോഗവും ഏൽപിച്ചിട്ടുണ്ടെങ്കിൽ അവൻ അതിന്റെ കുറഞ്ഞതും കൂടുതലും കൊണ്ടുവരട്ടെ. അതിൽനിന്ന് അവന് നൽകപ്പെടുന്നത് അവനെടുക്കട്ടെ. അവന്ന് നിഷേധിക്കപ്പെട്ടതിൽ നിന്ന് അവൻ വിട്ടുനിൽക്കുകയും ചെയ്യട്ടെ." (ദ)', 'عَدِيِّ بْنِ عُمَيْرَةَ الْكِنْدِيِّ', 'അദിയ്യുബ്നു ഉമൈറതിനിൽ കിന്ദീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 426, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِيَمِينٍ وَشَاهِدٍ. وَفِي رِوَايَةٍ: فِي الْحُقُوقِ. (م,د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂലുല്ലാഹി(സ) ഒരു സാക്ഷിയെക്കൊണ്ടും സത്യം ചെയ്യൽ കൊണ്ടും വിധി പറയുകയുണ്ടായി. ഒരു റിപ്പോർട്ടിൽ: അവകാശങ്ങളിൽ. (മു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=61), 1, 'وَفِي رِوَايَةٍ: فِي الْحُقُوقِ. (م,د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ سُرَّقٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجَازَ شَهَادَةَ الرَّجُلِ وَيَمِينَ الطَّالِبِ. [ز: فيه مجهول] (جه)', 'സുർറഖ്(റ): ഒരു പുരുഷന്റെ സാക്ഷിത്വവും, തേടുന്നവന്റെ സത്യം ചെയ്യലും നബി(സ) അനുവദിച്ചിരിക്കുന്നു. (സനദിൽ അറിയപ്പെടാത്തയാളുണ്ട്) (ദ)', 'سُرَّقٍ', 'സുർറഖ്(റ)', null, null, array['جه']::text[], array['ദ']::text[], 'ز: فيه مجهول', null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنِ الزُّبَيْبِ بْنِ ثَعْلَبَةَ رَضِيَ اللهُ عَنْهُ: بَعَثَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَيْشًا إِلَى بَنِي الْعَنْبَرِ، فَأَخَذُوهُمْ بِرَكْبَةٍ مِنْ نَاحِيَةِ الطَّائِفِ، فَاسْتَاقُوهُمْ إِلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَكِبْتُ فَسَبَقْتُهُمْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: السَّلَامُ عَلَيْكَ يَا نَبِيَّ اللَّهِ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، أَتَانَا جُنْدُكَ فَأَخَذُونَا، وَقَدْ كُنَّا أَسْلَمْنَا وَخَضْرَمْنَا آذَانَ النَّعَمِ، فَلَمَّا قَدِمَ بَنُو الْعَنْبَرِ قَالَ لِي نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكُمْ بَيِّنَةٌ عَلَى أَنَّكُمْ أَسْلَمْتُمْ قَبْلَ أَنْ تُؤْخَذُوا فِي هَذِهِ الْأَيَّامِ". قُلْتُ: نَعَمْ، قَالَ: "مَنْ بَيِّنَتُكَ". قُلْتُ: سَمُرَةُ – رَجُلٌ مِنْ بَنِي الْعَنْبَرِ – وَرَجُلٌ آخَرُ سَمَّاهُ لَهُ، فَشَهِدَ الرَّجُلُ، وَأَبَى سَمُرَةُ أَنْ يَشْهَدَ، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أَبَى أَنْ يَشْهَدَ لَكَ، فَتَحْلِفُ مَعَ شَاهِدِكَ الْآخَرِ". قُلْتُ: نَعَمْ، فَاسْتَحْلَفَنِي، فَحَلَفْتُ بِاللَّهِ لَقَدْ أَسْلَمْنَا يَوْمَ كَذَا وَكَذَا، وَخَضْرَمْنَا آذَانَ النَّعَمِ. فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اذْهَبُوا، فَقَاسِمُوهُمْ أَنْصَافَ الْأَمْوَالِ، وَلَا تَمَسُّوا ذَرَارِيَّهُمْ، لَوْلَا أَنَّ اللَّهَ لَا يُحِبُّ ضَلَالَةَ الْعَمَلِ مَا رَزَيْنَاكُمْ عِقَالًا". قَالَ الزُّبَيْبُ: فَدَعَتْنِي أُمِّي. فَقَالَتْ: هَذَا الرَّجُلُ أَخَذَ زَرْبِيَّتِي. فَانْصَرَفْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَعْنِي فَأَخْبَرْتُهُ، فَقَالَ لِي: "احْبِسْهُ". فَأَخَذْتُ بِتَلْبِيبِهِ، وَقُمْتُ مَعَهُ مَكَانَنَا، ثُمَّ نَظَرَ إِلَيْنَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمَيْنِ، فَقَالَ: "مَا تُرِيدُ بِأَسِيرِكَ". فَأَرْسَلْتُهُ مِنْ يَدِي، فَقَامَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِلرَّجُلِ: "رُدَّ عَلَى هَذَا زَرْبِيَّةَ أُمِّهِ الَّتِي أَخَذْتَ مِنْهَا". فَقَالَ: يَا نَبِيَّ اللَّهِ، إِنَّهَا خَرَجَتْ مِنْ يَدِي. قَالَ: فَاخْتَلَعَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَيْفَ الرَّجُلِ فَأَعْطَانِيهِ، وَقَالَ لِلرَّجُلِ: "اذْهَبْ، فَزِدْهُ آصُعًا مِنْ طَعَامٍ". قَالَ: فَزَادَنِي آصُعًا مِنْ شَعِيرٍ. (د)', 'സുബൈബുബ്നു സഅ്ലബ(റ): ബനുൽ അൻബറിലേക്ക് ഒരു സൈന്യത്തെ തിരുനബി(സ) അയച്ചു. ത്വാഇഫിന്റെ പ്രാന്തപ്രദേശത്ത് വെച്ച് സൈന്യം അവരെ പിടികൂടി. അങ്ങനെ അവരെ നബി(സ)യുടെ അടുത്തേക്ക് നയിച്ചു. ഞാൻ ഉടൻ വാഹനം കയറി. ഞാൻ അവരുടെ മുമ്പേ റസൂലുല്ലാഹി(സ)യുടെ അടുക്കലെത്തി. ഞാൻ പറഞ്ഞു: അസ്സലാമു അലൈക്ക യാ നബിയ്യല്ലാഹി വറഹ്മത്തുല്ലാഹി വബറകാത്തുഹു! അങ്ങയുടെ സേന ഞങ്ങളുടെ അടുക്കൽ വന്ന് ഞങ്ങളെ പിടിച്ചുവെച്ചു. ഞങ്ങൾ മുസ്ലിംകൾ ആവുകയും ഞങ്ങളുടെ ഒട്ടകങ്ങളുടെ ചെവികളുടെ അഗ്രങ്ങൾ ഛേദിക്കുകയും ചെയ്തിരുന്നു. ബനുൽ അൻബർ വന്നപ്പോൾ തിരുനബി(സ) എന്നോട് പറഞ്ഞു: "ഈ ദിവസങ്ങളിൽ പിടിക്കപ്പെടും മുമ്പേ നിങ്ങൾ മുസ്ലിംകളായിട്ടുണ്ടെന്നതിന് വല്ല തെളിവും നിങ്ങൾക്ക് ഉണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. അവിടന്ന് ചോദിച്ചു: "ആരാണ് നിന്റെ തെളിവ് (സാക്ഷി)?" ഞാൻ പറഞ്ഞു: ബനുൽ അൻബറിൽപ്പെട്ട സമുറതും - നബി(സ)യോട് അദ്ദേഹം പേര് പറഞ്ഞുകൊടുത്ത - മറ്റൊരാളും. അങ്ങനെ ആ ആൾ സാക്ഷി നിന്നു. സമുറത് സാക്ഷി നിൽക്കാൻ വിസമ്മതിക്കുകയും ചെയ്തു. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "അയാൾ താങ്കൾക്ക് സാക്ഷിനിൽക്കാൻ വിസമ്മതിച്ചിരിക്കുന്നു. അതിനാൽ താങ്കൾ മറ്റേയാളുടെ കൂടെ സത്യം ചെയ്യുക." ഞാൻ പറഞ്ഞു: അതെ. അങ്ങനെ അവിടന്ന് എന്നെ സത്യം ചെയ്യിച്ചു. ഞങ്ങൾ ഇന്നാലിന്ന ദിവസം മുസ്ലിംകളായി എന്നും ഞങ്ങളുടെ ഒട്ടകങ്ങളുടെ കാതുകളുടെ അഗ്രങ്ങൾ മുറിച്ചുവെന്നും ഞാൻ സത്യം ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പോവുക. അവരുടെ സ്വത്ത് പകുതി വീതിക്കുക, അവരിലെ കുട്ടികളെ തൊടരുത്. അല്ലാഹു ഒരു പ്രവർത്തനം വഴിപിഴപ്പിക്കൽ ഇഷ്ടപ്പെടാതിരിക്കുന്നില്ലായിരുന്നുവെങ്കിൽ നാം ഒരു ഒട്ടകക്കയർ പോലും നിങ്ങൾക്ക് നൽകുമായിരുന്നില്ല." സുബൈബ് പറഞ്ഞു: അന്നേരം എന്റെ ഉമ്മ എന്നെ വിളിച്ചിട്ട് പറഞ്ഞു: ഈ മനുഷ്യൻ എന്റെ മെത്തയെടുത്തിരിക്കുന്നു. ഉടൻ ഞാൻ നബി(സ)യുടെ അടുക്കലേക്ക് തിരിച്ചു, അഥവാ, ഞാനവിടത്തോട് വിഷയം അവതരിപ്പിച്ച് കൊടുത്തു. അവിടന്ന് പറഞ്ഞു: "അവനെ പിടിക്കുക." ഞാൻ അയാളുടെ കഴുത്തിൽ ചുറ്റിയിരുന്ന വസ്ത്രത്തിൽ പിടിച്ചു. എന്നിട്ട് അയാളുടെ കൂടെ ഞങ്ങളുടെ സ്ഥലത്ത് നിന്നു. ഞങ്ങൾ നിൽക്കുമ്പോൾ റസൂലുല്ലാഹി(സ) ഞങ്ങളെ നോക്കി. അവിടന്ന് ചോദിച്ചു: "താങ്കളുടെ ബന്ധിയെക്കൊണ്ട് താങ്കൾ ഉദ്ദേശിക്കുന്നതെന്താണ്?" അപ്പോൾ ഞാൻ അയാളെ എന്റെ കയ്യിൽ നിന്നും അയച്ചിട്ടു. അപ്പോൾ നബി(സ) എഴുന്നേറ്റുനിന്ന് ആ മനുഷ്യനോട് പറഞ്ഞു: "നീ എടുത്ത, ഇയാളുടെ ഉമ്മയുടെ മെത്ത ഇയാൾക്ക് തിരിച്ച് നൽകൂ." അയാൾ പറഞ്ഞു: റസൂലേ, നിശ്ചയം അത് എന്റെ കൈയിൽ നിന്ന് പോയിട്ടുണ്ട്. നിവേദകൻ: ഉടനെ നബി(സ) അയാളുടെ വാൾ ഊരി എനിക്ക് നൽകി. ശേഷം അവിടുന്ന് ആ മനുഷ്യനോട് പറഞ്ഞു: "നീ പോവുക. എന്നിട്ട് അദ്ദേഹത്തിന് കുറച്ച് സ്വാഅ് (ഒരു സ്വാഅ് = നാല് മുദ്ദ്) ഭക്ഷണം അധികം നൽകുക." നിവേദകൻ: അങ്ങനെ അയാൾ എനിക്ക് കുറച്ച് സ്വാഅ് ബാർലി തന്നു. (ദ)', 'الزُّبَيْبِ بْنِ ثَعْلَبَةَ', 'സുബൈബുബ്നു സഅ്ലബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 427, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَبْغَضَ الرِّجَالِ إِلَى اللَّهِ الْأَلَدُّ الْخَصِمُ". (م,ن)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹുവിന് ഏറ്റവും ദേഷ്യമുള്ള മനുഷ്യൻ നന്നായി ശണ്ഠ കൂടി തർക്കിക്കുന്നവനാണ്." (മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ زَوْجَ بَرِيرَةَ كَانَ عَبْدًا يُقَالُ لَهُ مُغِيثٌ، كَأَنِّي أَنْظُرُ إِلَيْهِ يَطُوفُ خَلْفَهَا يَبْكِي وَدُمُوعُهُ تَسِيلُ عَلَى لِحْيَتِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْعَبَّاسِ: "يَا عَبَّاسُ أَلَا تَعْجَبُ مِنْ حُبِّ مُغِيثٍ بَرِيرَةَ، وَمِنْ بُغْضِ بَرِيرَةَ مُغِيثًا". فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ رَاجَعْتِيهِ، فَإِنَّهُ أَبُو وَلَدِكِ". قَالَتْ: يَا رَسُولَ اللَّهِ، أَتَأْمُرُنِي؟ قَالَ: "إِنَّمَا أَنَا شَفِيعٌ". قَالَتْ: فَلَا حَاجَةَ لِي فِيهِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ബരീറ(റ)യുടെ ഭർത്താവ് ഒരു അടിമയായിരുന്നു. മുഗീസ് എന്നാണ് അയാളെ വിളിക്കപ്പെടുക. അയാൾ അവരുടെ പിന്നാലെ, താടിയിലൂടെ കണ്ണീരൊലിക്കും വിധം കരഞ്ഞ് കൊണ്ട് ചുറ്റുന്നത് ഞാൻ ഇപ്പോഴും കണ്ടുകൊണ്ടിരിക്കുന്നത് പോലെയുണ്ട്! നബി(സ) അബ്ബാസ്(റ)വിനോട് പറഞ്ഞു: "ഓ അബ്ബാസ്, മുഗീസിന് ബരീറ(റ)യോടുള്ള സ്നേഹത്തിലും ബരീറക്ക് മുഗീസിനോടുള്ള വെറുപ്പിലും താങ്കൾ അത്ഭുതപ്പെടുന്നില്ലേ?" അങ്ങനെ നബി(സ) ബരീറ(റ)യോട് പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തെ തിരികെ എടുത്തിരുന്നെങ്കിൽ! കാരണം, നിശ്ചയം അദ്ദേഹം നിങ്ങളുടെ കുട്ടിയുടെ പിതാവാണ്." അവർ ചോദിച്ചു: അവിടുന്നെന്നോട് കൽപിക്കുകയാണോ? തിരുമേനി(സ) പറഞ്ഞു: "നിശ്ചയം ഞാൻ ഒരു ശിപാർശകൻ മാത്രമാണ്." അവർ പറഞ്ഞു: എനിക്കയാളിൽ ഒരാവശ്യവുമില്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 428, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَعْتَقَ رَجُلٌ مِنَ الْأَنْصَارِ غُلَامًا لَهُ عَنْ دُبُرٍ، وَكَانَ مُحْتَاجًا وَكَانَ عَلَيْهِ دَيْنٌ، فَبَاعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَمَانِ مِائَةِ دِرْهَمٍ فَأَعْطَاهُ، فَقَالَ: "اقْضِ دَيْنَكَ، وَأَنْفِقْ عَلَى عِيَالِكَ". (ن)', 'ജാബിറുബ്നു അബ്ദില്ലാഹി(റ): അൻസാറുകളിലൊരാൾ തന്റെ അടിമയെ തന്റെ മരണശേഷം മോചിതനാകുന്ന രീതിയിലാക്കി. അങ്ങനെ മോചിപ്പിച്ചു. അയാളൊരു ദരിദ്രനായിരുന്നു. അയാൾക്ക് കടവും ഉണ്ടായിരുന്നു. അപ്പോൾ റസൂലുല്ലാഹി(സ) അവനെ എണ്ണൂറ് ദിർഹമിന് വിൽക്കുകയും അത് അദ്ദേഹത്തിന് നൽകുകയും ചെയ്തു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "നിന്റെ കടം നീ കൊടുത്തുവീട്ടുക. നിന്റെ കുടുംബത്തിന്റെ മേൽ ചെലവഴിക്കുകയും ചെയ്യുക." (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാഹി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا كَانَ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عُقْدَتِهِ ضَعْفٌ، وَكَانَ يُبَايِعُ، وَأَنَّ أَهْلَهُ أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ، احْجُرْ عَلَيْهِ. فَدَعَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَهَاهُ عَنْ ذَلِكَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي لَا أَصْبِرُ عَنِ الْبَيْعِ. فَقَالَ: "إِذَا بَايَعْتَ فَقُلْ: هَا، وَلَا خِلَابَةَ". (د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂലുല്ലാഹി(സ)യുടെ കാലത്ത് ഒരാളുടെ നാവിൽ ക്ഷയം ഉണ്ടായി. അദ്ദേഹമാണെങ്കിൽ വ്യാപാരം നടത്തുമായിരുന്നു. അദ്ദേഹത്തിന്റെ കുടുംബക്കാർ നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അങ്ങ് അദ്ദേഹത്തെ (വിൽപനയൽ നിന്ന്) തടുക്കണേ. അപ്പോൾ അദ്ദേഹത്തെ നബി(സ) വിളിച്ച് അതിനെ (വിൽപനയെ) നിരോധിച്ചു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എനിക്ക് വിൽപന നടത്താതെ ക്ഷമിച്ചിരിക്കാനാവില്ല. അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ വിൽപന നടത്തിയാൽ പറയുക: എടുത്തുകൊള്ളുക, പ്രലോഭനമൊന്നുമില്ല, എന്ന്." (ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانٍ قَالَ: هُوَ جَدِّي مُنْقِذُ بْنُ عَمْرٍو، وَكَانَ رَجُلًا قَدْ أَصَابَتْهُ آمَّةٌ فِي رَأْسِهِ فَكَسَرَتْ لِسَانَهُ، وَكَانَ لَا يَدَعُ عَلَى ذَلِكَ التِّجَارَةَ، وَكَانَ لَا يَزَالُ يُغْبَنُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ لَهُ: "إِذَا أَنْتَ بَايَعْتَ فَقُلْ: لَا خِلَابَةَ، ثُمَّ أَنْتَ فِي كُلِّ سِلْعَةٍ ابْتَعْتَهَا بِالْخِيَارِ ثَلَاثَ لَيَالٍ: فَإِنْ رَضِيتَ فَأَمْسِكْ، وَإِنْ سَخِطْتَ فَارْدُدْهَا عَلَى صَاحِبِهَا". [ز: فيه مدلس عنعنه] (جه)', 'മുഹമ്മദുബ്നു യഹ്യബ്നി ഹബ്വാൻ(റ): എന്റെ പിതാമഹൻ മുൻഖിദുബ്നു അംറിന് തന്റെ തലയിൽ ഒരു ന്യൂനത സംഭവിക്കുകയും അത് അദ്ദേഹത്തിന്റെ നാവ് മുറിക്കുകയും ചെയ്തിരിക്കുന്നു. അതൊക്കെയാണെങ്കിലും അദ്ദേഹം വ്യാപാരം ഒഴിവാക്കില്ലായിരുന്നു. അദ്ദേഹം ചതിക്കപ്പെട്ടുകൊണ്ടേയിരിക്കുന്നുണ്ടായിരുന്നു. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ വന്ന് അക്കാര്യം അവിടത്തെ ബോധിപ്പിച്ചു. അവിടന്ന് അദ്ദേഹത്തോട് പറഞ്ഞു: "നിങ്ങൾ വിൽപന നടത്തുകയാണെങ്കിൽ പറയുക: (ഇതിൽ) പ്രലോഭനമൊന്നുമില്ല. പിന്നെ താങ്കൾ എല്ലാ ചരക്കും മൂന്ന് ദിവസത്തെ, തിരഞ്ഞെടുക്കാനുള്ള അവകാശം കൊണ്ട് വാങ്ങണം. അത് നിങ്ങൾ തൃപ്തിപ്പെട്ടാൽ പിടിക്കുക. ഇഷ്ടപ്പെട്ടില്ലെങ്കിൽ അതിന്റെയാളെ ഏൽപിക്കുകയും ചെയ്യുക." (ജ)', 'مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانٍ قَالَ', 'മുഹമ്മദുബ്നു യഹ്യബ്നി ഹബ്വാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه مدلس عنعنه', null, 429, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ أَبِي مُلَيْكَةَ قَالَ: كَانَتْ جَارِيَتَانِ تَخْرُزَانِ بِالطَّائِفِ، فَخَرَجَتْ إِحْدَاهُمَا وَيَدُهَا تَدْمَى، فَزَعَمَتْ أَنَّ صَاحِبَتَهَا أَصَابَتْهَا وَأَنْكَرَتِ الْأُخْرَى، فَكَتَبْتُ إِلَى ابْنِ عَبَّاسٍ فِي ذَلِكَ، فَكَتَبَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى: أَنَّ الْيَمِينَ عَلَى الْمُدَّعَى عَلَيْهِ: "وَلَوْ أَنَّ النَّاسَ أُعْطُوا بِدَعْوَاهُمْ لَادَّعَى نَاسٌ أَمْوَالَ نَاسٍ وَدِمَاءَهُمْ". فَادْعُهَا وَاتْلُ عَلَيْهَا هَذِهِ الْآيَةَ: {إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا أُولَئِكَ لَا خَلَاقَ لَهُمْ فِي الْآخِرَةِ} حَتَّى خَتَمَ الْآيَةَ، فَدَعَوْتُهَا فَتَلَوْتُ عَلَيْهَا فَاعْتَرَفَتْ بِذَلِكَ، فَسَرَّهُ. (ن)', 'ഇബ്നുഅബീ മുലൈക(റ): രണ്ട് പരിചാരികമാർ ത്വാഇഫിൽ ചെരുപ്പ് തുന്നുകയായിരുന്നു. അവരിലൊരാൾ തന്റെ കൈ രക്തമൊലിച്ച് കൊണ്ട് പുറത്ത് വന്നു. എന്നിട്ട് തന്റെ കൂട്ടുകാരിയാണിത് പറ്റിച്ചതെന്ന് അവൾ വാദിച്ചു. മറ്റവൾ അത് നിഷേധിക്കുകയും ചെയ്തു. അപ്പോൾ ഞാൻ ഇബ്നു അബ്ബാസ്(റ)വിന് ഇക്കാര്യത്തിൽ കത്തെഴുതി. അദ്ദേഹം മറുപടിയായി ഇപ്രകാരം എഴുതി: തീർച്ചയായും പ്രതിയാണ് സത്യം ചെയ്യേണ്ടത് എന്ന് റസൂലുല്ലാഹി(സ) വിധിച്ചിരിക്കുന്നു. അവിടുന്ന് പറഞ്ഞു: "ജനങ്ങൾക്ക് അവരുടെ വാദത്തിനനുസരിച്ച് നൽകിയാൽ തീർച്ചയായും ജനങ്ങൾ മറ്റുജനങ്ങളുടെ സമ്പത്തും രക്തവും വാദിക്കുക തന്നെ ചെയ്യും." അതിനാൽ താങ്കൾ അവളെ വിളിച്ച് അവൾക്ക് ഈ സൂക്തം ഓതിക്കൊടുക്കുക: ''തീർച്ചയായും അല്ലാഹുവിന്റെ കരാർ കൊണ്ടും തങ്ങളുടെ സത്യം ചെയ്യൽ കൊണ്ടും തുച്ഛമായ വില വാങ്ങുന്നവർ, അവർക്ക് അന്ത്യനാളിൽ ഒരു ഓഹരിയുമില്ല.'' ഈ സൂക്തത്തിന്റെ അവസാനം വരെ. അങ്ങനെ ഞാനവളെ വിളിച്ച് ഈ സൂക്തം ഓതിക്കൊടുത്തു. അവളത് സമ്മതിച്ചു. അതദ്ദേഹത്തിന് സന്തോഷമായി. (ന)', 'ابْنِ أَبِي مُلَيْكَةَ قَالَ', 'ഇബ്നുഅബീ മുലൈക(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي دَابَّةٍ، لَيْسَ لِوَاحِدٍ مِنْهُمَا بَيِّنَةٌ، فَقَضَى بِهَا بَيْنَهُمَا نِصْفَيْنِ. (ن)', 'അബൂമൂസാ(റ): രണ്ട് പേർ ഒരു മൃഗത്തിന്റെ കാര്യത്തിൽ തർക്കിച്ച് നബി(സ)യുടെ സന്നിധിയിലെത്തി. അവരിലൊരാൾക്കും ഒരു തെളിവും ഉണ്ടായിരുന്നില്ല. തിരുമേനി(സ) അവർക്കിടയിൽ മൃഗത്തിന്റെ പകുതി കൊണ്ട് വിധിച്ചു. (ന)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلَيْنِ ادَّعَيَا بَعِيرًا - أَوْ: دَابَّةً - إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَيْسَتْ لِوَاحِدٍ مِنْهُمَا بَيِّنَةٌ، فَجَعَلَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا. وَفِي رِوَايَةٍ: أَنَّ رَجُلَيْنِ ادَّعَيَا بَعِيرًا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ كُلُّ وَاحِدٍ مِنْهُمَا شَاهِدَيْنِ، فَقَسَمَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا نِصْفَيْنِ. (د,ن,جه)', 'അബൂമൂസൽ അശ്അരീ(റ): രണ്ടാളുകൾ ഒരൊട്ടകത്തെക്കുറിച്ച് - അല്ലെങ്കിൽ ഒരു മൃഗത്തെ - തന്റേതാണെന്ന് വാദിച്ച് നബി(സ)യുടെ അടുക്കലെത്തി. അവരിലൊരാൾക്കും തെളിവ് ഇല്ലായിരുന്നു. അപ്പോൾ നബി(സ) അതിനെ അവർക്കിടയിൽ വീതിച്ചു. ഒരു റിപ്പോർട്ടിൽ: നബി(സ)യുടെ കാലത്ത് രണ്ട് പേർ ഒരൊട്ടകത്തിന്റെ കാര്യത്തിൽ തർക്കിച്ചു. രണ്ടുപേരും രണ്ട് സാക്ഷികളെ അയച്ചു. അപ്പോൾ നബി(സ) അതിനെ രണ്ടുപേർക്കുമിടയിൽ പകുതിയാക്കി വിധിച്ചു. (ദ,ന,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരീ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 430, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=71), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَجُلَيْنِ ادَّعَيَا بَعِيرًا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ كُلُّ وَاحِدٍ مِنْهُمَا شَاهِدَيْنِ، فَقَسَمَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا نِصْفَيْنِ. (د,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلَيْنِ اخْتَصَمَا فِي مَتَاعٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَيْسَ لِوَاحِدٍ مِنْهُمَا بَيِّنَةٌ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْتَهِمَا عَلَى الْيَمِينِ مَا كَانَ، أَحَبَّا ذَلِكَ أَوْ كَرِهَا". وَفِي رِوَايَةٍ: اخْتَصَمَا فِي دَابَّةٍ، وَلَيْسَ لَهُمَا بَيِّنَةٌ، فَأَمَرَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَسْتَهِمَا عَلَى الْيَمِينِ. وَفِي رِوَايَةٍ: "إِذَا كَرِهَ الِاثْنَانِ الْيَمِينَ، أَوِ اسْتَحَبَّاهَا فَلْيَسْتَهِمَا عَلَيْهَا". وَفِي رِوَايَةٍ: "إِذَا أُكْرِهَ الِاثْنَانِ عَلَى الْيَمِينِ". (خ,د,ن,جه)', 'അബൂഹുറൈറ(റ): രണ്ടുപേർ ഒരു ചരക്കിന്റെ കാര്യത്തിൽ പരസ്പരം ശണ്ഠകൂടി നബി(സ)യുടെ അടുക്കലെത്തി. അവരിലൊരാൾക്ക് ഒരു തെളിവുമില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ട് പേരും ഇഷ്ടപ്പെട്ടാലും വെറുത്താലും ഇരുവരും സത്യം ചെയ്ത് ഉള്ളത് വീതിക്കുക." ഒരു ഉദ്ധരണിയിൽ: ഇരുവരും ഒരു മൃഗത്തിന്റെ കാര്യത്തിൽ തർക്കിച്ചു. ഇരുവർക്കും തെളിവൊന്നുമില്ലതാനും. അപ്പോൾ നബി(സ) അവരോട് സത്യം ചെയ്ത്, വീതം വെക്കാൻ കൽപിച്ചു. ഒരു നിവേദനത്തിൽ: "രണ്ട് പേർ സത്യം ചെയ്യാൻ ഇഷ്ടപ്പെടാതെ വന്നാൽ, അല്ലെങ്കിൽ ഇരുവരും അതിഷ്ടപ്പെട്ടാൽ, ഇരുവരും അത് വീതം വെച്ചെടുക്കട്ടെ." മറ്റൊരു റിപ്പോർട്ടിൽ: "രണ്ടുപേർ സത്യം ചെയ്യാൻ നിർബന്ധിക്കപ്പെട്ടാൽ" എന്നാണുള്ളത്. (ബു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=72), 1, 'وَفِي رِوَايَةٍ: اخْتَصَمَا فِي دَابَّةٍ، وَلَيْسَ لَهُمَا بَيِّنَةٌ، فَأَمَرَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَسْتَهِمَا عَلَى الْيَمِينِ.', 'മറ്റൊരു നിവേദനിൽ: "രണ്ടുപേർ സത്യം ചെയ്യാൻ നിർബന്ധിക്കപ്പെട്ടാൽ" എന്നാണുള്ളത്. (ബു,ദ,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=72), 2, 'وَفِي رِوَايَةٍ: "إِذَا كَرِهَ الِاثْنَانِ الْيَمِينَ، أَوِ اسْتَحَبَّاهَا فَلْيَسْتَهِمَا عَلَيْهَا".', null);
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=72), 3, 'وَفِي رِوَايَةٍ: "إِذَا أُكْرِهَ الِاثْنَانِ عَلَى الْيَمِينِ". (خ,د,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ ادَّعَى مَا لَيْسَ لَهُ فَلَيْسَ مِنَّا، وَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (جه)', 'അബൂദർറ്(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ആരെങ്കിലും തനിക്കില്ലാത്തത് വാദിച്ചാൽ അവൻ നമ്മിൽപ്പെട്ടവനല്ല. അവൻ തന്റെ ഇരിപ്പിടം നരകത്തിൽ തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَعَانَ عَلَى خُصُومَةٍ بِظُلْمٍ - أَوْ: يُعِينُ عَلَى ظُلْمٍ - لَمْ يَزَلْ فِي سَخَطِ اللَّهِ حَتَّى يَنْزِعَ". (د,جه)', 'ഇബ്നുഉമർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു തർക്കത്തിന് വല്ല അക്രമവും കൊണ്ട് സഹായിച്ചാൽ - അല്ലെങ്കിൽ: അവൻ അക്രമത്തിന് സഹായിക്കുകയാണെങ്കിൽ - അവൻ അതിൽ നിന്ന് ഊരുന്നത് വരെ അല്ലാഹുവിന്റെ കോപത്തിലായിക്കൊണ്ടിരിക്കും." (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْيَمِينِ مَعَ الشَّاهِدِ الْوَاحِدِ. حسن. (د,ت,جه)', 'അബൂഹുറൈറ(റ): ഒറ്റ സാക്ഷി മാത്രമുണ്ടാകുമ്പോൾ സത്യം ചെയ്യൽ കൂടി വേണമെന്ന് റസൂലുല്ലാഹി(സ) വിധിച്ചു. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 431, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ. (ت,جه)', 'ജാബിർ(റ): ഒറ്റ സാക്ഷിയുടെ കൂടെ സത്യം ചെയ്യൽ കൂടി വേണമെന്ന് തിരുനബി(സ) വിധിച്ചു. (തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ الْوَاحِدِ، قَالَ: وَقَضَى بِهَا عَلِيٌّ فِيكُمْ. (ت)', 'മുഹമ്മദുബ്നു അലിയ്യിബ്നിൽ ഹുസൈൻ(റ): ഒറ്റ സാക്ഷിയുടെ കൂടെ സത്യം ചെയ്യൽക്കൊണ്ടും തിരുനബി(സ) വിധിച്ചു. നിവേദകൻ പറഞ്ഞു: ആ വിധി അലി(റ)വും നിങ്ങളിൽ വിധിച്ചിട്ടുണ്ട്. (തു)', 'مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ الْوَاحِدِ، قَالَ', 'മുഹമ്മദുബ്നു അലിയ്യിബ്നിൽ ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمِ ادَّعَى نَاسٌ دِمَاءَ رِجَالٍ وَأَمْوَالَهُمْ، وَلَكِنِ الْيَمِينُ عَلَى الْمُدَّعَى عَلَيْهِ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് അവരുടെ വാദമനുസരിച്ച് നൽകപ്പെടുകയാണെങ്കിൽ ചില ജനങ്ങൾ ആളുകളുടെ രക്തബന്ധത്തിനും സമ്പതതിനും വാദമുന്നയിക്കും. എന്നാൽ പ്രതിയുടെ മേലാണ് സത്യം ചെയ്യലുള്ളത്." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ الْأَشْعَثِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنَ الْيَهُودِ أَرْضٌ، فَجَحَدَنِي، فَقَدَّمْتُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكَ بَيِّنَةٌ". قُلْتُ: لَا. قَالَ لِلْيَهُودِيِّ: "احْلِفْ". قُلْتُ: إِذًا يَحْلِفُ فِيهِ فَيَذْهَبُ بِمَالِي. فَأَنْزَلَ اللَّهُ سُبْحَانَهُ: {إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا} إِلَى آخِرِ الْآيَةِ. (ق,د,ت,جه)', 'അശ്അസുബ്നു വൈസ്(റ): എന്റെയും ഒരു ജൂതന്റെയുമിടയിൽ ഒരു ഭൂമി സംബന്ധമായ ഇടപാട് ഉണ്ടായിരുന്നു. അങ്ങനെ അയാൾ എനിക്കത് നിഷേധിച്ചു. അപ്പോൾ ഞാൻ അക്കാര്യം നബി(സ)യുടെ മുന്നിൽ അവതരിപ്പിച്ചു. അവിടുന്നെന്നോട് ചോദിച്ചു: "നിനക്ക് വല്ല തെളിവുമുണ്ടോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അവിടന്ന് ആ ജൂതനോട് പറഞ്ഞു: "നീ സത്യം ചെയ്യുക." അപ്പോൾ ഞാൻ പറഞ്ഞു: അങ്ങനെയെങ്കിൽ അവനതിൽ സത്യം ചെയ്യുകയും എന്റെ സ്വത്തുമായി പോവുകയും ചെയ്യും. അപ്പോൾ പരിശുദ്ധനായ അല്ലാഹു ''നിശ്ചയം അല്ലാഹുവിന്റെ കരാറിലും തങ്ങളുടെ സത്യത്തിലുമായി തുച്ഛമായ വില വാങ്ങുന്നവർ'' എന്ന സൂക്തത്തിന്റെ അവസാനം വരെ ഇറക്കി. (ബു,മു,ദ,തു,ജ)', 'الْأَشْعَثِ بْنِ قَيْسٍ', 'അശ്അസുബ്നു വൈസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنْ حَضْرَمَوْتَ وَرَجُلٌ مِنْ كِنْدَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا غَلَبَنِي عَلَى أَرْضٍ لِي فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضِي وَفِي يَدِي، لَيْسَ لَهُ فِيهَا حَقٌّ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْحَضْرَمِيِّ: "أَلَكَ بَيِّنَةٌ". قَالَ: لَا. قَالَ: "فَلَكَ يَمِينُهُ". قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ الرَّجُلَ فَاجِرٌ، لَا يُبَالِي عَلَى مَا حَلَفَ عَلَيْهِ، وَلَيْسَ يَتَوَرَّعُ مِنْ شَيْءٍ. قَالَ: "لَيْسَ لَكَ مِنْهُ إِلَّا ذَلِكَ". قَالَ: فَانْطَلَقَ الرَّجُلُ لِيَحْلِفَ لَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَدْبَرَ: "لَئِنْ حَلَفَ عَلَى مَالِكَ لِيَأْكُلَهُ ظُلْمًا لَيَلْقَيَنَّ اللَّهَ وَهُوَ عَنْهُ مُعْرِضٌ". حسن صحيح. (م,د,ت,ن)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഹള്റമൗത്തിൽ നിന്ന് ഒരാളും കിൻദയിൽ നിന്ന് ഒരാളും നബി(സ)യുടെ അടുക്കൽ വന്നു. ആ ഹള്റമിക്കാരൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇയാൾ എന്റെ ഒരു ഭൂമി കൈവശപ്പെടുത്തിയിരിക്കുന്നു. അപ്പോൾ കിൻദക്കാരൻ പറഞ്ഞു: അതെന്റെ ഭൂമിയാണ്. എന്റെ കൈയിലുമാണത്. ഇയാൾക്കതിൽ ഒരവകാശവുമില്ല. അപ്പോൾ ഹള്റമിക്കാരനോട് നബി(സ) ചോദിച്ചു: "നിനക്ക് വല്ല തെളിവുമുണ്ടോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അവിടന്ന് പറഞ്ഞു: "എന്നാൽ നിനക്ക് അവന്റെ സത്യം ചെയ്യലാണുള്ളത്." അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ആ മനുഷ്യൻ ചീത്തവനാണ്. സത്യം ചെയ്യുന്നത് അവൻ വിലവെക്കില്ല. അവൻ ഒരു കാര്യത്തിലും സൂക്ഷ്മത പുലർത്താറില്ല. അവിടന്ന് പറഞ്ഞു: "അവനിൽ നിന്ന് അതല്ലാതെ ഒന്നും തന്നെ നിനക്കില്ല." നിവേദകൻ പറയുന്നു: അങ്ങനെ ആ മനുഷ്യൻ സത്യം ചെയ്യാൻ നീങ്ങി. അവൻ പിന്തിരിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൻ നിന്റെ സ്വത്തിന്റെ കാര്യത്തിൽ, അക്രമമായി അത് ഭക്ഷിക്കാൻ വേണ്ടി, സത്യം ചെയ്താൽ തന്നെത്തൊട്ട് തിരിഞ്ഞുകളയുന്ന നിലയിൽ, അവൻ അല്ലാഹുവിനെ കണ്ടുമുട്ടുക തന്നെ ചെയ്യും." (മു,ദ,തു,ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 432, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَبْدِ اللَّهِ عَنْ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي خُطْبَتِهِ: "الْبَيِّنَةُ عَلَى الْمُدَّعِي، وَالْيَمِينُ عَلَى الْمُدَّعَى عَلَيْهِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) തന്റെ ഖുഥ്ബയിൽ പറഞ്ഞു: "തെളിവ് നൽകേണ്ട ഉത്തരവാദിത്തം വാദിയുടെ മേലിലാണ്. സത്യം ചെയ്യേണ്ട ഉത്തരവാദിത്തം പ്രതിയുടെ മേലിലുമാണ്." (തു)', 'عَبْدِ اللَّهِ عَنْ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى أَنَّ الْيَمِينَ عَلَى الْمُدَّعَى عَلَيْهِ. حسن صحيح. (ق,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം സത്യം ചെയ്യേണ്ടത് പ്രതിയാണ് എന്ന് റസൂലുല്ലാഹി(സ) വിധിച്ചു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ النَّاسِ خَيْرٌ؟ قَالَ: "قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ يَجِيءُ قَوْمٌ تَبْدُرُ شَهَادَةُ أَحَدِهِمْ يَمِينَهُ، وَيَمِينُهُ شَهَادَتَهُ". (ق,ت,جه)', 'അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ): റസൂലുല്ലാഹി(സ)യോട് ചോദിക്കപ്പെട്ടു: ജനങ്ങളിൽ ഏറ്റവും നല്ലവൻ ആരാണ്? അവിടന്ന് പറഞ്ഞു: "എന്റെ നൂറ്റാണ്ട് (എന്റെ കാലത്ത് ജീവിക്കുന്നവർ), പിന്നീട് അവരോട് അടുത്തവർ, പിന്നീട് അവരോടടുത്തവർ. പിന്നീട് ഒരു സമൂഹം വരും. അവരിലൊരാളുട സാക്ഷിത്വം തന്റെ സത്യത്തേക്കാൾ മുന്നിൽ വരും, അവന്റെ സത്യം ചെയ്യൽ തന്റെ സാക്ഷിത്വത്തേക്കാൾ മുന്നിൽ വരും." (ബു,മു,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا عُمَرُ بْنُ الْخَطَّابِ بِالْجَابِيَةِ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فِينَا مِثْلَ مُقَامِي فِيكُمْ، فَقَالَ: "احْفَظُونِي فِي أَصْحَابِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ يَفْشُو الْكَذِبُ، حَتَّى يَشْهَدَ الرَّجُلُ وَمَا يُسْتَشْهَدُ، وَيَحْلِفَ وَمَا يُسْتَحْلَفُ". [ز: فيه مدلس عنعنه] (جه)', 'ജാബിറുബ്നു സമുറ(റ): ജാബിയയിൽ വെച്ച് ഉമറുബ്നുൽഖത്താബ്(റ) ഞങ്ങളോട് പ്രഭാഷണം നടത്തി. അദ്ദേഹം പറഞ്ഞു: റസൂലുല്ലാഹി(സ) ഞങ്ങളിൽ, നിങ്ങളിലുള്ള എന്റെ ഈ നിൽപ് പോലെ എഴുന്നേറ്റു നിന്ന് പറഞ്ഞു: "എന്റെ സ്വഹാബാക്കളിൽ നിങ്ങൾ എന്നെ സൂക്ഷിക്കുവീൻ, പിന്നീട് അവരോടടുത്തവരിൽ, പിന്നീട് അവരോടടുത്തവരിൽ. അതിന് ശേഷം കള്ളം പറയൽ അധികമാകും. എത്രത്തോളമെന്നാൽ, ഒരാൾ തന്നോട് സാക്ഷ്യം ചോദിക്കപ്പെടും മുമ്പേ സാക്ഷി നിൽക്കും. അവനോട് സത്യം ചെയ്യാൻ പറയപ്പെടും മുമ്പേ അവൻ സത്യം ചെയ്യുകയും ചെയ്യും." (ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه مدلس عنعنه', null, 433, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "خَيْرُ النَّاسِ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ. ثَلَاثًا، ثُمَّ يَجِيءُ قَوْمٌ مِنْ بَعْدِهِمْ يَتَسَمَّنُونَ وَيُحِبُّونَ السِّمَنَ، يُعْطُونَ الشَّهَادَةَ قَبْلَ أَنْ يُسْأَلُوهَا". (ق,د,ت,ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ജനങ്ങളിൽ ഏറ്റവും നല്ലവർ എന്റ നൂറ്റാണ്ടുകാരാണ്, പിന്നീട് അവരോടടുത്തവർ, പിന്നീട് അവരോടടുത്തവർ. മൂന്ന് തലമുറ വരെ. പിന്നീട് അവർക്ക് ശേഷം ഒരു സമൂഹം വരും. അവർ തന്നിലില്ലാത്ത ഗുണങ്ങൾ ഉണ്ടെന്ന് വാദിക്കുകയും കൊഴുപ്പ് ഇഷ്ടപ്പെടുകയും ചെയ്യും. അവരോട് ആവശ്യപ്പെടും മുമ്പേ അവർ സാക്ഷിത്വം നിൽക്കുകയും ചെയ്യും." (ബു,മു,ദ,തു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ بِخَيْرِ الشُّهَدَاءِ؟ الَّذِي يَأْتِي بِشَهَادَتِهِ - أَوْ: يُخْبِرُ بِشَهَادَتِهِ - قَبْلَ أَنْ يُسْأَلَهَا". (م,د,ت,جه)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനീ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "സാക്ഷി നിൽക്കുന്നവരിൽ ഏറ്റവും നല്ലവനെ ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ? സാക്ഷിത്വം ചോദിക്കപ്പെടും മുമ്പേ സാക്ഷിത്വവുമായി വരുന്ന - അല്ലെങ്കിൽ സാക്ഷിത്വം അറിയിക്കുന്ന - വനാണ്." (മു,ദ,തു,ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനീ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَيْمَنَ بْنِ خُرَيْمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ خَطِيبًا فَقَالَ: "يَا أَيُّهَا النَّاسُ، عَدَلَتْ شَهَادَةُ الزُّورِ إِشْرَاكًا بِاللَّهِ". ثُمَّ قَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {فَاجْتَنِبُوا الرِّجْسَ مِنَ الْأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ} [الحجّ: ٣٠]. (ت)', 'ഐമനുബ്നു ഖുറൈം(റ): നബി(സ) പ്രസംഗിക്കാൻ നിന്നുകൊണ്ട് പറഞ്ഞു: "ജനങ്ങളേ! കള്ളസാക്ഷ്യം വഹിക്കൽ അല്ലാഹുവിനെ പങ്കുചേർക്കലിനോട് കിടപിടിക്കും." പിന്നീട് റസൂലുല്ലാഹി(സ) ഓതി: ''ബിംബങ്ങളിൽ നിന്നുള്ള ചീത്ത പ്രവൃത്തി നിങ്ങൾ ഒഴിവാക്കുക. കള്ള വാക്കുകളും നിങ്ങൾ ഒഴിവാക്കുക'' (അൽഹജ്ജ്: 30) (തു)', 'أَيْمَنَ بْنِ خُرَيْمٍ', 'ഐമനുബ്നു ഖുറൈം(റ)', null, null, array['ت']::text[], array['തു']::text[], 'الحجّ: ٣٠', null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى صَلَاةَ الصُّبْحِ، فَلَمَّا انْصَرَفَ قَامَ قَائِمًا فَقَالَ: "عُدِلَتْ شَهَادَةُ الزُّورِ بِالشِّرْكِ بِاللَّهِ" ثَلَاثَ مَرَّاتٍ، ثُمَّ تَلَا هَذِهِ الْآيَةَ: {وَاجْتَنِبُوا قَوْلَ الزُّورِ} إِلَى آخِرِ الْآيَةِ. (د,ت,جه)', 'ഖുറൈമുബ്നു ഫാതികിനിൽ അസദീ(റ): റസൂലുല്ലാഹി(സ) സുബ്ഹി നിസ്കാരം നിർവ്വഹിച്ചു. അവിടന്ന് തിരിഞ്ഞപ്പോൾ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: "കള്ളസാക്ഷ്യം വഹിക്കൽ അല്ലാഹുവിൽ പങ്കുചേർക്കലിനോട് കിടയൊത്തിരിക്കുന്നു." ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. പിന്നീട് അവിടുന്ന് ഈ സൂക്തം ഓതി: ''കള്ളവാക്യങ്ങൾ നിങ്ങൾ ഒഴിവാക്കുകയും ചെയ്യുക'' ആ സൂക്തത്തിന്റെ അവസാനം വരെ. (ദ,തു,ജ)', 'خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ', 'ഖുറൈമുബ്നു ഫാതികിനിൽ അസദീ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 434, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ" ثَلَاثًا. قَالُوا: بَلَى، يَا رَسُولَ اللَّهِ. قَالَ: "الْإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ". وَجَلَسَ، وَكَانَ مُتَّكِئًا. فَقَالَ: "أَلَا، وَقَوْلُ الزُّورِ". فَمَا زَالَ يُكَرِّرُهَا، حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ. (خ)', 'അബൂബക്റ(റ): നബി(സ) പറഞ്ഞു: "വൻദോഷങ്ങളിൽ ഏറ്റവും വലുത് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ ദൂതരേ. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവിൽ പങ്കുചേർക്കലും മാതാപിതാക്കളോട് അപമര്യാദയായി പെരുമാറലുമാണ്." തിരുമേനി(സ) ചാരിനിൽക്കുകയായിരുന്നു, അവിടന്ന് ഇരുന്നു. എന്നിട്ട് പറഞ്ഞു: "അറിയണേ, കള്ളവാക്യം പറയലുമാണ്." അത് അവിടന്ന് ആവർത്തിച്ച് കൊണ്ടേയിരുന്നു, അവിടന്ന് നിർത്തിയിരുന്നെങ്കിൽ എന്ന് ഞങ്ങൾ ആഗ്രഹിക്കുന്നത് വരെ. (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَنْ تَزُولَ قَدَمَا شَاهِدِ الزُّورِ حَتَّى يُوجِبَ اللَّهُ لَهُ النَّارَ". [ز: فيه راو متّفق على ضعفه] (جه)', 'ഇബ്നുഉമർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "കള്ളസാക്ഷ്യം നിന്നവന്റെ കാൽപ്പാദം നീങ്ങുകയില്ല, അല്ലാഹു അവന് നരകം നിർബന്ധമാക്കുന്നത് വരെ." (ഏകാഭിപ്രായപ്രകാരം ബലഹീനതയുള്ള ഒരാൾ ഇതിലുണ്ട്) (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ദ']::text[], 'ز: فيه راو متّفق على ضعفه', null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَدَّ شَهَادَةَ الْخَائِنِ وَالْخَائِنَةِ، وَذِي الْغِمْرِ عَلَى أَخِيهِ، وَرَدَّ شَهَادَةَ الْقَانِعِ لِأَهْلِ الْبَيْتِ وَأَجَازَهَا لِغَيْرِهِمْ. وَفِي رِوَايَةٍ: "لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا خَائِنَةٍ، وَلَا زَانٍ وَلَا زَانِيَةٍ، وَلَا ذِي غِمْرٍ عَلَى أَخِيهِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): വഞ്ചകന്റെയും വഞ്ചകിയുടെയും തന്റെ സഹോദരനോട് പകയുള്ളവന്റെയും സാക്ഷിത്വം റസൂലുല്ലാഹി(സ) റദ്ദ് ചെയ്തു. ഒരു കുടുംബത്തിനനുകൂലമായി അവരുടെ ആശ്രിതന്റെ സാക്ഷിത്വം അവിടന്ന് റദ്ദ് ചെയ്യുകയുണ്ടായി. ആ സാക്ഷിത്വം മറ്റുള്ളവർക്ക് നൽകുകയും ചെയ്തു. മറ്റൊരു നിവേദനത്തിൽ: "വഞ്ചകന്റെയും വഞ്ചകിയുടെയും വ്യഭിചാരിയുടെയും അഭിസാരികയുടെയും സഹോദരനോട് പകവെക്കുന്നവന്റെയും സാക്ഷിത്വം അനുവദനീയമല്ല." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=91), 1, 'وَفِي رِوَايَةٍ: "لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا خَائِنَةٍ، وَلَا زَانٍ وَلَا زَانِيَةٍ، وَلَا ذِي غِمْرٍ عَلَى أَخِيهِ". (د,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "വഞ്ചകന്റെയും വഞ്ചകിയുടെയും വ്യഭിചാരിയുടെയും അഭിസാരികയുടെയും സഹോദരനോട് പകവെക്കുന്നവന്റെയും സാക്ഷിത്വം അനുവദനീയമല്ല." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا خَائِنَةٍ، وَلَا مَجْلُودٍ حَدًّا وَلَا مَجْلُودَةٍ، وَلَا ذِي غِمْرٍ لِأَخِيهِ، وَلَا مُجَرَّبِ شَهَادَةٍ، وَلَا الْقَانِعِ أَهْلَ الْبَيْتِ لَهُمْ، وَلَا ظَنِينٍ فِي وَلَاءٍ وَلَا قَرَابَةٍ". (ت)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "വഞ്ചകന്റെയും വഞ്ചകിയുടെയും ഹദ്ദടിക്കപ്പെട്ടവന്റെയും ഹദ്ദടിക്കപ്പെട്ടവളുടെയും സഹോദരനോട് പകയുള്ളവന്റെയും, സാക്ഷിത്വം പരീക്ഷിച്ചറിഞ്ഞവന്റെയും ഒരു കുടുംബത്തിന് അനുകൂലമായി അവരോട് ആശ്രയിച്ചുകഴിയുന്നവന്റെയും ഉടമാവകാശത്തിലോ കുടുംബബന്ധത്തിലോ സംശയിക്കപ്പെടുന്നവന്റെയും സാക്ഷിത്വം അനുവദനീയമല്ല." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَجُوزُ شَهَادَةُ بَدَوِيٍّ عَلَى صَاحِبِ قَرْيَةٍ". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ഒരു ഗ്രാമവാസിക്കെതിരെ ഒരു മരുഭൂനിവാസിയുടെ സാക്ഷിത്വം അനുവദനീയമല്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 435, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنِ الشَّعْبِيِّ: أَنَّ رَجُلًا مِنَ الْمُسْلِمِينَ حَضَرَتْهُ الْوَفَاةُ بِدَقُوقَاءَ هَذِهِ، وَلَمْ يَجِدْ أَحَدًا مِنَ الْمُسْلِمِينَ يُشْهِدُهُ عَلَى وَصِيَّتِهِ، فَأَشْهَدَ رَجُلَيْنِ مِنْ أَهْلِ الْكِتَابِ، فَقَدِمَا الْكُوفَةَ، فَأَتَيَا أَبَا مُوسَى الْأَشْعَرِيَّ رَضِيَ اللهُ عَنْهُ فَأَخْبَرَاهُ، وَقَدِمَا بِتَرِكَتِهِ وَوَصِيَّتِهِ، فَقَالَ الْأَشْعَرِيُّ: هَذَا أَمْرٌ لَمْ يَكُنْ بَعْدَ الَّذِي كَانَ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَحْلَفَهُمَا بَعْدَ الْعَصْرِ بِاللَّهِ: مَا خَانَا وَلَا كَذَبَا وَلَا بَدَّلَا وَلَا كَتَمَا وَلَا غَيَّرَا، وَإِنَّهَا لَوَصِيَّةُ الرَّجُلِ وَتَرِكَتُهُ. فَأَمْضَى شَهَادَتَهُمَا. (د)', 'ശഅബീ(റ): മുസ്ലിംകളിൽപ്പെട്ട ഒരാൾ ഈ ദഖൂഖാഇൽ വെച്ച് മരണാസന്നനായി. അയാൾക്ക് മുസ്ലിംകളിൽപ്പെട്ട ഒരാളെയും തന്റെ ഔസ്യത്തിന് സാക്ഷിയായി ലഭിച്ചില്ല. അങ്ങനെ അയാൾ ഗ്രന്ഥക്കാരിൽ നിന്നുള്ള രണ്ട് പേരെ സാക്ഷി നിർത്തി. അവരിരുവരും കൂഫയിലേക്ക് ചെന്നു. അനന്തരം അബൂമൂസൽ അശ്അരീ(റ)വിന്റെ അടുക്കൽ ചെന്ന് അദ്ദേഹത്തോട് വിവരം ധരിപ്പിച്ചു. അവർ അയാളുടെ ഔസ്യത്തും അനന്തരവുമായിട്ടായിരുന്നു വന്നിരുന്നത്. അപ്പോൾ അശ്അരീ(റ) പറഞ്ഞു: റസൂലുല്ലാഹി(സ)യുടെ കാലം തൊട്ട് ഇതുവരെ ഉണ്ടാവാത്ത ഒരു കാര്യമാണിത്. അങ്ങനെ അദ്ദേഹം രണ്ടുപേരെയും അസ്വറിന് ശേഷം അല്ലാഹുവിന്റെ പേരിൽ സത്യം ചെയ്യിച്ചു. അവരിരുവരും വഞ്ചിച്ചിട്ടില്ല, കള്ളം പറഞ്ഞിട്ടില്ല, മാറ്റിമറിച്ചില്ല, മറച്ചുവെച്ചില്ല, വ്യത്യാസപ്പെടുത്തിയിട്ടില്ല, നിശ്ചയം, ഇത് ആ മനുഷ്യന്റെ ഒസ്യത്തും അയാളുടെ അനന്തരവുമാണ് എന്നെല്ലാം സത്യം ചെയ്യിച്ചു. അങ്ങനെ അദ്ദേഹം അവരിരുവരുടെയും സാക്ഷിത്വം നടപ്പാക്കി. (ദ)', 'الشَّعْبِيِّ', 'ശഅബീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 436, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَجُلٌ مِنْ بَنِي سَهْمٍ مَعَ تَمِيمٍ الدَّارِيِّ وَعُدَيِّ بْنِ بَدَّاءٍ، فَمَاتَ السَّهْمِيُّ بِأَرْضٍ لَيْسَ بِهَا مُسْلِمٌ، فَلَمَّا قَدِمَا بِتَرِكَتِهِ فَقَدُوا جَامَ فِضَّةٍ مُخَوَّصًا بِالذَّهَبِ، فَأَحْلَفَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ وُجِدَ الْجَامُ بِمَكَّةَ، فَقَالُوا: اشْتَرَيْنَاهُ مِنْ تَمِيمٍ وَعُدَيٍّ، فَقَامَ رَجُلَانِ مِنْ أَوْلِيَاءِ السَّهْمِيِّ فَحَلَفَا: لَشَهَادَتُنَا أَحَقُّ مِنْ شَهَادَتِهِمَا، وَإِنَّ الْجَامَ لِصَاحِبِهِمْ. قَالَ: فَنَزَلَتْ فِيهِمْ: {يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ...} [المائدة: ١٠٦]. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ബനൂസഹ്മിൽപ്പെട്ട ഒരാൾ തമീമുദ്ദാരീ(റ)വിന്റെയും അദിയ്യുനിബ്നു ബദ്ദാഅ്(റ)വിന്റെയും കൂടെ യാത്രപുറപ്പെട്ടു. അങ്ങനെ ആ സഹ്മിക്കാരൻ, ഒരു മുസ്ലിമുമില്ലാത്ത നാട്ടിൽ വെച്ച് മരിച്ചു. അവരിരുവരും ഇദ്ദേഹത്തിന്റെ അനന്തരവുമായി വന്നപ്പോൾ ഉപരിതലം സ്വർണ്ണം കൊണ്ടലങ്കരിച്ച ഒരു വെള്ളിക്കപ്പ് അവർക്ക് നഷ്ടപ്പെട്ടു. അതിനാൽ അവരിരുവരെയും റസൂലുല്ലാഹി(സ) സത്യം ചെയ്യിച്ചു. പിന്നീട് ആ വെള്ളിക്കപ്പ് മക്കയിൽ വെച്ച് ലഭിച്ചു. അവർ പറഞ്ഞു: ഞങ്ങൾ അത് തമീമിൽ നിന്നും അദിയ്യിൽ നിന്നും വാങ്ങിയതാണ്. അപ്പോൾ ആ സഹ്മിക്കാരന്റെ രണ്ട് കൈകാര്യകർത്താക്കൾ എണീറ്റുനിന്ന് സത്യം ചെയ്തു: അവരിരുവരുടെയും സാക്ഷിത്വത്തേക്കാൾ ഞങ്ങളുടെ സാക്ഷിത്വം തന്നെയാണ് ഏറ്റവും സത്യമായുള്ളത്, നിശ്ചയം ആ വെള്ളിപ്പാത്രം അവരുടെ ആളുടേത് തന്നെയാണ്. നിവേദകൻ പറഞ്ഞു: അങ്ങനെ അവരുടെ വിഷയത്തിലാണ്: ''സത്യവിശ്വാസികളേ. നിങ്ങളിലാർക്കെങ്കിലും മരണമെത്തിയാൽ നിങ്ങൾക്കിടയിലെ സാക്ഷിത്വം...'' (മാഇദ: 106) എന്ന സൂക്തമിറങ്ങിയത്. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'المائدة: ١٠٦', null, 436, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: {فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ} [المائدة: ٤٢] فَنُسِخَتْ، قَالَ: {فَاحْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ} [المائدة: ٤٧] (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അവർ താങ്കളുടെ സന്നിധിയിൽ വന്നാൽ അവർക്കിടയിൽ വിധിപറയുക, അല്ലെങ്കിൽ അവരിൽ നിന്ന് തിരിഞ്ഞുകളയുക.'' (മാഇദ: 42) ഈ സൂക്തം ദുർബ്വലമാക്കപ്പെട്ടു. ഇജിജ്ഗമ പറഞ്ഞു: ''അല്ലാഹു ഇറക്കിയതു കൊണ്ട് അവർക്കിടയിൽ താങ്കൾ വിധിപറയുക.'' (മാഇദ: 47) (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'المائدة: ٤٧', null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ: {فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ} [المائدة: ٤٢] الْآيَةُ، قَالَ: كَانَ بَنُو النَّضِيرِ إِذَا قَتَلُوا مِنْ بَنِي قُرَيْظَةَ أَدَّوْا نِصْفَ الدِّيَةِ، وَإِذَا قَتَلَ بَنُو قُرَيْظَةَ مِنْ بَنِي النَّضِيرِ أَدَّوْا إِلَيْهِمُ الدِّيَةَ كَامِلَةً، فَسَوَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمْ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അവർ താങ്കളുടെയടുക്കൽ വന്നാൽ അവർക്കിടയിൽ താങ്കൾ വിധിപറയുക, അല്ലെങ്കിൽ അവരിൽ നിന്ന് തിരിഞ്ഞുകളയുക. താങ്കൾ വിധിപറഞ്ഞാൽ നീതി പൂർവ്വം അവർക്കിടയിൽ താങ്കൾ വിധിക്കുക'' (മാഇദ: 42) എന്ന സൂക്തം ഇറങ്ങി. നിവേദകൻ: ബനൂന്നളീർ ഗോത്രക്കാർ ബനൂഖുറൈള ഗോത്രക്കാരിൽ നിന്ന് ആരെയെങ്കിലും കൊന്നാൽ നഷ്ടപരിഹാരത്തിന്റെ പകുതി നൽകുമായിരുന്നു. ബനൂഖുറൈളക്കാർ ബനൂന്നളീറിൽ നിന്ന് ആരെയെങ്കിലും കൊന്നാൽ പൂർണ്ണനഷ്ടപരിഹാരം നൽകുകയും ചെയ്യുമായിരുന്നു. അങ്ങനെ നബി(സ) അവർക്കിടയിൽ സമത്വം സൃഷ്ടിച്ചു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], 'المائدة: ٤٢', null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنِ الْأَشْعَثِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنَ الْيَهُودِ أَرْضٌ، فَجَحَدَنِي، فَقَدَّمْتُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَكَ بَيِّنَةٌ". قُلْتُ: لَا. قَالَ لِلْيَهُودِيِّ: "احْلِفْ". قُلْتُ: يَا رَسُولَ اللَّهِ، إِذًا يَحْلِفُ وَيَذْهَبُ بِمَالِي؟ فَأَنْزَلَ اللَّهُ: {إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا} [آل عمران: ٧٧] إِلَى آخِرِ الْآيَةِ. (خ,ت,جه)', 'അശ്അസ്(റ): എനിക്കും ജൂതരിലൊരാൾക്കുമിടയിൽ ഒരു ഭൂമി സംബന്ധമായ ഇടപാട് ഉണ്ടായിരുന്നു. അയാൾ അതെനിക്ക് നിഷേധിച്ചു. ഞാൻ പ്രശ്നം നബി(സ)യുടെ മുന്നിൽ വെച്ചു. അപ്പോൾ എന്നോട് നബി(സ) ചോദിച്ചു: "താങ്കൾക്ക് തെളിവുണ്ടോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. തിരുമേനി(സ) ജൂതനോട് പറഞ്ഞു: "നീ സത്യം ചെയ്യുക." ഞാൻ പറഞ്ഞു: അങ്ങനെയെങ്കിൽ അവൻ സത്യം ചെയ്യുകയും എന്റെ മുതലുമായി പോകുകയും ചെയ്യും. അപ്പോൾ അല്ലാഹു, ''നിശ്ചയം അല്ലാഹുവിന്റെ കരാറിലും തങ്ങളുടെ സത്യത്തിലുമായി വില വാങ്ങുന്നവർ'' (ആലുഇംറാൻ: 77) എന്ന സൂക്തം അവസാനം വരെ ഇറക്കി. (ബു,തു,ജ)', 'الْأَشْعَثِ', 'അശ്അസ്(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], 'آل عمران: ٧٧', null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَعْنِي لِلْيَهُودِ: "أَنْشُدُكُمْ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى، مَا تَجِدُونَ فِي التَّوْرَاةِ عَلَى مَنْ زَنَى". وَسَاقَ الْحَدِيثَ فِي قِصَّةِ الرَّجْمِ. وَفِي رِوَايَةٍ: عَنْ عِكْرِمَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ، يَعْنِي لِابْنِ صُورِيَا: "أُذَكِّرُكُمْ بِاللَّهِ الَّذِي نَجَّاكُمْ مِنْ آلِ فِرْعَوْنَ، وَأَقْطَعَكُمُ الْبَحْرَ، وَظَلَّلَ عَلَيْكُمُ الْغَمَامَ، وَأَنْزَلَ عَلَيْكُمُ الْمَنَّ وَالسَّلْوَى، وَأَنْزَلَ عَلَيْكُمُ التَّوْرَاةَ عَلَى مُوسَى: أَتَجِدُونَ فِي كِتَابِكُمُ الرَّجْمَ". قَالَ: ذَكَّرْتَنِي بِعَظِيمٍ، وَلَا يَسَعُنِي أَنْ أَكْذِبَكَ، ... وَسَاقَ الْحَدِيثَ. (د)', 'അബൂഹുറൈറ(റ): നബി(സ) ജൂതന്മാരോട് ചോദിച്ചു: "മൂസാ(അ)ക്ക് തൗറാത്തിറക്കിയ അല്ലാഹുവിനെക്കൊണ്ട് ഞാൻ നിങ്ങളോട് സത്യം ചെയ്യിക്കുന്നു: വ്യഭിചരിച്ചവന്റെ മേൽ എന്ത് ശിക്ഷയാണ് തൗറാത്തിൽ നിങ്ങൾ കാണുന്നത്?" അങ്ങനെ എറിഞ്ഞുകൊല്ലുന്ന സംഭവത്തിലെ ഹദീസ് നിവേദകൻ പറഞ്ഞു. മറ്റൊരു നിവേദനത്തിൽ: ഇക്രിമ(റ): നബി(സ) ഇബ്നുസൂരിയായോട് ചോദിച്ചു: "ഫിർഔന്റെ ആളുകളിൽ നിന്ന് നിങ്ങളെ രക്ഷിക്കുകയും നിങ്ങളെ കടൽ കടത്തിവിടുകയും കാർമേഘം കൊണ്ട് നിഴലിട്ടുതരികയും, തേൻകട്ടിയും കാടപ്പക്ഷിയും നിങ്ങൾക്കായി ഇറക്കുകയും, നിങ്ങൾക്കായി മൂസാ നബി(അ)ക്ക് തൗറാത്തിറക്കുകയും ചെയ്ത അല്ലാഹുവിനെക്കൊണ്ട് ഞാൻ നിങ്ങളെ ഓർമ്മപ്പെടുത്തുന്നു. നിങ്ങളുടെ ഗ്രന്ഥത്തിൽ റജ്മിനെക്കുറിച്ച് (എറിഞ്ഞുകൊല്ലുന്നതിനെക്കുറിച്ച്) നിങ്ങൾ കാണുന്നുണ്ടോ?" അയാൾ പറഞ്ഞു: അവിടുന്നെനിക്ക് വലിയ കാര്യമാണ് ഉണർത്തിത്തന്നത്. എനിക്കങ്ങയോട് കള്ളം പറയാൻ വയ്യ. ... ഹദീസ് തുടർന്നു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 438, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=99), 1, 'وَفِي رِوَايَةٍ: عَنْ عِكْرِمَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ، يَعْنِي لِابْنِ صُورِيَا: "أُذَكِّرُكُمْ بِاللَّهِ الَّذِي نَجَّاكُمْ مِنْ آلِ فِرْعَوْنَ، وَأَقْطَعَكُمُ الْبَحْرَ، وَظَلَّلَ عَلَيْكُمُ الْغَمَامَ، وَأَنْزَلَ عَلَيْكُمُ الْمَنَّ وَالسَّلْوَى، وَأَنْزَلَ عَلَيْكُمُ التَّوْرَاةَ عَلَى مُوسَى: أَتَجِدُونَ فِي كِتَابِكُمُ الرَّجْمَ". قَالَ: ذَكَّرْتَنِي بِعَظِيمٍ، وَلَا يَسَعُنِي أَنْ أَكْذِبَكَ، ... وَسَاقَ الْحَدِيثَ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: ഇക്രിമ(റ): നബി(സ) ഇബ്നുസൂരിയായോട് ചോദിച്ചു: "ഫിർഔന്റെ ആളുകളിൽ നിന്ന് നിങ്ങളെ രക്ഷിക്കുകയും നിങ്ങളെ കടൽ കടത്തിവിടുകയും കാർമേഘം കൊണ്ട് നിഴലിട്ടുതരികയും, തേൻകട്ടിയും കാടപ്പക്ഷിയും നിങ്ങൾക്കായി ഇറക്കുകയും, നിങ്ങൾക്കായി മൂസാ നബി(അ)ക്ക് തൗറാത്തിറക്കുകയും ചെയ്ത അല്ലാഹുവിനെക്കൊണ്ട് ഞാൻ നിങ്ങളെ ഓർമ്മപ്പെടുത്തുന്നു. നിങ്ങളുടെ ഗ്രന്ഥത്തിൽ റജ്മിനെക്കുറിച്ച് (എറിഞ്ഞുകൊല്ലുന്നതിനെക്കുറിച്ച്) നിങ്ങൾ കാണുന്നുണ്ടോ?" അയാൾ പറഞ്ഞു: അവിടുന്നെനിക്ക് വലിയ കാര്യമാണ് ഉണർത്തിത്തന്നത്. എനിക്കങ്ങയോട് കള്ളം പറയാൻ വയ്യ. ... ഹദീസ് തുടർന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَقْرَأُ فِي الْمَسْجِدِ، فَقَالَ: "رَحِمَهُ اللَّهُ، لَقَدْ أَذْكَرَنِي كَذَا وَكَذَا آيَةً أَسْقَطْتُهُنَّ مِنْ سُورَةِ كَذَا وَكَذَا". (خ)', 'ആഇശ(റ): പള്ളിയിലിരുന്ന് ഒരാൾ ഓതുന്നത് നബി(സ) കേട്ടു. അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹു അയാൾക്ക് കാരുണ്യം ചൊരിയട്ടെ. അയാൾ എനിക്ക് ഇന്നാലിന്ന സൂക്തങ്ങൾ ഉണർത്തിത്തന്നു. ഇന്നാലിന്ന സൂറത്തിൽ നിന്ന് ഞാൻ ആ സൂക്തങ്ങളെ വിട്ടുകളഞ്ഞിരുന്നു." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 438, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا فِي رِوَايَةٍ قَالَتْ: تَهَجَّدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِي، فَسَمِعَ صَوْتَ عَبَّادٍ يُصَلِّي فِي الْمَسْجِدِ، فَقَالَ: "يَا عَائِشَةُ، أَصَوْتُ عَبَّادٍ هَذَا". قُلْتُ: نَعَمْ. قَالَ: "اللَّهُمَّ ارْحَمْ عَبَّادًا". (خ)', 'ആഇശ(റ): ഒരു റിപ്പോർട്ടിൽ മഹതി പറഞ്ഞു: തിരുനബി(സ) തഹജ്ജുദ് നിസ്കാരം എന്റെ വീട്ടിൽ വെച്ച് നിർവ്വഹിച്ചു. അപ്പോൾ പള്ളിയിൽ നിസ്കരിക്കുകയായിരുന്ന അബ്ബാദ്(റ)വിന്റെ ശബ്ദം തിരുമേനി(സ) കേട്ടു. അവിടുന്ന് പറഞ്ഞു: "ആഇശാ! അബ്ബാദിന്റെ ശബ്ദമല്ലേ അത്?" ഞാൻ പറഞ്ഞു: അതെ. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവേ, നീ അബ്ബാദിന് കരുണ ചെയ്യണേ!" (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 438, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجَازَ شَهَادَةَ أَهْلِ الْكِتَابِ، بَعْضِهِمْ عَلَى بَعْضٍ. [ز: في إسناده ضعيف] (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഗ്രന്ഥത്തിന്റെ ആളുകളിൽ ചിലർ ചിലർക്കെതിരിൽ സാക്ഷി നിൽക്കൽ റസൂലുല്ലാഹി(സ) അനുവദിച്ചു. ഇതിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 438, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَعَا رَجُلًا مِنْ عُلَمَاءِ الْيَهُودِ، فَقَالَ: "أَنْشُدُكَ بِالَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى". (م,د,ن,جه)', 'ബറാഉബ്നു ആസിബ്(റ): ജൂത പണ്ഡിതരിൽപ്പെട്ട ഒരാളെ റസൂലുല്ലാഹി(സ) ക്ഷണിച്ചു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "മൂസാ(അ)ന്റെ മേൽ തൗറാത്ത് ഇറക്കിയവനെക്കൊണ്ട് ഞാൻ നിന്നെ സത്യം ചെയ്യിക്കുന്നു." (മു,ദ,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِيَهُودِيَّيْنِ: "أَنْشَدْتُكُمَا بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى عَلَيْهِ السَّلَامُ". (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂലുല്ലാഹി(സ) രണ്ട് ജൂതരോട് പറഞ്ഞു: "ഞാൻ മൂസാ(അ)ന്റെ മേൽ തൗറാത്ത് ഇറക്കിയ അല്ലാഹുവിനെക്കൊണ്ട് നിങ്ങളെ ഞാൻ സത്യം ചെയ്യിക്കുന്നു." (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أُمِّ كُلْثُومٍ بِنْتِ عُقْبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ فَيَنْمِي خَيْرًا أَوْ يَقُولُ خَيْرًا". (خ)', 'ഉമ്മുകുൽസൂം ബിൻതു ഉഖ്ബ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ജനങ്ങൾക്കിടയിൽ പ്രശ്നം പരിഹരിക്കുകയും അങ്ങനെ നന്മ കൂട്ടിപ്പറയുകയും അല്ലെങ്കിൽ നന്മ പറയുകയും ചെയ്യുന്നുവെങ്കിൽ അവൻ കള്ളം പറയുന്നവനല്ല." (ബു)', 'أُمِّ كُلْثُومٍ بِنْتِ عُقْبَةَ', 'ഉമ്മുകുൽസൂം ബിൻതു ഉഖ്ബ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِي اللَّهُ عَنْهُمَا قَالَ: اعْتَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذِي الْقَعْدَةِ فَأَبَى أَهْلُ مَكَّةَ أَنْ يَدَعُوهُ يَدْخُلُ مَكَّةَ حَتَّى قَاضَاهُمْ عَلَى أَنْ يُقِيمَ بِهَا ثَلَاثَةَ أَيَّامٍ، فَلَمَّا كَتَبُوا الْكِتَابَ، كَتَبُوا: هَذَا مَا قَاضَى عَلَيْهِ مُحَمَّدٌ رَسُولُ اللَّهِ فَقَالُوا: لَا نُقِرُّ بِهَا فَلَوْ نَعْلَمُ أَنَّكَ رَسُولُ اللَّهِ مَا مَنَعْنَاكَ لَكِنْ أَنْتَ مُحَمَّدُ بْنُ عَبْدِاللَّهِ فَقَالَ: أَنَا رَسُولُ اللَّهِ وَأَنَا مُحَمَّدُ بْنُ عَبْدِاللَّهِ، ثُمَّ قَالَ لِعَلِيٍّ: امْحُ رَسُولَ اللَّهِ، فَقَالَ: لَا وَاللَّهِ لَا أَمْحُوكَ أَبَدًا، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْكِتَابَ فَكَتَبَ: هَذَا مَا قَاضَى عَلَيْهِ مُحَمَّدُ بْنُ عَبْدِاللَّهِ لَا يُدْخِلُ مَكَّةَ سِلَاحًا إِلَّا فِي الْقِرَابِ، وَأَنْ لَا يَخْرُجَ مِنْ أَهْلِهَا بِأَحَدٍ إِنْ أَرَادَ أَنْ يَتَّبِعَهُ، وَأَنْ لَا يَمْنَعَ أَحَدًا مِنْ أَصْحَابِهِ أَرَادَ أَنْ يُقِيمَ بِهَا، فَلَمَّا دَخَلَهَا وَمَضَى الْأَجَلُ أَتَوْا عَلِيًّا، فَقَالُوا: قُلْ لِصَاحِبِكَ اخْرُجْ عَنَّا، فَقَدْ مَضَى الْأَجَلُ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَبِعَتْهُمُ ابْنَةُ حَمْزَةَ: يَا عَمِّ، يَا عَمِّ، فَتَنَاوَلَهَا عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ فَأَخَذَ بِيَدِهَا وَقَالَ لِفَاطِمَةَ رَضِيَ اللَّهُ عَنْهَا: دُونَكِ ابْنَةَ عَمِّكِ احْمِلِيهَا، قَالَ: فَاخْتَصَمَ فِيهَا عَلِيٌّ وَزَيْدٌ وَجَعْفَرٌ فَقَالَ عَلِيٌّ: أَنَا أَحَقُّ بِهَا وَهِيَ ابْنَةُ عَمِّي، وَقَالَ جَعْفَرٌ: ابْنَةُ عَمِّي وَخَالَتُهَا تَحْتِي، وَقَالَ زَيْدٌ: ابْنَةُ أَخِي، فَقَضَى بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَالَتِهَا، وَقَالَ: "الْخَالَةُ بِمَنْزِلَةِ الْأُمِّ". وَقَالَ لِعَلِيٍّ: "أَنْتَ مِنِّي وَأَنَا مِنْكَ". وَقَالَ لِجَعْفَرٍ: "أَشْبَهْتَ خَلْقِي وَخُلُقِي". وَقَالَ لِزَيْدٍ: "أَنْتَ أَخُونَا وَمَوْلَانَا". (خ)', 'ബറാഉബ്നു ആസിബ്(റ): ദുൽഖഅ്ദയിൽ തിരുനബി(സ) ഉംറ നിർവ്വഹിച്ചു. തിരുമേനി(സ) മക്കയിൽ കടന്ന് അവിടെ തങ്ങുന്നത് മക്കക്കാർ തടഞ്ഞു. അങ്ങനെ അവിടന്ന് അവരോട് മൂന്ന് ദിവസം തങ്ങാമെന്ന് സന്ധി ചെയ്തു. അവർ രേഖ എഴുതിയപ്പോൾ ഇങ്ങനെ എഴുതി: ഇത് അല്ലാഹുവിന്റെ ദൂതൻ മുഹമ്മദ് സന്ധി ചെയ്യുന്നതാണ്. അവർ പറഞ്ഞു: ഞങ്ങളത് സമ്മതിക്കില്ല. താങ്കൾ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് ഞങ്ങൾ മനസ്സിലാക്കുന്നുണ്ടെങ്കിൽ ഞങ്ങൾ താങ്കളെ തടയുമായിരുന്നില്ല. പക്ഷേ, താങ്കൾ അബ്ദുല്ലയുടെ മകൻ മുഹമ്മദ് ആണ്. അവിടന്ന് പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണ്, ഞാൻ അബ്ദുല്ലയുടെ മകൻ മുഹമ്മദ് ആണ്." പിന്നീട് അവിടന്ന് അലി(റ)വിനോട് പറഞ്ഞു: "റസൂലുല്ലാഹി എന്നത് നീക്കം ചെയ്യുക." അലി(റ) പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ, ഞാനൊരിക്കലും താങ്കളെ മായ്ക്കുകയില്ല. അപ്പോൾ റസൂൽ(സ) ആ എഴുത്ത് എടുത്ത് ഇപ്രകാരം എഴുതി: ഉറയിലിട്ടുകൊണ്ടല്ലാതെ ഒരു ആയുധവും മക്കയിലേക്ക് കടത്തുകയില്ലെന്നും; മക്കക്കാരിൽ നിന്നാരെങ്കിലും തന്നെ പിൻപറ്റിയാൽ, അവനെ കൊണ്ടുപോവുകയില്ലെന്നും; തന്റെ അനുയായികളിൽ നിന്ന് മക്കയിൽ തങ്ങാൻ ഉദ്ദേശിക്കുന്ന ഒരാളെയും തടയുകയില്ലെന്നും; അബ്ദുല്ലയുടെ മകൻ മുഹമ്മദ് സന്ധി ചെയ്യുന്ന പത്രമാണിത്. അങ്ങനെ അവർ അവിടെ പ്രവേശിക്കുകയും സമയം കഴിയുകയും ചെയ്തപ്പോൾ അവർ അലി(റ)വിന്റെ അടുത്തെത്തി പറഞ്ഞു: താങ്കളുടെയാളോട് ഞങ്ങളുടെ അടുത്ത് നിന്നും പുറപ്പെടാൻ പറയൂ, സമയം കഴിഞ്ഞിരിക്കുന്നു. അങ്ങനെ തിരുനബി(സ) പുറപ്പെട്ടു. അപ്പോൾ ഹംസ(റ)വിന്റെ പുത്രി, പിതൃവ്യാ, പിതൃവ്യാ എന്ന് വിളിച്ചുകൊണ്ട് അവരെ പിന്തുടർന്നു. അപ്പോൾ അലി(റ) അവളെ തന്റെ കൈയിൽ പിടിച്ചു. അദ്ദേഹം ഫാത്തിമ(റ)യോട് പറഞ്ഞു: നിന്റെ പിതൃവ്യപുത്രിയെയും കൂടെയെടുക്കൂ. നിവേദകൻ പറഞ്ഞു: അവളുടെ കാര്യത്തിൽ അലി(റ)വും സൈദ്(റ)വും ജഅ്ഫർ(റ)വും തർക്കിച്ചു. അപ്പോൾ അലി(റ) പറഞ്ഞു: ഞാനാണ് അവളോട് ഏറ്റവും ബന്ധപ്പെട്ടവൻ. അവളെന്റെ പിതൃവ്യപുത്രിയാണ്. ജഅ്ഫർ(റ) പറഞ്ഞു: അവൾ എന്റെ പിതൃവ്യപുത്രിയാണ്, അവളുടെ മാതൃസഹോദരി എന്റെ കീഴിലാണ്. സൈദ്(റ) പറഞ്ഞു: അവൾ എന്റെ സഹോദരപുത്രിയാണ്. അപ്പോൾ തിരുനബി(സ) അവളെ അവളുടെ മാതൃസഹോദരിക്കായി വിധിച്ചു. എന്നിട്ട് പറഞ്ഞു: "മാതൃസഹോദരി മാതാവിന്റെ സ്ഥാനത്താണ്." അവിടന്ന് അലി(റ)വിനോട് പറഞ്ഞു: "താങ്കൾ എന്നിൽ നിന്നും ഞാൻ താങ്കളിൽ നിന്നുമാണ്." ജഅ്ഫർ(റ)വിനോട് പറഞ്ഞു: "താങ്കൾ രൂപം കൊണ്ടും സ്വഭാവം കൊണ്ടും എന്നോട് സദൃശമായിരിക്കുന്നു." സൈദ്(റ)വിനോട് പറഞ്ഞു: "താങ്കൾ എന്റെ സഹോദരനും സേവകനുമാണ്." (ബു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 439, 440, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ وَالْحَسَنُ بْنُ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا إِلَى جَنْبِهِ وَهُوَ يُقْبِلُ عَلَى النَّاسِ مَرَّةً وَعَلَيْهِ أُخْرَى وَيَقُولُ: "إِنَّ ابْنِي هَذَا سَيِّدٌ، وَلَعَلَّ اللَّهَ أَنْ يُصْلِحَ بِهِ بَيْنَ فِئَتَيْنِ عَظِيمَتَيْنِ مِنَ الْمُسْلِمِينَ". (خ)', 'അബൂബക്റ(റ): തന്റെ ഒരു വശത്ത് അലി(റ)വിന്റെ മകൻ ഹുസൈൻ(റ) ഉണ്ടായിരിക്കെ, റസൂലുല്ലാഹി(സ) മിമ്പറിൽ നിൽക്കുന്നത് ഞാൻ കണ്ടു. അവിടുന്ന് ഇടക്ക് ജനങ്ങളിലേക്കും ഇടക്ക് അദ്ദേഹത്തിലേക്കും തിരിയുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "നിശ്ചയം എന്റെ ഈ മകൻ നേതാവാണ്. മുസ്ലിംകളിൽപ്പെട്ട രണ്ടു വലിയ വിഭാഗങ്ങൾക്കിടയിൽ അല്ലാഹു ഇവനിലൂടെ പ്രശ്നപരിഹാരം നടത്തുന്നതായിരിക്കും." (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 440, 440, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سمع رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَجُوزُ شَهَادَةُ بَدَوِيٍّ عَلَى صَاحِبِ قَرْيَةٍ". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു മരുഭൂനിവാസി ഒരു പട്ടണനിവാസിക്കെതിരെ സാക്ഷി നിൽക്കാൻ പാടില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يَخْرُجَ سَفَرًا أَقْرَعَ بَيْنَ أَزْوَاجِهِ، فَأَيَّتُهُنَّ خَرَجَ سَهْمُهَا خَرَجَ بِهَا مَعَهُ، فَأَقْرَعَ بَيْنَنَا فِي غَزَاةٍ غَزَاهَا، فَخَرَجَ سَهْمِي، فَخَرَجْتُ مَعَهُ بَعْدَ مَا أُنْزِلَ الْحِجَابُ، فَأَنَا أُحْمَلُ فِي هَوْدَجٍ وَأُنْزَلُ فِيهِ، فَسِرْنَا، حَتَّى إِذَا فَرَغَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ غَزْوَتِهِ تِلْكَ وَقَفَلَ وَدَنَوْنَا مِنَ الْمَدِينَةِ آذَنَ لَيْلَةً بِالرَّحِيلِ، فَقُمْتُ حِينَ آذَنُوا بِالرَّحِيلِ، فَمَشَيْتُ، حَتَّى جَاوَزْتُ الْجَيْشَ، فَلَمَّا قَضَيْتُ شَأْنِي أَقْبَلْتُ إِلَى الرَّحْلِ، فَلَمَسْتُ صَدْرِي، فَإِذَا عِقْدٌ لِي مِنْ جَزْعِ أَظْفَارٍ قَدِ انْقَطَعَ، فَرَجَعْتُ فَالْتَمَسْتُ عِقْدِي، فَحَبَسَنِي ابْتِغَاؤُهُ، فَأَقْبَلَ الَّذِينَ يَرْحَلُونَ لِي، فَاحْتَمَلُوا هَوْدَجِي، فَرَحَلُوهُ عَلَى بَعِيرِيَ الَّذِي كُنْتُ أَرْكَبُ، وَهُمْ يَحْسِبُونَ أَنِّي فِيهِ، وَكَانَ النِّسَاءُ إِذْ ذَاكَ خِفَافًا لَمْ يَثْقُلْنَ وَلَمْ يَغْشَهُنَّ اللَّحْمُ، وَإِنَّمَا يَأْكُلْنَ الْعُلْقَةَ مِنَ الطَّعَامِ، فَلَمْ يَسْتنكِرِ الْقَوْمُ حِينَ رَفَعُوهُ ثِقَلَ الْهَوْدَجِ فَاحْتَمَلُوهُ، وَكُنْتُ جَارِيَةً حَدِيثَةَ السِّنِّ، فَبَعَثُوا الْجَمَلَ وَسَارُوا، فَوَجَدْتُ عِقْدِي بَعْدَ مَا اسْتَمَرَّ الْجَيْشُ، فَجِئْتُ مَنْزِلَهُمْ، وَلَيْسَ فِيهِ أَحَدٌ، فَأَمَمْتُ مَنْزِلِي الَّذِي كُنْتُ بِهِ، فَظَنَنْتُ أَنَّهُمْ سَيَفْقِدُونَنِي فَيَرْجِعُونَ إِلَيَّ، فَبَيْنَا أَنَا جَالِسَةٌ غَلَبَتْنِي عَيْنَايَ، فَنِمْتُ، وَكَانَ صَفْوَانُ بْنُ الْمُعَطَّلِ السُّلَمِيُّ ثُمَّ الذَّكْوَانِيُّ مِنْ وَرَاءِ الْجَيْشِ، فَأَصْبَحَ عِنْدَ مَنْزِلِي، فَرَأَى سَوَادَ إِنْسَانٍ نَائِمٍ فَأَتَانِي، وَكَانَ يَرَانِي قَبْلَ الْحِجَابِ، فَاسْتَيْقَظْتُ بِاسْتِرْجَاعِهِ، حِينَ أَنَاخَ رَاحِلَتَهُ، فَوَطِئَ يَدَهَا فَرَكِبْتُهَا، فَانْطَلَقَ يَقُودُ بِيَ الرَّاحِلَةَ، حَتَّى أَتَيْنَا الْجَيْشَ بَعْدَ مَا نَزَلُوا مُعَرِّسِينَ فِي نَحْرِ الظَّهِيرَةِ، فَهَلَكَ مَنْ هَلَكَ، وَكَانَ الَّذِي تَوَلَّى الإِفْكَ عَبْدُاللهِ بْنُ أُبَيٍّ ابْنُ سَلُولَ، فَقَدِمْنَا الْمَدِينَةَ، فَاشْتَكَيْتُ بِهَا شَهْرًا، وَالنَّاسُ يُفِيضُونَ فِي قَوْلِ أَصْحَابِ الإِفْكِ، وَيَرِيبُنِي فِي وَجَعِي أَنِّي لَا أَرَى مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اللُّطْفَ الَّذِي كُنْتُ أَرَى مِنْهُ حِينَ أَمْرَضُ إِنَّمَا يَدْخُلُ فَيُسَلِّمُ ثُمَّ يَقُولُ كَيْفَ تِيكُمْ، لَا أَشْعُرُ بِشَيْءٍ مِنْ ذَلِكَ حَتَّى نَقَهْتُ، فَخَرَجْتُ أَنَا وَأُمُّ مِسْطَحٍ قِبَلَ الْمَنَاصِعِ مُتَبَرَّزَنَا، لَا نَخْرُجُ إِلَّا لَيْلًا إِلَى لَيْلٍ، وَذَلِكَ قَبْلَ أَنْ نَتَّخِذَ الْكُنُفَ قَرِيبًا مِنْ بُيُوتِنَا، وَأَمْرُنَا أَمْرُ الْعَرَبِ الأُوَلِ فِي الْبَرِّيَّةِ، أَوْ فِي التَّنَزُّهِ، فَأَقْبَلْتُ أَنَا وَأُمُّ مِسْطَحِ بِنْتُ أَبِي رُهْمٍ نَمْشِي فَعَثُرَتْ فِي مِرْطِهَا، فَقَالَتْ: تَعِسَ مِسْطَحٌ، فَقُلْتُ لَهَا: بِئْسَ مَا قُلْتِ، أَتَسُبِّينَ رَجُلًا شَهِدَ بَدْرًا؟ فَقَالَتْ: يَا هَنْتَاهْ، أَلَمْ تَسْمَعِي مَا قَالُوا؟ فَأَخْبَرَتْنِي بِقَوْلِ أَهْلِ الإِفْكِ، فَازْدَدْتُ مَرَضًا عَلَى مَرَضِي، فَلَمَّا رَجَعْتُ إِلَى بَيْتِي دَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ فَقَالَ: "كَيْفَ تِيكُمْ". فَقُلْتُ: ائْذَنْ لِي إِلَى أَبَوَيَّ. قَالَتْ: وَأَنَا حِينَئِذٍ أُرِيدُ أَنْ أَسْتَيْقِنَ الْخَبَرَ مِنْ قِبَلِهِمَا، فَأَذِنَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُ أَبَوَيَّ فَقُلْتُ لِأُمِّي مَا يَتَحَدَّثُ بِهِ النَّاسُ، فَقَالَتْ، يَا بُنَيَّةُ، هَوِّنِي عَلَى نَفْسِكِ الشَّأْنَ، فَوَاللهِ لَقَلَّمَا كَانَتِ امْرَأَةٌ قَطُّ وَضِيئَةٌ عِنْدَ رَجُلٍ يُحِبُّهَا وَلَهَا ضَرَائِرُ إِلَّا أَكْثَرْنَ عَلَيْهَا. فَقُلْتُ: سُبْحَانَ اللهِ. وَلَقَدْ يَتَحَدَّثُ النَّاسُ بِهَذَا، قَالَتْ: فَبِتُّ تِلْكَ اللَّيْلَةَ حَتَّى أَصْبَحْتُ لَا يَرْقَأُ لِي دَمْعٌ وَلَا أَكْتَحِلُ بِنَوْمٍ، ثُمَّ أَصْبَحْتُ، فَدَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِيَّ بْنَ أَبِي طَالِبٍ وَأُسَامَةَ بْنَ زَيْدٍ حِينَ اسْتَلْبَثَ الْوَحْيُ، يَسْتَشِيرُهُمَا فِي فِرَاقِ أَهْلِهِ، فَأَمَّا أُسَامَةُ فَأَشَارَ عَلَيْهِ بِالَّذِي يَعْلَمُ فِي نَفْسِهِ مِنَ الْوُدِّ لَهُمْ، فَقَالَ أُسَامَةُ: أَهْلُكَ يَا رَسُولَ اللهِ، وَلَا نَعْلَمُ وَاللهِ إِلَّا خَيْرًا، وَأَمَّا عَلِيٌّ فَقَالَ: يَا رَسُولَ اللهِ، لَمْ يُضَيِّقِ اللهُ عَلَيْكَ وَالنِّسَاءُ سِوَاهَا كَثِيرٌ، وَسَلِ الْجَارِيَةَ، تَصْدُقْكَ، فَدَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَرِيرَةَ، فَقَالَ: "يَا بَرِيرَةُ، هَلْ رَأَيْتِ فِيهَا شَيْئًا يَرِيبُكِ". فَقَالَتْ بَرِيرَةُ: لَا، وَالَّذِي بَعَثَكَ بِالْحَقِّ، إِنْ رَأَيْتُ مِنْهَا أَمْرًا أَغْمِصُهُ عَلَيْهَا قَطُّ أَكْثَرَ مِنْ أَنَّهَا جَارِيَةٌ حَدِيثَةُ السِّنِّ تَنَامُ عَنِ الْعَجِينِ فَتَأْتِي الدَّاجِنُ فَتَأْكُلُهُ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ يَوْمِهِ، فَاسْتَعْذَرَ مِنْ عَبْدِاللهِ بْنِ أُبَيٍّ ابْنِ سَلُولَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَعْذُرُنِي مِنْ رَجُلٍ بَلَغَنِي أَذَاهُ فِي أَهْلِي، فَوَاللهِ مَا عَلِمْتُ عَلَى أَهْلِي إِلَّا خَيْرًا، وَقَدْ ذَكَرُوا رَجُلًا مَا عَلِمْتُ عَلَيْهِ إِلَّا خَيْرًا، وَمَا كَانَ يَدْخُلُ عَلَى أَهْلِي إِلَّا مَعِي". فَقَامَ سَعْدُ بْنُ مُعَاذٍ، فَقَالَ: يَا رَسُولَ اللهِ، أَنَا وَاللهِ أَعْذُرُكَ مِنْهُ إِنْ كَانَ مِنَ الأَوْسِ ضَرَبْنَا عُنُقَهُ، وَإِنْ كَانَ مِنْ إِخْوَانِنَا مِنَ الْخَزْرَجِ أَمَرْتَنَا فَفَعَلْنَا فِيهِ أَمْرَكَ. فَقَامَ سَعْدُ بْنُ عُبَادَةَ وَهُوَ سَيِّدُ الْخَزْرَجِ، وَكَانَ قَبْلَ ذَلِكَ رَجُلًا صَالِحًا، وَلَكِنِ احْتَمَلَتْهُ الْحَمِيَّةُ، فَقَالَ: كَذَبْتَ، لَعَمْرُ اللهِ لَا تَقْتُلُهُ وَلَا تَقْدِرُ عَلَى ذَلِكَ. فَقَامَ أُسَيْدُ بْنُ حُضَيْرٍ، فَقَالَ: كَذَبْتَ، لَعَمْرُ اللهِ وَاللهِ لَنَقْتُلَنَّهُ، فَإِنَّكَ مُنَافِقٌ تُجَادِلُ عَنِ الْمُنَافِقِينَ. فَثَارَ الْحَيَّانِ: الأَوْسُ وَالْخَزْرَجُ، حَتَّى هَمُّوا، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ، فَنَزَلَ، فَخَفَّضَهُمْ، حَتَّى سَكَتُوا وَسَكَتَ، وَبَكَيْتُ يَوْمِي لَا يَرْقَأُ لِي دَمْعٌ وَلَا أَكْتَحِلُ بِنَوْمٍ، فَأَصْبَحَ عِنْدِي أَبَوَايَ، وَقَدْ بَكَيْتُ لَيْلَتَيْنِ وَيَوْمًا، حَتَّى أَظُنُّ أَنَّ الْبُكَاءَ فَالِقٌ كَبِدِي، قَالَتْ: فَبَيْنَا هُمَا جَالِسَانِ عِنْدِي وَأَنَا أَبْكِي، إِذِ اسْتَأْذَنَتِ امْرَأَةٌ مِنَ الأَنْصَارِ، فَأَذِنْتُ لَهَا، فَجَلَسَتْ تَبْكِي مَعِي، فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَلَسَ، وَلَمْ يَجْلِسْ عِنْدِي مِنْ يَوْمِ قِيلَ فِيَّ مَا قِيلَ قَبْلَهَا، وَقَدْ مَكَثَ شَهْرًا لَا يُوحَى إِلَيْهِ فِي شَأْنِي شَيْءٌ، قَالَتْ: فَتَشَهَّدَ، ثُمَّ قَالَ: "يَا عَائِشَةُ، فَإِنَّهُ بَلَغَنِي عَنْكِ كَذَا وَكَذَا، فَإِنْ كُنْتِ بَرِيئَةً فَسَيُبَرِّئُكِ اللهُ، وَإِنْ كُنْتِ أَلْمَمْتِ بِذَنْبٍ فَاسْتَغْفِرِي اللهَ وَتُوبِي إِلَيْهِ، فَإِنَّ الْعَبْدَ إِذَا اعْتَرَفَ بِذَنْبِهِ ثُمَّ تَابَ تَابَ اللهُ عَلَيْهِ". فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَقَالَتَهُ قَلَصَ دَمْعِي، حَتَّى مَا أُحِسُّ مِنْهُ قَطْرَةً، وَقُلْتُ لِأَبِي: أَجِبْ عَنِّي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: وَاللهِ مَا أَدْرِي مَا أَقُولُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقُلْتُ لِأُمِّي: أَجِيبِي عَنِّي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيمَا قَالَ. قَالَتْ: وَاللهِ مَا أَدْرِي مَا أَقُولُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَتْ: وَأَنَا جَارِيَةٌ حَدِيثَةُ السِّنِّ لَا أَقْرَأُ كَثِيرًا مِنَ الْقُرْآنِ، فَقُلْتُ: وَاللهِ لَقَدْ عَلِمْتُ أَنَّكُمْ سَمِعْتُمْ مَا يَتَحَدَّثُ بِهِ النَّاسُ وَوَقَرَ فِي أَنْفُسِكُمْ وَصَدَّقْتُمْ بِهِ، وَلَئِنْ قُلْتُ لَكُمْ إِنِّي بَرِيئَةٌ، وَاللهُ يَعْلَمُ إِنِّي لَبَرِيئَةٌ لَا تُصَدِّقُونِي بِذَلِكَ، وَلَئِنِ اعْتَرَفْتُ لَكُمْ بِأَمْرٍ وَاللهُ يَعْلَمُ أَنِّي بَرِيئَةٌ لَتُصَدِّقُنِّي، وَاللهِ مَا أَجِدُ لِي وَلَكُمْ مَثَلًا إِلَّا أَبَا يُوسُفَ إِذْ قَالَ: فَصَبْرٌ جَمِيلٌ وَاللهُ الْمُسْتَعَانُ عَلَى مَا تَصِفُونَ. ثُمَّ تَحَوَّلْتُ عَلَى فِرَاشِي وَأَنَا أَرْجُو أَنْ يُبَرِّئَنِي اللهُ، وَلَكِنْ وَاللهِ مَا ظَنَنْتُ أَنْ يُنْزِلَ فِي شَأْنِي وَحْيًا يُتْلَى وَلَأَنَا أَحْقَرُ فِي نَفْسِي مِنْ أَنْ يُتَكَلَّمَ بِالْقُرْآنِ فِي أَمْرِي، وَلَكِنْ كُنْتُ أَرْجُو أَنْ يَرَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي النَّوْمِ، رُؤْيَا يُبَرِّئُنِي اللهُ بِهَا، فَوَاللهِ مَا رَامَ مَجْلِسَهُ وَلَا خَرَجَ أَحَدٌ مِنْ أَهْلِ الْبَيْتِ حَتَّى أُنْزِلَ عَلَيْهِ الْوَحْيُ، فَأَخَذَهُ مَا كَانَ يَأْخُذُهُ مِنَ الْبُرَحَاءِ، حَتَّى إِنَّهُ لَيَتَحَدَّرُ مِنْهُ مِثْلُ الْجُمَانِ مِنَ الْعَرَقِ فِي يَوْمٍ شَاتٍ، فَلَمَّا سُرِّيَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَضْحَكُ، فَكَانَ أَوَّلَ كَلِمَةٍ تَكَلَّمَ بِهَا أَنْ قَالَ لِي: "يَا عَائِشَةُ، احْمَدِي اللهَ فَقَدْ بَرَّأَكِ اللهُ". فَقَالَتْ لِي أُمِّي: قُومِي إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقُلْتُ: لَا وَاللهِ، لَا أَقُومُ إِلَيْهِ وَلَا أَحْمَدُ إِلَّا اللهَ. فَأَنْزَلَ اللهُ تَعَالَى: {إِنَّ الَّذِينَ جَاءُوا بِالإِفْكِ عُصْبَةٌ مِنْكُمْ} الآيَاتِ، فَلَمَّا أَنْزَلَ اللهُ عَزَّ وَجَلَّ هَذَا فِي بَرَاءَتِي قَالَ أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللهُ عَنْهُ: - وَكَانَ يُنْفِقُ عَلَى مِسْطَحِ بْنِ أُثَاثَةَ لِقَرَابَتِهِ مِنْهُ - وَاللهِ لَا أُنْفِقُ عَلَى مِسْطَحٍ شَيْئًا أَبَدًا بَعْدَ مَا قَالَ لِعَائِشَةَ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَلَا يَأْتَلِ أُولُو الْفَضْلِ مِنْكُمْ وَالسَّعَةِ أَنْ يُؤْتُوا أُولِي الْقُرْبَى} إِلَى قَوْلِهِ {غَفُورٌ رَحِيمٌ} فَقَالَ أَبُو بَكْرٍ: بَلَى وَاللهِ إِنِّي لَأُحِبُّ أَنْ يَغْفِرَ اللهُ لِي، فَرَجَعَ إِلَى مِسْطَحٍ الَّذِي كَانَ يُجْرِي عَلَيْهِ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلَ زَيْنَبَ بِنْتَ جَحْشٍ عَنْ أَمْرِي فَقَالَ: "يَا زَيْنَبُ مَا عَلِمْتِ مَا رَأَيْتِ". فَقَالَتْ: يَا رَسُولَ اللهِ، أَحْمِي سَمْعِي وَبَصَرِي، وَاللهِ مَا عَلِمْتُ عَلَيْهَا إِلَّا خَيْرًا، قَالَتْ: وَهِيَ الَّتِي كَانَتْ تُسَامِينِي، فَعَصَمَهَا اللهُ بِالْوَرَعِ. (خ)', 'ആഇശ(റ): തിരുമേനി(സ) ഒരു യാത്ര പുറപ്പെടാനുദ്ദേശിച്ചാൽ തന്റെ പത്നിമാർക്കിടയിൽ നറുക്കിടുകയും നറുക്കിൽ ആരുടെ പേര് കിട്ടിയോ അവരെ കൊണ്ടുപോകുകയുമായിരുന്നു പതിവ്. അതനുസരിച്ച് നബി(സ)യുടെ ഒരു യുദ്ധയാത്രയിൽ നറുക്കിടുകയും എന്റെ പേര് കിട്ടുകയും ഞാൻ തിരുമേനി(സ)യോടൊപ്പം പുറപ്പെടുകയും ചെയ്തു. മറയുടെ വിധി നടപ്പിൽ വന്നതിന് ശേഷമായിരുന്നു അത്. അങ്ങനെ ഞാൻ ഒരു പല്ലക്കിൽ വഹിക്കപ്പെടുകയും വല്ലയിടത്തും ഇറങ്ങേണ്ടി വന്നാൽ ആ പല്ലക്കോടു കൂടെത്തന്നെ ഇറക്കപ്പെടുകയും ചെയ്യും. അപ്രകാരം ഞങ്ങൾ യാത്ര ചെയ്യുകയും അല്ലാഹുവിന്റെ റസൂൽ(സ) ആ യുദ്ധത്തിൽ നിന്ന് വിരമിക്കുകയും മടക്കയാത്ര ചെയ്യുകയും ഞങ്ങൾ മദീനയോടടുക്കുകയും ചെയ്തപ്പോൾ ഒരു രാത്രി യാത്ര തുടരുവാൻ തിരുമേനി(സ) എല്ലാവരെയും വിളിച്ചറിയിച്ചു. അങ്ങനെ അവർ വിളിച്ചപ്പോൾ ഞാൻ എഴുന്നേൽക്കുകയും സൈന്യത്തെ വിട്ട് കടക്കുവോളം നടക്കുകയും ചെയ്തു. ഞാൻ എന്റെ മലമൂത്രവിസർജനാവശ്യങ്ങൾ കഴിഞ്ഞ് വന്നപ്പോൾ വാഹനത്തിന്റെ അടുക്കൽ ചെന്നു. അപ്പോൾ ഞാനെന്റെ നെഞ്ചിൽ കൈ വെച്ച് നോക്കിയപ്പോൾ യമനിലെ ളിഫാറിൽ നിന്ന് നിർമ്മിക്കപ്പെട്ട മണികൾ കോർത്ത എന്റെ മാല അറ്റു വീണുപോയിരിക്കുന്നു. അപ്പോൾ ഞാൻ മടങ്ങിപ്പോവുകയും എന്റെ മാല തിരയുകയും ചെയ്തു. അതിനോടുള്ള അഗ്രഹം എന്നെ തടഞ്ഞു വെച്ചു. ആ സമയം യാത്രയിലെ എന്റെ സഹായികൾ വരികയും ഞാൻ അകത്തുണ്ടെന്ന് കരുതി എന്റെ ഒട്ടകക്കട്ടിൽ ചുമന്ന് ഞാൻ വാഹനം കയറിയിരുന്ന എന്റെ ഒട്ടകത്തിന്മേൽ വെക്കുകയും ചെയ്തു. ആ കാലത്ത് സ്ത്രീകൾ വളരെ ഭാരം കുറഞ്ഞവരായിരുന്നു. അവർ ഭാരം കൂടുകയില്ല, ഇറച്ചി അവരെ മൂടുകയില്ല. കാരണം, വളരെ കുറച്ച് മാത്രമായിരുന്നു അന്ന് സ്ത്രീകൾ ഭക്ഷിക്കാറുണ്ടായിരുന്നത്. അതിനാൽ അവർ ആ ഒട്ടകക്കട്ടിൽ ചുമന്നപ്പോൾ അതിന്റെ ഭാരത്തെക്കുറിച്ച് സംശയം തോന്നിയില്ല. അതിനാലവരത് ഒട്ടകപ്പുറത്ത് കയറ്റിവെച്ചു. അന്ന് ഞാൻ ചെറുപ്രായക്കാരിയായ ഒരു പെൺകുട്ടിയായിരുന്നു. അങ്ങനെ ഒട്ടകത്തെ അവർ തെളിച്ചുകൊണ്ടുപോയി. സൈന്യം പോയിക്കഴിഞ്ഞതിന് ശേഷം എനിക്കെന്റെ മാല കിട്ടി. അപ്പോൾ അവരുണ്ടായിരുന്നിടത്തേക്ക് ഞാൻ വന്നു. അവിടെയാരുമുണ്ടായിരുന്നില്ല. ഇറങ്ങിയിരുന്ന അതേ സ്ഥലത്ത് പോയി ഇരിക്കാൻ ഞാൻ ഉദ്ദേശിച്ചു. എന്നെ കാണാതെ വരുമ്പോൾ അവർ എന്നെ അന്വേഷിച്ച് തിരിച്ചുവരുമെന്ന് ഞാനുറപ്പിച്ചു. അങ്ങനെ ഞാനിരിക്കുന്നതിനിടക്ക് എനിക്കുറക്കം വന്ന് കിടന്നുറങ്ങിപ്പോയി. സ്വഫ്വാനുബ്നുൽ മുഅത്ത്വലുസ്സുലമീ(റ) പട്ടാളത്തിന്റെയെല്ലാം പിന്നിൽ യാത്രചെയ്തുകൊണ്ടിരിക്കുകയായിരുന്നു. അദ്ദേഹം പ്രഭാതവേളയിൽ എന്റെ താവളത്തിനടുത്തുകൂടെ വന്നപ്പോൾ ഉറങ്ങുന്ന ഒരു മനുഷ്യരൂപം കണ്ടു. ഉടനെ അദ്ദേഹം എന്റെയടുക്കൽ വന്നു. മറ നിർബന്ധമാക്കപ്പെടുന്നതിന് മുമ്പ് അദ്ദേഹം എന്നെ കാണാറുണ്ടായിരുന്നു. അദ്ദേഹം ''ഇന്നാലില്ലാഹി'' ചൊല്ലുന്നത് കേട്ട് ഞാനുണർന്നു. ഉടനെ അദ്ദേഹം തന്റെ ഒട്ടകത്തെ മുട്ടുകുത്തിക്കുകയും അതിന്റെ കൈയിൻമേൽ ചവിട്ടുകയും ചെയ്തു. അങ്ങനെ ഞാനതിന്മേൽ കയറി. അങ്ങനെ എന്നേയും കൂട്ടി അദ്ദേഹം വാഹനത്തെ തെളിച്ചു. പട്ടാളം മദ്ധ്യാഹ്നവിശ്രമത്തിന് വേണ്ടി ഒരിടത്ത് ഇറങ്ങിയ ശേഷം ഞങ്ങൾ അവരോടൊപ്പം എത്തിച്ചേർന്നു. അപ്പോഴേക്ക് (ഊഹാപോഹങ്ങളും ആരോപണങ്ങളും കെട്ടിച്ചമച്ച് പ്രചരിപ്പിച്ച്) നശിക്കേണ്ടവരെല്ലാം നശിച്ചുകഴിഞ്ഞിരുന്നു. ആരോപണത്തിന്റെ നായകത്വം ഏറ്റെടുത്തിരുന്നത് അബ്ദുല്ലാഹിബ്നു ഉബയ്യിബ്നു സലൂലായിരുന്നു. അങ്ങനെ ഞങ്ങൾ മദീനയിലേക്ക് വരികയും അവിടെ ഞാൻ ഒരു മാസത്തോളം രോഗിയായി കിടക്കുകയും ചെയ്തു. ജനങ്ങളാകട്ടെ, ആരോപണം കെട്ടിച്ചമച്ചുണ്ടാക്കിയവരുടെ വാക്കുകൾ നാടെങ്ങും പ്രചരിപ്പിക്കുന്നതിൽ വ്യാപൃതരായി. എനിക്ക് രോഗം പിടിപെടുമ്പോൾ തിരുമേനി(സ)യിൽ ഞാൻ കാണാറുണ്ടായിരുന്ന അനുകമ്പ ഈ രോഗാവസ്ഥയിൽ അവിടുന്ന് എന്നോട് കാണിക്കാത്തതിൽ എനിക്ക് സംശയവും ഉണ്ടായിരുന്നു. തിരുമേനി(സ) എന്റെയടുക്കൽ പ്രവേശിച്ച്: "നിനക്കെങ്ങനെയുണ്ട്?" എന്ന് മാത്രം ചോദിക്കും. വാസ്തവത്തിൽ സുഖം പ്രാപിക്കുന്നത് വരെ ഇക്കഥകളൊന്നും എനിക്കറിയുമായിരുന്നില്ല. കുറച്ചൊക്കെ സുഖം പ്രാപിച്ചപ്പോൾ ഒരു ദിവസം ഞാനും മിസ്ത്വഹിന്റെ ഉമ്മയും കൂടി മനാസ്വിഇന്റെ ഭാഗത്തേക്ക് പുറപ്പെട്ടു. ഞങ്ങളുടെ വിസർജ്ജനസ്ഥലമായിരുന്നു അത്. രാത്രിസമയത്ത് മാത്രമേ ഞങ്ങൾ അവിടെ പോകാറുണ്ടായിരുന്നുള്ളൂ. ഞങ്ങളുടെ വീടുകളുടെ അടുത്ത് കക്കൂസുകൾ നിർമ്മിക്കുന്നതിന് മുമ്പുള്ള സമ്പ്രദായമാണിത്. പുരാതന അറബികളുടേത് പോലെ മൈതാനത്തോ വീട്ടിൽ നിന്നും വളരെ അകന്ന സ്ഥലത്തോ പോകലായിരുന്നു ഞങ്ങളുടെയും പതിവ്. അങ്ങനെ ഞാനും അബൂറുഹ്മിന്റെ മകളായ ഉമ്മുമിസ്ത്വഹും നടന്ന് പോകുമ്പോൾ അവർ വസ്ത്രത്തിൽ തടഞ്ഞ് വീണു. അപ്പോൾ അവർ പറഞ്ഞു: മിസ്ത്വഹ് നശിച്ചിരിക്കുന്നു. അപ്പോൾ ഞാനവരോട് പറഞ്ഞു: നിങ്ങളിപ്പറഞ്ഞത് വളരെ മോശമായി. ബദ്ർ യുദ്ധത്തിൽ പങ്കെടുത്ത ഒരാളെയാണോ നിങ്ങളാക്ഷേപിക്കുന്നത്? അപ്പോൾ അവർ പറഞ്ഞു: മകളേ, അവർ പറഞ്ഞ് പരത്തുന്നത് നീ കേട്ടില്ലേ? അന്നേരം, ആരോപണമുന്നയിച്ചവരുടെ സംസാരങ്ങളെല്ലാം അവരെനിക്ക് പറഞ്ഞുതന്നു. അതോടുകൂടി എന്റെ രോഗം വർദ്ധിച്ചു. ഞാൻ വീട്ടിലേക്ക് മടങ്ങിച്ചെന്നപ്പോൾ തിരുമേനി(സ) എന്റെ അടുക്കൽ പ്രവേശിച്ച് സലാം ചൊല്ലിയിട്ട്: "നിനക്കെങ്ങനെയുണ്ട്?" എന്നന്വേഷിച്ചു. ഞാൻ പറഞ്ഞു: എനിക്കെന്റെ മാതാപിതാക്കളുടെ അടുത്ത് പോകാൻ സമ്മതം തന്നാലും! എന്റെ മാതാപിതാക്കളുടെ അടുത്ത് നിന്നും ഈ വാർത്തയുടെ യാഥാർത്ഥ്യം അറിയണമെന്നായിരുന്നു എന്റെ ഉദ്ദേശ്യം. അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) എനിക്ക് സമ്മതം നൽകുകയും ഞാനെന്റെ മാതാപിതാക്കളുടെ അടുക്കൽ ചെല്ലുകയും ചെയ്തു. ഞാനെന്റെ ഉമ്മയോട് ചോദിച്ചു: ജനങ്ങൾ പറഞ്ഞുനടക്കുന്നതെന്താണ്? അപ്പോൾ ഉമ്മ പറഞ്ഞു: എന്റെ കുഞ്ഞുമകളേ, സാരമില്ല. നീ മനസ്സമാധാനത്തോടെയിരിക്കൂ. അല്ലാഹുവാണ് സത്യം! തന്നെ സ്നേഹിക്കുന്ന തന്റെ ഭർത്താവിന്റെ കൂടെ താമസിക്കുന്ന സുന്ദരിയായ ഒരു സ്ത്രീയെപ്പറ്റി തന്റെ ഭാര്യമാർ കൂടതൽ പറഞ്ഞു പരത്താതിരിക്കുകയെന്നത് അത്യപൂർവ്വമാണ്. അപ്പോൾ ഞാൻ പറഞ്ഞു: സുബ്ഹാനല്ലാഹ്! ജനങ്ങൾ ഇതെല്ലാം പറഞ്ഞ് നടക്കുന്നുണ്ടോ? ആഇശ(റ) പറയുന്നു: അങ്ങനെ ആ രാത്രി പുലരും വരേക്കും തോരാത്ത കണ്ണുനീരും ഉറക്കം വരാത്ത കൺപോളകളുമായി ഞാൻ കഴിച്ചുകൂട്ടി. പിന്നീട് നേരം പുലരുകയും വഹ്‌യ് ഇറങ്ങാതിരിക്കുകയും ചെയ്തപ്പോൾ തന്റെ ഭാര്യയുമായുള്ള ബന്ധം വേർപ്പെടുത്തുന്ന കാര്യത്തിൽ കൂടിയാലോചിക്കാൻ വേണ്ടി അല്ലാഹുവിന്റെ റസൂൽ(സ) അലിയ്യുബ്നു അബീത്വാലിബ്(റ)വിനേയും ഉസാമതുബ്നു സൈദ്(റ)വിനേയും വിളിച്ചുവരുത്തി. അപ്പോൾ ഉസാമ(റ) തനിക്ക് തിരുമേനി(സ)യുടെ പത്നിമാരോടുണ്ടായിരുന്ന സ്നേഹം മുൻ നിർത്തിക്കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ ഭാര്യമാരാണവർ. അവരെക്കുറിച്ച് നല്ലതല്ലാതെ യാതൊന്നും ഞങ്ങളുടെ അറിവിലില്ല. എന്നാൽ അലി(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അല്ലാഹു അങ്ങേക്ക് ഒന്നും തന്നെ കുടുസ്സാക്കിയിട്ടില്ല. മഹതിയെക്കൂടാതെ തന്നെ എത്രയോ സ്ത്രീകളുണ്ട് താനും. അതുകൊണ്ട് അങ്ങ് പരിചാരികയെ വിളിച്ച് ചോദിച്ചാലും, അവൾ അങ്ങയോട് സത്യം പറയുമായിരിക്കും. അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) ബരീറ(റ)യെ വിളിച്ച് ചോദിച്ചു: "ബരീറാ, സംശയം ജനിപ്പിക്കുന്ന വല്ലതും നീ അവളിൽ കണ്ടിട്ടുണ്ടോ?" ബരീറ(റ) പറഞ്ഞു: ഇല്ല, അങ്ങയെ സത്യസന്ദേശവുമായി നിയോഗിച്ചവനെത്തന്നെയാണ് സത്യം! ചെറുപ്രായക്കാരിയായ ഒരു പെൺകുട്ടിയെന്ന നിലക്ക് ചിലപ്പോൾ മാവ് കുഴച്ച്‌വെച്ച് ഉറക്കം തൂങ്ങുകയും വളർത്തുമൃഗങ്ങൾ വന്ന് അത് തിന്നുകയും ചെയ്യാറുണ്ട് എന്നതൊഴിച്ച് അവരെക്കുറിച്ച് എനിക്ക് കുറ്റം പറയാൻ പറ്റുന്ന ഒന്നും തന്നെ ഞാനവരിൽ കണ്ടിട്ടില്ല. അപ്പോൾ തിരുനബി(സ) ആ പകൽ സമയത്ത് തന്നെ എഴുന്നേറ്റ് നിന്ന് അബ്ദുല്ലാഹിബ്നു ഉബയ്യിബ്നി സലൂലിനെതിരിൽ നടപടിയെടുക്കാൻ ജനങ്ങളോട് സഹകരണത്തിനാവശ്യപ്പെട്ടു. അവിടുന്ന് ചോദിച്ചു: "എന്റെ ഭാര്യയുടെ മേൽ അപരാധം ചുമത്തി എന്നെ ദ്രോഹിച്ചവനെതിരിൽ നടപടിയെടുക്കാൻ എന്നെ സഹായിക്കുന്നവരാരുണ്ട്? അല്ലാഹുവാണ് സത്യം! എന്റെ ഭാര്യയെക്കുറിച്ച് നന്മയല്ലാതെ മറ്റൊന്നും ഞാനറിഞ്ഞിട്ടില്ല. ഒരു പുരുഷനെക്കുറിച്ചാണവർ പറയുന്നത്. അദ്ദേഹത്തിലും ഞാൻ നന്മയല്ലാതെ മറ്റൊന്നും അറിഞ്ഞിട്ടില്ല. അദ്ദേഹം എന്റെ കൂടെയല്ലാതെ എന്റെ കുടുംബത്തിൽ പ്രവേശിക്കാറുണ്ടായിരുന്നില്ല." അപ്പോൾ സഅ്ദ്(റ) എഴുന്നേറ്റു നിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവാണ് സത്യം! അയാൾക്കെതിരിൽ നടപടിയെടുക്കുന്നതിൽ ഞാനങ്ങയെ സഹായിക്കുക തന്നെ ചെയ്യും. അയാൾ ഔസ് ഗോത്രത്തിൽ പെട്ടവനാണെങ്കിൽ നിശ്ചയം ഞങ്ങളവന്റെ കഴുത്തറുക്കും. ഇനി അയാൾ ഖസ്‌റജ് ഗോത്രത്തിലെ ഞങ്ങളുടെ സഹോദരന്മാരിൽ പെട്ടവനാണെങ്കിൽ അങ്ങ് ഞങ്ങളോട് കൽപിക്കണം. എന്നാൽ അങ്ങയുടെ കൽപന അയാളിൽ ഞങ്ങൾ നടപ്പാക്കും. ഇത് കേട്ടപ്പോൾ ഖസ്‌റജ് ഗോത്രത്തിന്റെ നേതാവായ സഅ്ദുബ്നു ഉബാദ(റ) - ഇതിനു മുമ്പ് അദ്ദേഹമൊരു നല്ല മനുഷ്യനായിരുന്നു. പക്ഷേ, അഭിമാനരോഷം അദ്ദേഹത്തിൽ തലപൊക്കി - എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: കളവാണ് നീ പറഞ്ഞത്. അല്ലാഹുവാണ, നീ അവനെ കൊല്ലുകയോ നിനക്കവനെ കൊല്ലാൻ സാധിക്കുകയോ ഇല്ല. അപ്പോൾ ഉസൈദുബ്നു ഹുളൈർ(റ) പറഞ്ഞു: നീ പറഞ്ഞത് അസത്യമാണ്. അല്ലാഹുവാണ, ഞങ്ങളവനെ കൊല്ലുകതന്നെ ചെയ്യും. നിശ്ചയം കപടവിശ്വാസികൾക്ക് വേണ്ടി വാദിക്കുന്ന മറ്റൊരു കപടവിശ്വാസിയാണ് നീ. ഇതോടെ ഔസ്, ഖസ്‌റജ് എന്നീ രണ്ട് ഗോത്രങ്ങൾ അത്യന്തം ക്ഷുഭിതരായി ഇളകുകയും ഒരു പോരാട്ടത്തിനു തന്നെ അവർ മുതിരുകയും ചെയ്തു. അല്ലാഹുവിന്റെ റസൂൽ(സ) മിമ്പറിൽ തന്നെ ഇരിക്കവെയാണിത്. ഉടനെ തിരുമേനി(സ) അവിടെ നിന്നിറങ്ങുകയും അവരെ നിശ്ശബ്ദരാക്കുകയും ചെയ്തു. അങ്ങനെ അവരെല്ലാവരും അടങ്ങി. തിരുമേനി(സ)യും മൗനം പാലിച്ചു. അന്ന് മുഴുവനും ഞാൻ കരഞ്ഞുകൊണ്ടേയിരുന്നു. എന്റെ കണ്ണുനീർ വറ്റുകയോ എനിക്ക് ഉറക്കം വരികയോ ചെയ്തില്ല. പ്രഭാതത്തിൽ എന്റെ മാതാപിതാക്കൾ എന്റെയടുക്കൽ വന്നു. അപ്പോഴേക്കും രണ്ട് രാവും ഞാൻ കരഞ്ഞുകഴിഞ്ഞിരുന്നു. അവസാനം കരച്ചിൽ കാരണം എന്റെ കരൾ പൊട്ടിപ്പോകുമോ എന്നെനിക്ക് ഭയമായി. അങ്ങനെ എന്റെ മാതാപിതാക്കൾ എന്റെ അരികിലിരിക്കുകയും ഞാൻ കരഞ്ഞ് കൊണ്ടിരിക്കുകയും ചെയ്യുന്നതിനിടക്ക് ഒരു അൻസാരി സ്ത്രീ എന്റെയടുക്കലേക്ക് വരാൻ സമ്മതം ആവശ്യപ്പെട്ടു. ഞാനവൾക്ക് സമ്മതം നൽകി. അപ്പോൾ അവളും എന്റെ കൂടെ ഇരുന്ന് കരയാൻ തുടങ്ങി. ഞങ്ങളങ്ങനെയിരിക്കെ അല്ലാഹുവിന്റെ റസൂൽ(സ) കടന്ന് വന്ന് എന്റെ അടുത്തിരുന്നു. എന്നെക്കുറിച്ച് അപരാധം പറയപ്പെട്ട ദിവസം മുതൽ ഈ ദിവസം വരെയും തിരുമേനി(സ) എന്റെയടുക്കൽ വന്നിരുന്നിട്ടില്ല. എന്റെ കാര്യത്തിൽ തിരുമേനി(സ)ക്ക് യാതൊരു ദൈവിക സന്ദേശവും ലഭിക്കാതെ ഒരു മാസക്കാലം അവിടന്ന് കഴിച്ച്കൂട്ടി. മഹതി പറയുന്നു: തിരുമേനി(സ) ശഹാദത്ത് ചൊല്ലിയിട്ട് ചോദിച്ചു: "ആഇശാ, നിന്നെക്കുറിച്ച് എനിക്ക് ഇന്നാലിന്ന വാർത്തകൾ ലഭിച്ചിട്ടുണ്ട്. നീ യഥാർത്ഥത്തിൽ നിരപരാധിയാണെങ്കിൽ നീ നിരപരാധിയാണെന്നത് അല്ലാഹു തെളിയിക്കും. ഇനി വല്ല തെറ്റും വന്നിട്ടുണ്ടെങ്കിൽ നീ അല്ലാഹുവിനോട് പൊറുക്കലിനെ തേടി അവനിലേക്ക് പശ്ചാത്തപിച്ച് മടങ്ങുക. കാരണം, താൻ ചെയ്ത തെറ്റ് ഏറ്റു പറഞ്ഞ് അടിമ പശ്ചാത്തപിച്ച് മടങ്ങിയാൽ അവന്റെ പശ്ചാത്താപം അല്ലാഹു സ്വീകരിക്കും." തിരുമേനി(സ)യുടെ സംസാരം തീർന്നതോടെ എന്റെ കണ്ണുനീർ പാടേ വറ്റി. പിന്നീട് ഒരു തുള്ളിയും ഒലിച്ചില്ല. എന്റെ പിതാവിനോട് ഞാൻ പറഞ്ഞു: എന്റെ പക്ഷത്തുനിന്ന് തിരുമേനി(സ)യോട് സംസാരിക്കണം. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണ, എന്താണ് തിരുമേനി(സ)യോട് പറയേണ്ടതെന്ന് എനിക്കറിയില്ല. അപ്പോൾ ഞാൻ മാതാവിനോട് പറഞ്ഞു: എനിക്കുവേണ്ടി റസൂൽ(സ)യോട് നിങ്ങൾ സംസാരിക്കണം. മാതാവ് പറഞ്ഞു: അല്ലാഹുവാണ, റസൽ(സ)യോട് എന്തു പറയണമെന്ന് എനിക്കൊരു നിശ്ചയവുമില്ല. മഹതി പറയുന്നു: ഞാൻ ചെറുപ്രായമായിരുന്നു. ഖുർആനിൽ ഭൂരിഭാഗവും എനിക്ക് വശമില്ലായിരുന്നു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണ, ജനങ്ങളുടെ സംസാരങ്ങളിൽ നിങ്ങൾ കേട്ടതും നിങ്ങളുടെ ഹൃദയങ്ങളിൽ ഉറച്ചതും നിങ്ങൾ ഗ്രഹിച്ചുവെച്ചതുമായ കാര്യങ്ങൾ ഞാനറിഞ്ഞു. ഞാൻ നിരപരാധിയാണെന്ന് നിങ്ങളോട് പറഞ്ഞാൽ - ഞാൻ നിരപരാധിയാണെന്ന് അല്ലാഹുവിന്നറിയാം - നിങ്ങളത് വിശ്വസിക്കുകയില്ല. ഇനി, വല്ല തെറ്റും നിങ്ങളോട് ഞാൻ ഏറ്റുപറഞ്ഞുവെന്ന് വെക്കുക - ഞാൻ നിരപരാധിയാണെന്നത് അല്ലാഹുവിന്നറിയാം - നിങ്ങളത് വിശ്വസിക്കുകയും ചെയ്യും. യൂസുഫ് നബി(അ)മിന്റെ പിതാവിനെ മാത്രമാണ് ഞാൻ എനിക്കും നിങ്ങൾക്കുമുള്ള ഉദാഹരണമായി കാണുന്നത്. അദ്ദേഹം പറഞ്ഞു: ഞാൻ അങ്ങേയറ്റം ക്ഷമിക്കുന്നു. നിങ്ങൾ പറയുന്ന കാര്യങ്ങളിൽ സഹായമഭ്യർത്ഥിക്കപ്പെടുന്നവനായി അല്ലാഹു മാത്രമാണുള്ളത്. ഇപ്രകാരം പറഞ്ഞ് ഞാനെന്റെ വിരിപ്പിൽ മുഖം തിരിഞ്ഞുകിടന്നു. അല്ലാഹു എന്റെ നിരപരാധിത്വം തെളിയിക്കുമെന്ന പ്രതീക്ഷയിലായിരുന്നു ഞാൻ. പക്ഷേ, അല്ലാഹുവാണ, ഖുർആനിൽ ഓതപ്പെട്ടുകൊണ്ടിരിക്കാൻ ഇടവരത്തക്ക വിധം എന്റെ കാര്യത്തിൽ അല്ലാഹു വഹ്‌യ് ഇറക്കുമെന്ന് ഞാൻ ധരിച്ചിരുന്നതേയില്ല. കാരണം, ഖുർആനിൽ എന്റെ കാര്യം പറയാതിരിക്കാൻ മാത്രം എന്റെ മനസ്സിൽ ഞാൻ നിസ്സാരമായിരുന്നു. എങ്കിലും എന്റെ നിരപരാധിത്വം വെളിപ്പെടുത്തിക്കൊണ്ട് തിരുമേനി(സ)ക്ക് അല്ലാഹു സ്വപ്നം കാണിച്ചുകൊടുക്കുമെന്ന് ഞാൻ പ്രതീക്ഷിച്ചിരുന്നു. വാസ്തവത്തിൽ അല്ലാഹുവാണ, തിരുമേനി(സ) ആ ഇരുത്തത്തിൽ നിന്ന് അനങ്ങുകയോ വീട്ടുകാരിൽ വല്ലവരും പുറത്തുപോകുകയോ ചെയ്തില്ല. അപ്പോഴേക്ക് തിരുമേനി(സ)ക്ക് ദൈവിക സന്ദേശം ലഭിക്കുകയും ആ സമയത്ത് ബാധിക്കാറുള്ള ശക്തമായ ക്ഷീണം ബാധിക്കുകയും ചെയ്തു. അങ്ങനെ തിരുമേനി(സ)യിൽ നിന്ന് ശൈത്യനാളുകളിലെന്നോണം മുത്തുമണികൾ പോലെയുള്ള വിയർപ്പ് തുള്ളികൾ ഇറ്റിവീഴാൻ തുടങ്ങി. തിരുമേനി(സ)യിൽ നിന്നും ആ അവസ്ഥ നീങ്ങിക്കഴിഞ്ഞപ്പോൾ അവടന്ന് അതാ ചിരിക്കുന്നു. ശേഷം അവിടുന്ന് ആദ്യമായി ഇരുവിട്ട വാക്ക് എന്നോട് ഇങ്ങനെ പറഞ്ഞതായിരുന്നു. "ആഇശാ, നീ അല്ലാഹുവിനെ സ്തുതിക്കുക. നിന്റെ നിരപരാധിത്വം ഇതാ അല്ലാഹു പ്രഖ്യാപിച്ചിരിക്കുന്നു." ഇതു കേട്ടപ്പോൾ എന്റെ മാതാവ് എന്നോട് പറഞ്ഞു: നീ തിരുമേനി(സ)യുടെയടുത്തേക്ക് എഴുന്നേറ്റുചെല്ലൂ. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ, തിരുമേനി(സ)യുടെ അടുത്തേക്ക് ഞാൻ പോകില്ല. ഞാൻ അല്ലാഹുവിനെയല്ലാതെ സ്തുതിക്കുകയുമില്ല. അപ്പോൾ അല്ലാഹു ''കള്ളവാർത്ത കെട്ടിച്ചമച്ചുകൊണ്ട് വന്നവർ നിങ്ങളിൽ തന്നെയുള്ള ഒരു കൂട്ടം ആളുകളാണ്'' എന്ന സൂക്തമിറക്കി. എന്റെ നിരപരാധിത്വം തെളിയിച്ചുകൊണ്ട് അല്ലാഹു ഈ സൂക്തം അവതരിപ്പിച്ചപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവാണ, മിസ്തഹിന്ന്, അദ്ദേഹം ആഇശ(റ)യെക്കുറിച്ച് പറഞ്ഞതിനു ശേഷം ഞാനിനി ഒരു ധനസഹായവും നൽകുകയില്ല - മിസ്തഹുമായുള്ള കുടുംബബന്ധം പരിഗണിച്ച് അബൂബകർ(റ) അദ്ദേഹത്തിന് ധനസഹായം നൽകാറുണ്ടായിരുന്നു - ആ അവസരത്തിൽ അല്ലാഹു, ''നിങ്ങളിൽ ഉൽകൃഷ്ട പദവിയും ധനപരമായ കഴിവുമുള്ളവർ, അടുത്ത കുടുംബങ്ങൾക്കും അഗതികൾക്കും ദൈവമാർഗ്ഗത്തിൽ സ്വദേശം വെടിഞ്ഞവർക്കും ധനസഹായം ചെയ്യുകയില്ലെന്ന് സത്യം ചെയ്തുപോകരുത്'' എന്നതു മുതൽ ''അല്ലാഹു അങ്ങേയറ്റം പൊറുക്കുന്നവനും വളരെയേറെ ദയകാണിക്കുന്നവനുമാകുന്നു'' എന്നത് വരെയുള്ള സൂക്തമിറക്കി. ഇതുകേട്ടപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: അതെ, അല്ലാഹുവാണ, എന്റെ തെറ്റുകൾ അല്ലാഹു എനിക്ക് പൊറുത്തുതരണമെന്ന് തന്നെയാണ് എന്റെ ആഗ്രഹം. എന്നിട്ട് അദ്ദേഹം മിസ്തഹിന് മുമ്പ് കൊടുത്തുവന്നിരുന്ന ധനസഹായം പുനരാരംഭിച്ചു. എന്റെ വിഷയത്തെക്കുറിച്ച് തിരുമേനി(സ) സൈനബ് ബിൻത് ജഹ്ശ്(റ)യോട് ചോദിച്ചിരുന്നു. അവിടുന്ന് ചോദിച്ചു: "സൈനബ്, നീ എന്തെല്ലാം അറിഞ്ഞിട്ടുണ്ട്? നിന്റെ അഭിപ്രായമെന്താണ്?" അപ്പോൾ മഹതി പറഞ്ഞു: ദൈവദൂതരേ, ഞാനെന്റെ കാഴ്ചയും കേൾവിയും സൂക്ഷിക്കുന്നു. അല്ലാഹുവാണ, അവളെക്കുറിച്ച് നന്മയല്ലാതെ മറ്റൊന്നും എനിക്കറിയില്ല. ആഇശ(റ) പറയുന്നു: വാസ്തവത്തിൽ അവളായിരുന്നു ഞാനുമായി കിടമൽസരം നടത്താറുണ്ടായിരുന്നത്. പക്ഷേ, സൂക്ഷമതാ ബോധം മൂലം അല്ലാഹു അവളെ കാത്തുരക്ഷിച്ചു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 441, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عُقْبَةَ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: تَزَوَّجْتُ أُمَّ يَحْيَى بِنْتَ أَبِي إِهَابٍ فَدَخَلَتْ عَلَيْنَا امْرَأَةٌ سَوْدَاءُ، فَزَعَمَتْ أَنَّهَا أَرْضَعَتْنَا جَمِيعًا، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَأَعْرَضَ عَنِّي، فَقُلْتُ: يَا رَسُولَ اللهِ إِنَّهَا لَكَاذِبَةٌ، قَالَ: "وَمَا يُدْرِيكَ، وَقَدْ قَالَتْ مَا قَالَتْ؟ دَعْهَا عَنْكَ". (خ,د,ت,ن)', 'ഉഖ്ബതുബ്നുൽ ഹാരിസ്(റ): ഉമ്മുയഹ്യാ ബിൻത് അബീഇഹാബ്(റ)യെ ഞാൻ വിവാഹം കഴിച്ചു. അപ്പോൾ ഒരു കറുത്ത പെണ്ണ് ഞങ്ങളുടെ അടുക്കൽ വരികയും ഞങ്ങൾക്ക് രണ്ട് പേർക്കുമവൾ മുലയൂട്ടിയിട്ടുണ്ടെന്ന് വാദിക്കുകയും ചെയ്തു. ഉടനെ ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്ന് അവിടുത്തോട് അതേക്കുറിച്ച് പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് എന്നിൽ നിന്ന് പിന്തിരിഞ്ഞുകളഞ്ഞു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം അവൾ കളവ് പറയുന്നവളാണ്. അവിടുന്ന് പറഞ്ഞു: "നിനക്കെന്തെറിയാം? തീർച്ചയായും അവൾ പറഞ്ഞത് അവൾ പറഞ്ഞിരിക്കുന്നു. നീയവളെ ഒഴിവാക്കുക." (ബു,ദ,തു,ന)', 'عُقْبَةَ بْنِ الْحَارِثِ', 'ഉഖ്ബതുബ്നുൽ ഹാരിസ്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أُصِيبَ رَجُلٌ فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثِمَارٍ ابْتَاعَهَا، فَكَثُرَ دَيْنُهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَصَدَّقُوا عَلَيْهِ". فَتَصَدَّقَ النَّاسُ عَلَيْهِ، فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خُذُوا مَا وَجَدْتُمْ، وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ" يَعْنِي الْغُرَمَاءَ. (م,د,ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഒരാൾക്ക് താൻ വാങ്ങിയ പഴങ്ങളിൽ നഷ്ടം വരികയും അദ്ദേഹത്തിന്റെ കടം വർധിക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അയാൾക്ക് ദാനം കൊടുക്കുക." അപ്പോൾ ജനങ്ങളെല്ലാം അയാൾക്ക് ദാനം നൽകി. പക്ഷേ, അതൊന്നും തന്നെ അദ്ദേഹത്തിന്റെ കടം വീട്ടാൻ മതിയാകുമായിരുന്നില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് കിട്ടിയത് നിങ്ങൾ എടുക്കുക. ഇതല്ലാതെ മറ്റൊന്നും നിങ്ങൾക്കില്ല." അവിടുന്ന് കടക്കാരെയാണ് ഉദ്ദേശിച്ചത്. (മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَلَعَ مُعَاذَ بْنَ جَبَلٍ مِنْ غُرَمَائِهِ، ثُمَّ اسْتَعْمَلَهُ عَلَى الْيَمَنِ، فَقَالَ مُعَاذٌ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَخْلَصَنِي بِمَالِي ثُمَّ اسْتَعْمَلَنِي. [ز: في إسناده ضعيف] (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) മുആദുബ്നു ജബൽ(റ)വിനെ അദ്ദേഹത്തിന്റെ കടക്കാരിൽ നിന്നും ഒഴിവാക്കിക്കൊടുക്കുകയും പിന്നീടദ്ദേഹത്തെ യമനിലെ ഗവർണ്ണറായി നിയമിക്കുകയും ചെയ്തു. അപ്പോൾ മുആദ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ) എന്റെ സമ്പത്ത് കൊണ്ട് എന്നെ തെരഞ്ഞെടുക്കുകയും പിന്നീടെന്നെ ഗവർണ്ണറാക്കുകയും ചെയ്തു. പരമ്പരയിൽ ബലഹീനതയുണ്ട്. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ وَجَدَ مَتَاعَهُ بِعَيْنِهِ عِنْدَ رَجُلٍ قَدْ أَفْلَسَ فَهُوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പാപ്പരായ ഒരാളുടെ കയ്യിൽ തന്റെ വല്ല വസ്തുവും യാതൊരു മാറ്റവും കൂടാതെ ആരെങ്കിലും എത്തിച്ചാൽ അവനാണതിന് മറ്റാരെക്കാളും അർഹൻ." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 447, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا رَجُلٍ بَاعَ سِلْعَةً، فَأَدْرَكَ سِلْعَتَهُ بِعَيْنِهَا عِنْدَ رَجُلٍ، وَقَدْ أَفْلَسَ، وَلَمْ يَكُنْ قَبَضَ مِنْ ثَمَنِهَا شَيْئًا، فَهِيَ لَهُ. وَإِنْ كَانَ قَبَضَ مِنْ ثَمَنِهَا شَيْئًا فَهُوَ أُسْوَةٌ لِلْغُرَمَاءِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഒരു സാധനം വിൽക്കുകയും അങ്ങനെ ആ സാധനം യാതൊരു വ്യത്യാവസവും കൂടാതെ പാപ്പരായ ഒരാളുടെ അടുക്കൽ എത്തിക്കുകയും ചെയ്താൽ. അതിന്റെ വിലയിൽ നിന്ന് യാതൊന്നും തന്നെ ഇയാൾ കൈപ്പറ്റിയിട്ടുമില്ല. എന്നാൽ ആ സാധനം ഇയാൾക്കുള്ളതാണ്. ഇനി അതിന്റെ വിലയിൽ നിന്ന് കുറച്ചെന്തെങ്കിലും ഇയാൾ കൈപ്പറ്റിയിട്ടുണ്ടായിരുന്നുവെങ്കിൽ ഇയാൾ മറ്റു കടക്കാരെപ്പോലെത്തന്നെയാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَن ابْنِ خَلْدَةَ الزُّرَقِيِّ – وَكَانَ قَاضِيًا بِالْمَدِينَةِ – قَالَ: جِئْنَا أَبَا هُرَيْرَةَ – رَضِيَ اللهُ عَنْهُ – فِي صَاحِبٍ لَنَا قَدْ أَفْلَسَ، فَقَالَ: هَذَا الَّذِي قَضَى فِيهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا رَجُلٍ مَاتَ أَوْ أَفْلَسَ فَصَاحِبُ الْمَتَاعِ أَحَقُّ بِمَتَاعِهِ إِذَا وَجَدَهُ بِعَيْنِهِ". (د,جه)', 'ഇബ്നുഖൽദതുസ്സർഖീ(റ): അദ്ദേഹം മദീനയിലെ ഖാളിയായിരുന്നു - പാപ്പരായ ഞങ്ങളിലൊരാളുടെ വിഷയത്തിൽ ഞങ്ങൾ അബൂഹുറൈറ(റ)വിനെ സമീപിച്ചു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: നബി(സ) വിധി പറഞ്ഞ പ്രശ്നമാണിത്: "ഒരാൾ മരിക്കുകയോ പാപ്പരാകുകയോ ചെയ്ത ശേഷം ചരക്കിന്റെ ഉടമ യാതൊരു വ്യത്യാസവും കൂടാതെ തന്റെ ചരക്ക് കണ്ടെത്തിയാൽ അവൻ തന്നെയാണ് ആ ചരക്കിന് ഏറ്റവും അർഹൻ." (ദ,ജ)', 'ابْنِ خَلْدَةَ الزُّرَقِيِّ – وَكَانَ قَاضِيًا بِالْمَدِينَةِ – قَالَ', 'ഇബ്നുഖൽദതുസ്സർഖീ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا امْرِئٍ مَاتَ وَعِنْدَهُ مَالُ امْرِئٍ بِعَيْنِهِ، اقْتَضَى مِنْهُ شَيْئًا أَوْ لَمْ يَقْتَضِ، فَهُوَ أُسْوَةٌ لِلْغُرَمَاءِ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ മരിക്കുകയും അയാളുടെ പക്കൽ മറ്റൊരാളുടെ സാധനം യാതൊരു മാറ്റവും കൂടാതെ ഉണ്ടാവുകയും ചെയ്താൽ, കടത്തിൽ നിന്നുള്ള കുറച്ചെന്തെങ്കിലും വാങ്ങിയിട്ടുണ്ടെങ്കിലും ഇല്ലെങ്കിലും, ഇയാൾ മറ്റു കടക്കാരെപ്പോലെത്തന്നെയാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: تَلَا هَذِهِ الْآيَةَ: {يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى} حَتَّى بَلَغَ {فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضًا} فَقَالَ: هَذِهِ نَسَخَتْ مَا قَبْلَهَا. (جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): അദ്ദേഹം ഈ സൂക്തം ഓതി: ''സത്യവിശ്വാസികളേ, നിങ്ങൾ നിശ്ചിത കാലം വരെ പരസ്പരം കടമിടപാട് നടത്തുകയാണെങ്കിൽ'' അങ്ങനെ അദ്ദേഹം ഓതിയോതി ''നിങ്ങളിൽ ചിലർ ചിലരെ നിർഭയരാവുകയാണെങ്കിൽ'' എന്നതുവരെ എത്തി. അപ്പോഴദ്ദേഹം പറഞ്ഞു: ഇത് ഇതിന്റെ മുമ്പുള്ളതിനെ ദുർബലപ്പെടുത്തിയിരിക്കുന്നു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنِ ابْنِ عُمَرَ رَضِي اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَرَضَهُ يَوْمَ أُحُدٍ، وَهُوَ ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً، فَلَمْ يُجِزْنِي، ثُمَّ عَرَضَنِي يَوْمَ الْخَنْدَقِ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً، فَأَجَازَنِي. (خ)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം ഉഹ്ദ് യുദ്ധദിവസം, അദ്ദേഹത്തിന് പതിനാല് വയസ്സുള്ളപ്പോൾ, റസൂൽ(സ) അദ്ദേഹത്തെ പരിശോധിച്ചു. അപ്പോഴെനിക്കവിടുന്ന് യുദ്ധത്തിന് സമ്മതം തന്നില്ല. പിന്നീട് ഖന്ദഖ് യുദ്ധദിവസം, എനിക്ക് പതിനഞ്ച് വയസ്സുള്ളപ്പോൾ, അവിടുന്നെന്നെ പരിശോധിച്ചു. അപ്പോഴെനിക്കവിടുന്ന് സമ്മതം നൽകി. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ حَلَّفَهُ: "احْلِفْ بِاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ: مَا لَهُ عِنْدَكَ شَيْءٌ". يَعْنِي لِلْمُدَّعِي. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) സത്യം ചെയ്യിച്ച ഒരാളോട് അവിടുന്ന് പറഞ്ഞു: "നിന്റെയടുക്കൽ അവനുള്ള ഒന്നുമില്ലെന്ന്, ആരാധ്യനായി താനല്ലാതെ മറ്റാരുമില്ലാത്ത അല്ലാഹുവിനെക്കൊണ്ട് നീ സത്യം ചെയ്യുക." വാദിയെയാണ് അവിടുന്ന് ഉദ്ദേശിക്കുന്നത്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي هُرَيْرَةَ رَضِي اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَرَضَ عَلَى قَوْمٍ الْيَمِينَ، فَأَسْرَعُوا، فَأَمَرَ أَنْ يُسْهَمَ بَيْنَهُمْ فِي الْيَمِينِ، أَيُّهُمْ يَحْلِفُ. (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം നബി(സ) ഒരു സമുദായത്തോട് സത്യം ചെയ്യാൻ പറഞ്ഞു. അപ്പോൾ അവർ സത്യം ചെയ്യാൻ ധൃതി കാണിച്ചു. അപ്പോൾ അവരിൽ ആരാണ് സത്യം ചെയ്യേണ്ടതെന്ന് നോക്കാൻ അവർക്കിടയിൽ നറുക്കിടപ്പെടാൻ അവിടുന്ന് കൽപിച്ചു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَبِي هُرَيْرَةَ رَضِي اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْيَمِينُ عَلَى مَا يُصَدِّقُكَ بِهِ صَاحِبُكَ". حسن. (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ കൂടെയുള്ളവൻ എന്തുകൊണ്ട് നിന്നെ സത്യമാക്കുമോ അതിന്റെ മേലിലാണ് സത്യം ചെയ്യേണ്ടത്." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِي اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ بِيَمِينٍ آثِمَةٍ، عِنْدَ مِنْبَرِي هَذَا، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ، وَلَوْ عَلَى سِوَاكٍ أَخْضَرَ". (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഈ മിമ്പറിന്റെ അടുത്തുവെച്ച് ആരെങ്കിലും തെറ്റായ സത്യം ചെയ്താൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം ഉറപ്പിക്കട്ടെ. അവൻ സത്യം ചെയ്യുന്നത് ഒരു പച്ച അറാക്കിന് വേണ്ടിയാണെങ്കിൽ പോലും." (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 449, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحْلِفُ عِنْدَ هَذَا الْمِنْبَرِ عَبْدٌ وَلَا أَمَةٌ عَلَى يَمِينٍ آثِمَةٍ، وَلَوْ عَلَى سِوَاكٍ رَطْبٍ، إِلَّا وَجَبَتْ لَهُ النَّارُ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഈ മിമ്പറിന്റെ അടുത്തുവെച്ച് ഒരു അടിമയോ അടിമസ്ത്രീയോ, തനിക്ക് നരകം നിർബന്ധമായിട്ടല്ലാതെ, തെറ്റായ സത്യം ചെയ്യുകയില്ല. അവൻ സത്യം ചെയ്യുന്നത് ഒരു പച്ച സിവാക്കിന് വേണ്ടിയാണെങ്കിൽ പോലും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 450, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنِ ابْنِ عُمَرَ رَضِي اللهُ عَنْهما: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ حَالِفًا فَلْيَحْلِفْ بِاللهِ أَوْ لِيَصْمُتْ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും സത്യം ചെയ്യുകയാണെങ്കിൽ അവൻ അല്ലാഹുവെക്കൊണ്ട് സത്യം ചെയ്യട്ടെ. അല്ലെങ്കിൽ മൗനമവലംബിക്കട്ടെ." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 450, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِي اللهُ عَنْهُ قَالَ: قَالَ مُعَاوِيَةُ رَضِي اللهُ عَنْهُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَى حَلْقَةٍ – يَعْنِي مِنْ أَصْحَابِهِ – فَقَالَ: "مَا أَجْلَسَكُمْ". قَالُوا: جَلَسْنَا نَدْعُو اللهَ وَنَحْمَدُهُ عَلَى مَا هَدَانَا لِدِينِهِ وَمَنَّ عَلَيْنَا بِكَ. قَالَ: "آللهُ مَا أَجْلَسَكُمْ إِلَّا ذَلِكَ". قَالُوا: آللهُ مَا أَجْلَسَنَا إِلَّا ذَلِكَ. قَالَ: "أَمَا إِنِّي لَمْ أَسْتَحْلِفْكُمْ تُهَمَةً لَكُمْ، وَإِنَّمَا أَتَانِي جِبْرِيلُ عَلَيْهِ السَّلَام: فَأَخْبَرَنِي: أَنَّ اللهَ عَزَّ وَجَلَّ يُبَاهِي بِكُمُ الْمَلَائِكَةَ". (ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): മുആവിയ(റ) പറയുന്നു: റസൂൽ(സ), തന്റെ സ്വഹാബികളിൽ നിന്നുള്ള ചിലർ കൂടിയിരിക്കുന്നതിന്റെ അടുത്തുകൂടെ നടന്നുപോയി. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിങ്ങളെ ഇവിടെ ഇരുത്തിയതെന്താണ്." അവർ പറഞ്ഞു: അല്ലാഹു അവന്റെ ദീനിലേക്ക് ഞങ്ങളെ മാർഗ്ഗദർശനം ചെയ്തതിനും അങ്ങയെ ഞങ്ങൾക്ക് നൽകിയതിനും അവനെ സ്തുതിച്ചുകൊണ്ടും അവനോട് പ്രാർത്ഥിച്ചുകൊണ്ടുമാണ് ഞങ്ങളിവിടെ ഇരിക്കുന്നത്. അവിടുന്ന് പറഞ്ഞു: "അതല്ലാതെ മറ്റൊന്നുമല്ല നിങ്ങളെ ഇരുത്തിയതെന്ന് അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യുക." അവർ പറഞ്ഞു: അല്ലാഹുവാണ, അതല്ലാതെ മറ്റൊന്നും ഞങ്ങളെ ഇരുത്തിയിട്ടില്ല. അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളെ തെറ്റിദ്ധരിച്ചത് കൊണ്ടല്ല ഞാൻ നിങ്ങളോട് സത്യം ചെയ്യാനാവശ്യപ്പെട്ടത്. നിശ്ചയം ജിബ്‌രീൽ(അ) എന്റെയടുക്കൽ വന്ന് ഇപ്രകാരം അറിയിച്ചിരിക്കുന്നു: നിശ്ചയം അല്ലാഹു നിങ്ങളെക്കൊണ്ട് മലക്കുകളോട് പ്രൗഢി നടിക്കുന്നുണ്ട്." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['തു']::text[], null, null, 450, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي هُرَيْرَةَ رَضِي اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "رَأَى عِيسَى بْنُ مَرْيَمَ عَلَيْهِ السَّلَام رَجُلًا يَسْرِقُ، فَقَالَ لَهُ: أَسَرَقْتَ؟ قَالَ: لَا وَاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ. قَالَ عِيسَى عَلَيْهِ السَّلَام: آمَنْتُ بِاللهِ وَكَذَّبْتُ بَصَرِي". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈസബ്നു മർയം(അ) ഒരാൾ മോഷ്ടിക്കുന്നതു കൊണ്ടു. അപ്പോൾ അവിടുന്ന് അയാളോട് ചോദിച്ചു: നീ മോഷ്ടിച്ചിട്ടുണ്ടോ? അയാൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, അവനല്ലാതെ മറ്റൊരു ആരാധ്യനുമില്ല, ഞാൻ മോഷ്ടിച്ചിട്ടില്ല. ഈസാ(അ) പറഞ്ഞു: ഞാൻ അല്ലാഹുവെക്കൊണ്ട് വിശ്വസിക്കുകയും എന്റെ കാഴ്ചയെ കളവാക്കുകയും ചെയ്യുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 450, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِي اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بَيْنَ رَجُلَيْنِ، فَقَالَ الْمَقْضِيُّ عَلَيْهِ لَمَّا أَدْبَرَ: حَسْبِيَ اللهُ وَنِعْمَ الْوَكِيلُ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ يَلُومُ عَلَى الْعَجْزِ، وَلَكِنْ عَلَيْكَ بِالْكَيْسِ، فَإِذَا غَلَبَكَ أَمْرٌ فَقُلْ: حَسْبِيَ اللهُ وَنِعْمَ الْوَكِيلُ". (د)', 'ഔഫുബ്നു മാലിക്(റ): നിശ്ചയം നബി(സ) രണ്ടുപേർക്കിടയിൽ വിധി പറഞ്ഞു. തിരിഞ്ഞുപോകുമ്പോൾ എതിരെ വിധിക്കപ്പെട്ടവൻ പറഞ്ഞു: എനിക്കല്ലാഹു മതി, അവനെത്ര നല്ല ഭരമേൽപ്പിക്കപ്പെടുന്നവനാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അശക്തതയുടെ പേരിൽ അല്ലാഹു ആക്ഷേപിക്കും. എന്നാൽ ബുദ്ധി പ്രയോഗിക്കൽ നിനക്ക് നിർബന്ധമാണ്. അപ്പോൾ നിന്നെയാരെങ്കിലും അതിജയിക്കുകയാണെങ്കിൽ നീ പറയുക: എനിക്കല്ലാഹു മതി, ഭരമേൽപ്പിക്കപ്പെടുന്നവനായി അവനെത്ര നല്ലവൻ." (ദ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنِ الْأَشْعَثِ بْنِ قَيْسٍ رَضِي اللهُ عَنْهُ: أَنَّ رَجُلًا مِنْ كِنْدَةَ وَرَجُلًا مِنْ حَضْرَمَوْتَ اخْتَصَمَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أَرْضٍ مِنَ الْيَمَنِ، فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللهِ، إِنَّ أَرْضِي اغْتَصَبَنِيهَا أَبُو هَذَا، وَهِيَ فِي يَدِهِ. قَالَ: "هَلْ لَكَ بَيِّنَةٌ". قَالَ: لَا، وَلَكِنْ أَحْلِفُهُ وَاللهِ مَا يَعْلَمُ أَنَّهَا أَرْضِي اغْتَصَبَنِيهَا أَبُوهُ. فَتَهَيَّأَ الْكِنْدِيُّ، يَعْنِي لِلْيَمِينِ، وَسَاقَ الْحَدِيثَ. (د)', 'അശ്അസുബ്നു ഖൈസ്(റ): കിന്ദ ഗോത്രത്തിൽപെട്ട ഒരാളും ഹളർമൗത്ത് എന്ന സ്ഥലത്തുള്ള ഒരാളും തമ്മിൽ യമനിലെ ഒരു ഭൂമിയുടെ വിഷയത്തിൽ തർക്കിച്ചുകൊണ്ട് നബി(സ)യെ സമീപിച്ചു. അപ്പോൾ ഹളർമൗതുകാരൻ പറഞ്ഞു: റസൂലേ, എന്റെ ഭൂമി എന്നിൽ നിന്നും ഇയാളുടെ പിതാവ് തട്ടിയെടുത്തിരിക്കുന്നു. അതിപ്പോൾ ഇയാളുടെ കയ്യിലാണ്. തിരുമേനി(സ) ചോദിച്ചു: "നിനക്ക് വല്ല തെളിവുമുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. പക്ഷേ, അല്ലാഹുവാണ, ഇത് എന്നിൽ നിന്നും ഇയാളുടെ പിതാവ് അപഹരിച്ചതാണെന്ന് ഇയാൾക്കറിയില്ലെന്ന് അങ്ങ് ഇയാളെക്കൊണ്ട് സത്യം ചെയ്യിച്ചാലും. അപ്പോൾ കിന്ദക്കാരൻ സത്യം ചെയ്യനാനൊരുങ്ങി. ശേഷം ഹദീസ് തുടർന്നു പറഞ്ഞു. (ദ)', 'الْأَشْعَثِ بْنِ قَيْسٍ', 'അശ്അസുബ്നു ഖൈസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ وَائِلِ بْنِ حُجْرٍ الْحَضْرَمِيِّ رَضِي اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنْ حَضْرَمَوْتَ وَرَجُلٌ مِنْ كِنْدَةَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللهِ، إِنَّ هَذَا غَلَبَنِي عَلَى أَرْضٍ كَانَتْ لِأَبِي، فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضِي فِي يَدِي أَزْرَعُهَا، لَيْسَ لَهُ فِيهَا حَقٌّ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْحَضْرَمِيِّ: "أَلَكَ بَيِّنَةٌ". قَالَ: لَا، قَالَ: "فَلَكَ يَمِينُهُ". فَقَالَ: يَا رَسُولَ اللهِ، إِنَّهُ فَاجِرٌ، لَيْسَ يُبَالِي مَا حَلَفَ، لَيْسَ يَتَوَرَّعُ مِنْ شَيْءٍ. فَقَالَ: "لَيْسَ لَكَ مِنْهُ إِلَّا ذَلِكَ". (م,د,ت)', 'വാഇലുബ്നു ഹുജ്‌രിൽ ഹള്റമീ(റ): ഹള്ർമൗതിൽ നിന്ന് ഒരാളും കിന്ദക്കാരനായ ഒരാളും നബി(സ)യുടെ അടുക്കൽ വന്നു. അപ്പോൾ ഹള്ർമൗത്തുകാരൻ പറഞ്ഞു: റസൂലേ, എന്റെ പിതാവിനുണ്ടായിരുന്ന ഒരു ഭൂമി ഇയാൾ ശക്തി പ്രയോഗിച്ച് അധീനപ്പെടുത്തിയിരിക്കുന്നു. അപ്പോൾ കിൻദക്കാരൻ പറഞ്ഞു: അത് എന്റെ കൈവശമുള്ള, ഞാൻ കൃഷിചെയ്യുന്ന, എന്റെ ഭൂമിയാണ്. അദ്ദേഹത്തിനതിൽ ഒരവകാശവുമില്ല. അപ്പോൾ ഹള്ർമൗത്തുകാരനോട് നബി(സ) ചോദിച്ചു: "നിനക്ക് വല്ല തെളിവുമുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ ഇനി നിനക്കുള്ളത് അദ്ദേഹത്തിന്റെ സത്യം ചെയ്യലാണ്." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂലേ, നിശ്ചയം അവനൊരു തെമ്മാടിയാണ്. എന്താണ് സത്യം ചെയ്യുന്നതെന്ന് അയാൾ ഗൗനിക്കില്ല. ഒരു കാര്യത്തിലുംതന്നെ അദ്ദേഹം സൂക്ഷ്മത പുലർത്തുകയുമില്ല. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിനക്കയാളിൽ നിന്ന് ഇതല്ലാതെ മറ്റൊന്നുമില്ല." (മു,ദ,തു)', 'وَائِلِ بْنِ حُجْرٍ الْحَضْرَمِيِّ', 'വാഇലുബ്നു ഹുജ്‌രിൽ ഹള്റമീ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِي اللهُ عَنْهما قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ حَالَتْ شَفَاعَتُهُ دُونَ حَدٍّ مِنْ حُدُودِ اللهِ فَقَدْ ضَادَّ اللهَ، وَمَنْ خَاصَمَ فِي بَاطِلٍ وَهُوَ يَعْلَمُهُ لَمْ يَزَلْ فِي سَخَطِ اللهِ حَتَّى يَنْزِعَ عَنْهُ، وَمَنْ قَالَ فِي مُؤْمِنٍ مَا لَيْسَ فِيهِ أَسْكَنَهُ اللهُ رَدْغَةَ الْخَبَالِ حَتَّى يَخْرُجَ مِمَّا قَالَ". وَفِي رِوَايَةٍ: "وَمَنْ أَعَانَ عَلَى خُصُومَةٍ بِظُلْمٍ فَقَدْ بَاءَ بِغَضَبٍ مِنَ اللهِ عَزَّ وَجَلَّ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ആരുടെയെങ്കിലും ശുപാർശ അല്ലാഹുവിന്റെ ശിക്ഷകളിൽ നിന്നുള്ള ഏതെങ്കിലുമൊരു ശിക്ഷക്കു മുന്നിൽ മറയിട്ടാൽ നിശ്ചയം അവൻ അല്ലാഹുവിന്റെ കൽപനക്കെതിരെ പ്രവർത്തിച്ചിരിക്കുന്നു. ആരെങ്കിലും വാസ്തവമറിഞ്ഞുകൊണ്ട്തന്നെ അസത്യമായൊരു കാര്യത്തിൽ തർക്കിച്ചാൽ അതിൽനിന്ന് പിൻമാറുന്നതു വരെ അവൻ അല്ലാഹുവിന്റെ ദേഷ്യത്തിലായിരിക്കും. ആരെങ്കിലും ഒരു മുഅ്മിനിനെക്കുറിച്ച് അവനിലില്ലാത്തത് ആരോപിച്ചാൽ താൻ പറഞ്ഞതിൽ നിന്ന് പിൻമാറുന്നതു വരെ, നരകാവകാശികളെ പിഴിഞ്ഞെടുത്ത നീരുമായി കൂട്ടിക്കലർത്തിയാലുണ്ടാവുന്ന കളിമണ്ണിൽ അല്ലാഹു അവനെ താമസിപ്പിക്കും." മറ്റൊരു നിവേദനം: "അക്രമപരമായി ഒരു തർക്കത്തിന് ആരെങ്കിലും സഹായിച്ചാൽ അവൻ അല്ലാഹുവിന്റെ ദേഷ്യത്തിന് പാത്രീഭൂതനായിരിക്കുന്നു." (ദ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=5 and h.hadith_no=130), 1, 'وَفِي رِوَايَةٍ: "وَمَنْ أَعَانَ عَلَى خُصُومَةٍ بِظُلْمٍ فَقَدْ بَاءَ بِغَضَبٍ مِنَ اللهِ عَزَّ وَجَلَّ". (د)', 'മറ്റൊരു നിവേദനം: "അക്രമപരമായി ഒരു തർക്കത്തിന് ആരെങ്കിലും സഹായിച്ചാൽ അവൻ അല്ലാഹുവിന്റെ ദേഷ്യത്തിന് പാത്രീഭൂതനായിരിക്കുന്നു." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِي اللهُ عَنْهُمَا قَالَ: أَرَدْتُ الْخُرُوجَ إِلَى خَيْبَرَ، فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمْتُ عَلَيْهِ، وَقُلْتُ لَهُ: إِنِّي أَرَدْتُ الْخُرُوجَ إِلَى خَيْبَرَ، فَقَالَ: "إِذَا أَتَيْتَ وَكِيلِي فَخُذْ مِنْهُ خَمْسَةَ عَشَرَ وَسْقًا، فَإِنِ ابْتَغَى مِنْكَ آيَةً فَضَعْ يَدَكَ عَلَى تَرْقُوَتِهِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞാൻ ഖൈബറിലേക്ക് പുറപ്പെടാനുദ്ദേശിച്ചു. അപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് സലാം പറഞ്ഞ് അവിടുത്തോട് പറഞ്ഞു: നിശ്ചയം ഞാൻ ഖൈബറിലേക്ക് പോകാനുദ്ദേശിച്ചിരിക്കുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ എന്റെ വക്കീലിന്റെ അടുത്ത് ചെന്നാൽ അദ്ദേഹത്തിൽ നിന്ന് പതിനഞ്ച് വസ്ഖ് വാങ്ങുക. ഇനി അദ്ദേഹം നിന്നോട് വല്ല തെളിവും ചോദിച്ചാൽ നീ അദ്ദേഹത്തിന്റെ ചുമലെല്ലിൽ നിന്റെ കൈ വെക്കുക." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي بَكْرَةَ رَضِي اللهُ عَنْهُ قَالَ: أَثْنَى رَجُلٌ عَلَى رَجُلٍ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "وَيْلَكَ قَطَعْتَ عُنُقَ صَاحِبِكَ" مِرَارًا، ثُمَّ قَالَ: "مَنْ كَانَ مِنْكُمْ مَادِحًا أَخَاهُ لَا مَحَالَةَ فَلْيَقُلْ: أَحْسِبُ فُلَانًا، وَاللهُ حَسِيبُهُ، وَلَا أُزَكِّي عَلَى اللهِ أَحَدًا، أَحْسِبُهُ كَذَا وَكَذَا، إِنْ كَانَ يَعْلَمُ ذَلِكَ مِنْهُ". (خ)', 'അബൂബക്റ(റ): നബി(സ)യുടെ സന്നിധിയിൽവെച്ച് ഒരാൾ മറ്റൊരാളെ പുകഴ്തി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ നിന്റെ കൂട്ടുകാരന്റെ കഴുത്തറുക്കാതിരുന്നത് എന്ത് കൊണ്ടാണ്?" കുറേ പ്രാവശ്യം അവിടിന്നിപ്രകാരം ചോദിച്ചു. ശേഷം പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും തന്റെ സഹോദരനെ പുകഴ്താതെ കഴിയില്ലെങ്കിൽ ഇപ്രകാരം പറയുക: ഇന്നവനെക്കുറിച്ച് ഞാൻ ഇങ്ങനെ വിചാരിക്കുന്നു, അല്ലാഹുവാണ് അവനെക്കുറിച്ച് നന്നായറിയുന്നവൻ. അല്ലാഹുവിനെക്കാൾ ഞാൻ ഒരാളെയും പരിശുദ്ധനാക്കുകയില്ല. അവൻ ഇപ്രകാരമാണെന്ന് ഞാൻ കരുതുന്നു. അവനെക്കുറിച്ച് അപ്രകാരമുള്ള അറിവുണ്ടെങ്കിലാണിത് ചെയ്യേണ്ടത്." (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِي اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ عَلَى يَمِينٍ، وَهُوَ فِيهَا فَاجِرٌ، يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ، لَقِيَ اللهَ وَهُوَ عَلَيْهِ غَضْبَانُ". (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്‌ലിമായ ഒരാളുടെ ധനം സ്വന്തമാക്കാൻ വേണ്ടി, സത്യം ചെയ്യുന്നതിൽ തെമ്മാടിത്തരം കാട്ടുന്നവനായി, ആരെങ്കിലും സത്യം ചെയ്താൽ തന്നോട് ദേഷ്യപ്പെട്ടവനായി അവൻ അല്ലാഹുവിനെ കണ്ടുമുട്ടും." (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَبِي أُمَامَةَ الْحَارِثِيِّ رَضِي اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَقْتَطِعُ رَجُلٌ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ إِلَّا حَرَّمَ اللهُ عَلَيْهِ الْجَنَّةَ، وَأَوْجَبَ لَهُ النَّارَ". فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: يَا رَسُولَ اللهِ، وَإِنْ كَانَ شَيْئًا يَسِيرًا؟ قَالَ: "وَإِنْ كَانَ سِوَاكًا مِنْ أَرَاكٍ". (م,ن,جه)', 'അബൂഉമാമതുൽ ഹാരിസി(റ): നിശ്ചയം റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹു നരകം നിർബന്ധമാക്കുകയും സ്വർഗ്ഗം ഹറാമാക്കുകയും ചെയ്തിട്ടല്ലാതെ ഒരാളും സത്യം ചെയ്തുകൊണ്ട് മുസ്‌ലിമായ മറ്റൊരാളുടെ അവകാശം സ്വന്തമാക്കുകയില്ല." അപ്പോൾ അവരിൽ നിന്നൊരാൾ ചോദിച്ചു: റസൂലേ, അതൊരു ചെറിയ വസ്തുവാണെങ്കിൽ പോലും അങ്ങനെത്തന്നെയാണോ? അവിടുന്ന് പറഞ്ഞു: "അതൊരു അറാക്കിന്റെ മിസ്‌വാക്കാണെങ്കിൽ പോലും." (മു,ന,ജ)', 'أَبِي أُمَامَةَ الْحَارِثِيِّ', 'അബൂഉമാമതുൽ ഹാരിസി(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذَكَرَ أَنَّ رَجُلَيْنِ ادَّعَيَا دَابَّةً، وَلَمْ يَكُنْ بَيْنَهُمَا بَيِّنَةٌ، فَأَمَرَهُمَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَسْتَهِمَا عَلَى الْيَمِينِ. (د,جه)', 'അബൂഹുറൈറ(റ): രണ്ടാളുകൾ ഒരു മൃഗത്തിന് വേണ്ടി വാദിച്ചു. അവർക്ക് രണ്ടുപേർക്കും തെളിവുണ്ടായിരുന്നില്ല. അപ്പോൾ സത്യം ചെയ്തുകൊണ്ട് ഇരുവരും അതിനെ വീതിച്ചെടുക്കാൻ നബി(സ) അവരോട് കൽപിച്ചു. (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي مُوسَى رَضِي اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اخْتَصَمَ إِلَيْهِ رَجُلَانِ، بَيْنَهُمَا دَابَّةٌ، وَلَيْسَ لِوَاحِدٍ مِنْهُمَا بَيِّنَةٌ، فَجَعَلَهَا بَيْنَهُمَا نِصْفَيْنِ. (د,ن,جه)', 'അബൂമൂസ(റ): രണ്ടുപേർ തർക്കവുമായി റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്നു. അവർക്കിടയിലെ പ്രശ്നം ഒരു മൃഗമാണ്. അവരിൽ ഒരാൾക്കും തന്നെ തെളിവില്ല താനും. അപ്പോൾ അവിടുന്ന് അതിനെ അവർക്കിടയിൽ പകുതിയായി വീതിക്കാൻ വിധിച്ചു. (ദ,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ سَمُرَةَ ابْنِ جُنْدَبٍ رَضِي اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا ضَاعَ لِلرَّجُلِ مَتَاعٌ، أَوْ سُرِقَ لَهُ مَتَاعٌ، فَوَجَدَهُ فِي يَدِ رَجُلٍ يَبِيعُهُ، فَهُوَ أَحَقُّ بِهِ. وَيَرْجِعُ الْمُشْتَرِي عَلَى الْبَائِعِ بِالثَّمَنِ". (جه)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്കൊരു സാധനം നഷ്ടപ്പെടുകയും, അല്ലെങ്കിൽ അയാളുടെ വല്ല സാധനവും മോഷ്ടിക്കപ്പെടുകയും, അത് വിൽക്കുന്ന മറ്റൊരാളുടെ കയ്യിൽ പിന്നീടത് കണ്ടെത്തുകയും ചെയ്താൽ അയാളാണതിന് ഏറ്റവും അർഹൻ. അതിനെ വാങ്ങിയവൻ ആ വിൽപ്പനക്കാരന്റെ അടുത്തേക്ക് അതിന്റെ വില ചോദിച്ച് ചെല്ലുകയും വേണം." (ജ)', 'سَمُرَةَ ابْنِ جُنْدَبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 453, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنِ الشَّرِيدِ بْنِ سُوَيْدٍ رَضِي اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيُّ الْوَاجِدِ يُحِلُّ عِرْضَهُ وَعُقُوبَتَهُ". (د,ن,جه)', 'ശരീദുബ്നു സുവൈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കടം വീട്ടാൻ കഴിവുള്ളവൻ കടം വീട്ടാതെ അവധി നീട്ടി ബുദ്ധിമുട്ടാക്കൽ, അവനെ ശിക്ഷിക്കലും അവന്റെ അഭിമാനത്തെ കളങ്കപ്പെടുത്തലും അനുവദനീയമാക്കും." (ദ,ന,ജ)', 'الشَّرِيدِ بْنِ سُوَيْدٍ', 'ശരീദുബ്നു സുവൈദ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَبِيهِ عَنْ جَدِّهِ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِغَرِيمٍ لِي، فَقَالَ لِيَ: "الْزَمْهُ". ثُمَّ قَالَ لِي: "يَا أَخَا بَنِي تَمِيمٍ، مَا تُرِيدُ أَنْ تَفْعَلَ بِأَسِيرِكَ". (د,جه)', 'ശുറൈദുബ്നു സുവൈദ്(റ)വിന്റെ പിതാവ് തന്റെ പിതാമഹനിൽ നിന്ന്: എനിക്ക് കടം വീട്ടാനുള്ള ഒരാളുമായി ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ അവിടുന്നെന്നോട് പറഞ്ഞു: "താങ്കളയാളെ പിടിച്ചുവെക്കുക." പിന്നെ അവിടുന്ന് ചോദിച്ചു: "ബനൂതമീമിന്റെ സഹോദരാ, താങ്കളുടെ ബന്ധിയെ എന്ത് ചെയ്യാനാണ് താങ്കളുടെ ഉദ്ദേശ്യം." (ദ,ജ)', 'أَبِيهِ عَنْ جَدِّهِ قَالَ', 'ശുറൈദുബ്നു സുവൈദ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَبَسَ رَجُلًا فِي تُهْمَةٍ. (د,ت,ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): തെറ്റിദ്ധാരണ കാരണം നബി(സ) ഒരാളെ ബന്ധിയാക്കി. (ദ,തു,ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'وَعَنْهُ: أَنَّهُ قَامَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ، فَقَالَ: جِيرَانِي بِمَا أُخِذُوا؟ فَأَعْرَضَ عَنْهُ، مَرَّتَيْنِ، ثُمَّ ذَكَرَ شَيْئًا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَلُّوا لَهُ عَنْ جِيرَانِهِ". (د)', 'മുആവിയതുബ്നു ഹൈദ(റ): നബി(സ) പ്രസംഗിച്ചുകൊണ്ടിരിക്കെ അദ്ദേഹം തിരുമേനി(സ)യുടെ സമീപത്തേക്ക് എണീറ്റുചെന്ന് ചോദിച്ചു: എന്റെ അയൽവാസികൾ എന്ത് കാരണത്താലാണ് ബന്ധികളാക്കപ്പെട്ടത്? അപ്പോൾ അവിടുന്ന് അദ്ദേഹത്തിൽ നിന്ന് തിരിഞ്ഞുകളഞ്ഞു. ഇങ്ങനെ രണ്ട് പ്രാവശ്യം സംഭവിച്ചു. പിന്നെ അദ്ദേഹം കുറച്ച് കാര്യങ്ങൾ പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹത്തിന്റെ അയൽവാസികളെ അദ്ദേഹത്തിന് വിട്ടുകൊടുക്കുക." (ദ)', null, 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إِذَا اسْتَأْذَنَ أَحَدَكُمْ جَارُهُ أَنْ يَغْرِزَ خَشَبَةً فِي جِدَارِهِ فَلَا يَمْنَعْهُ". فَلَمَّا حَدَّثَهُمْ أَبُو هُرَيْرَةَ طَأْطَئُوا رُءُوسَهُمْ، فَلَمَّا رَآهُمْ قَالَ: مَا لِي أَرَاكُمْ عَنْهَا مُعْرِضِينَ، وَاللهِ لَأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞതായി അദ്ദേഹം വിവരിക്കുകയാണ്: "നിങ്ങളിലാരുടെയെങ്കിലും ചുമരിന്മേൽ ഒരു മരത്തടി നടാൻ തന്റെ അയൽവാസി സമ്മതം ചോദിച്ചാൽ നിങ്ങളയാളെ വിലക്കരുത്." അബൂഹുറൈറ(റ) ജനങ്ങളോട് ഈ ഹദീസ് പറഞ്ഞപ്പോൾ അവർ തല താഴ്ത്തി. ഇത് കണ്ടപ്പോൾ അദ്ദഹം ചോദിച്ചു: ഈ കാര്യത്തിൽ നിന്ന് പിന്തിരിഞ്ഞുകളയുന്നവരായിട്ടാണല്ലോ ഞാൻ നിങ്ങളെ കാണുന്നത്. അല്ലാഹുവാണ് സത്യം, നിങ്ങളിലെ എല്ലാവർക്കുമിടയിൽ ഞാനീ വാർത്ത പരത്തും. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 454, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ عِكْرِمَةَ بْنِ سَلَمَةَ: أَنَّ أَخَوَيْنِ مِنْ بَلْمُغِيرَةِ: أَعْتَقَ أَحَدُهُمَا أَنْ لَا يَغْرِزَ خَشَبًا فِي جِدَارِهِ، فَأَقْبَلَ مُجَمِّعُ بْنُ يَزِيدَ وَرِجَالٌ كَثِيرٌ مِنَ الْأَنْصَارِ رَضِي اللهُ عَنْهُم فَقَالُوا: نَشْهَدُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَمْنَعْ أَحَدُكُمْ جَارَهُ أَنْ يَغْرِزَ خَشَبَةً فِي جِدَارِهِ". فَقَالَ: يَا أَخِي، إِنَّكَ مَقْضِيٌّ لَكَ عَلَيَّ، وَقَدْ حَلَفْتُ، فَاجْعَلْ أُسْطُوَانًا دُونَ حَائِطِي أَوْ جِدَارِي، فَاجْعَلْ عَلَيْهِ خَشَبَكَ. (جه)', 'ഇക്‌രിമത്തുബ്നു സലമ(റ): ബനൂൽ മുഗീറയിലെ രണ്ട് സഹോദരങ്ങളിലൊരാൾ തന്റെ ചുമരിൽ മറ്റെയാൾ മരത്തടി നാട്ടിയാൽ താൻ ഒരടിമയെ മോചിപ്പിക്കുമെന്ന് സത്യംചെയ്തു. അപ്പോൾ മുജമ്മഉബ്നു യസീദ്(റ)വും അൻസാരികളായ കുറെ ആളുകളും വന്നു, അവർ പറഞ്ഞു: "നിങ്ങളിലൊരാളും തന്റെ ചുമരിന്മേൽ മരത്തടി നാട്ടുന്നതിൽനിന്ന് തന്റെ അയൽവാസിയെ വിലക്കരുത്" എന്ന് നബി(സ) പറഞ്ഞിട്ടുണ്ടെന്ന് ഞങ്ങൾ സാക്ഷ്യം വഹിക്കുന്നു. അപ്പോൾ സത്യം ചെയ്തയാൾ പറഞ്ഞു: എന്റെ സഹോദരാ, എനിക്ക് പ്രതികൂലമായും നിനക്ക് അനുകൂലമായും വിധിക്കപ്പെട്ടിരിക്കുന്നു. ഞാനാണെങ്കിൽ സത്യം ചെയ്യുകയും ചെയ്തിരിക്കുന്നു. അതുകൊണ്ട് നീ എന്റെ ചുമരിന്റെയോ മതിലിന്റെയോ മുന്നിലൊരു തൂണുണ്ടാക്കി അതിന്മേൽ നിന്റെ മരത്തടി വെക്കുക. (ജ)', 'عِكْرِمَةَ بْنِ سَلَمَةَ', 'ഇക്‌രിമത്തുബ്നു സലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنِ ابْنِ عَبَّاسٍ رَضِي اللهُ عَنْهُما: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَمْنَعْ أَحَدُكُمْ جَارَهُ أَنْ يَغْرِزَ خَشَبَةً عَلَى جِدَارِهِ". [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരും തന്നെ തന്റെ ചുമരിൽ മരത്തടി നാട്ടാൻ തന്റെ അയൽവാസിയെ വിസമ്മതിക്കരുത്."', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], '{}'::text[], 'ز: في إسناده ضعيف', null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَبِي صِرْمَةَ رَضِي اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ ضَارَّ أَضَرَّ اللهُ بِهِ، وَمَنْ شَاقَّ شَاقَّ اللهُ عَلَيْهِ". (د,ت,جه)', 'അബൂസ്വർമ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും വിഷമിപ്പിച്ചാൽ അല്ലാഹു അവനെയും വിഷമിപ്പിക്കും. ആരെങ്കിലും ബുദ്ധിമുട്ടാക്കിയാൽ അല്ലാഹു അവനെയും ബുദ്ധിമുട്ടിക്കും."', 'أَبِي صِرْمَةَ', 'അബൂസ്വർമ(റ)', null, null, array['د','ت','جه']::text[], '{}'::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِي اللهُ عَنْهُ: أَنَّهُ كَانَتْ لَهُ عَضُدٌ مِنْ نَخْلٍ فِي حَائِطِ رَجُلٍ مِنَ الْأَنْصَارِ، قَالَ: وَمَعَ الرَّجُلِ أَهْلُهُ، قَالَ: فَكَانَ سَمُرَةُ يَدْخُلُ إِلَى نَخْلِهِ فَيَتَأَذَّى بِهِ وَيَشُقُّ عَلَيْهِ، فَطَلَبَ إِلَيْهِ أَنْ يَبِيعَهُ فَأَبَى، فَطَلَبَ إِلَيْهِ أَنْ يُنَاقِلَهُ فَأَبَى، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَطَلَبَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعَهُ فَأَبَى، فَطَلَبَ إِلَيْهِ أَنْ يُنَاقِلَهُ فَأَبَى، قَالَ: "فَهَبْهُ لَهُ وَلَكَ كَذَا وَكَذَا". أَمْرًا رَغَّبَهُ فِيهِ، فَأَبَى، فَقَالَ: "أَنْتَ مُضَارٌّ". فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْأَنْصَارِيِّ: "اذْهَبْ فَاقْلَعْ نَخْلَهُ". (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): അദ്ദേഹത്തിന് അൻസാറുകളിൽ പെട്ട ഒരാളുടെ തോട്ടത്തിൽ അൽപം ഈത്തപ്പനകളുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: അൻസാരിയോടൊപ്പം തന്റെ കുടുംബവുമുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: സമുറത്(റ) തന്റെ ഈത്തപ്പനകൾക്കിടയിൽ പ്രവേശിക്കുമായിരുന്നു. അത് അൻസാരിക്ക് ബുദ്ധിമുട്ടുണ്ടാക്കുകയും പ്രയാസമാവുകയും ചെയ്യുമായിരുന്നു. അപ്പോൾ അദ്ദേഹം സമുറത്(റ)വിനോടത് തനിക്ക് വിൽക്കാനാവശ്യപ്പെട്ടു. അദ്ദേഹമതിന് തയ്യാറായില്ല. അപ്പോഴദ്ദേഹം സമുറത്(റ)വിനോടത് പരസ്പരം കൈമാറാനാവശ്യപ്പെട്ടു. അദ്ദേഹം അതിനും തയ്യാറായില്ല. അപ്പോഴദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ വന്ന് അവിടുത്തോട് വിവരം പറഞ്ഞു. നബി(സ) സമുറത്(റ)വിനോടത് വിൽക്കാനാവശ്യപ്പെട്ടു. സമുറത്(റ) അതിന് വിസമ്മതിച്ചു. അത് അയാളുമായി പരസ്പരം കൈമാറാൻ നബി(സ) പറഞ്ഞു. അദ്ദേഹമതിനും വിസമ്മതിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്നാൽ നീയത് അദ്ദേഹത്തിന് നൽകുക. നിനക്ക് ഇന്ന വസ്തുക്കളെല്ലാം തരാം." അവിടുന്ന് സമുറത്(റ)വിനെ പ്രലോഭിപ്പിക്കാൻ എന്തോ പറഞ്ഞു. അപ്പോഴും അദ്ദേഹം വിസമ്മതിച്ചു. ഉടനെ തിരുമേനി(സ) പറഞ്ഞു: "നീ ബുദ്ധിമുട്ടിക്കുന്നവനാണ്." ശേഷം റസൂൽ(സ) ആ അൻസാരിയോട് പറഞ്ഞു: "നീ പോയി അദ്ദേഹത്തിന്റെ ഈത്തപ്പനകൾ പിഴുതെടുക്കുക." (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 455, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِي اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى أَنْ: "لَا ضَرَرَ وَلَا ضِرَارَ". (ز: منقطع) (جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): "മറ്റുള്ളവരെ ബുദ്ധിമുട്ടിക്കലും രണ്ടുപേർ പരസ്പരം ബുദ്ധിമുട്ടിക്കലും അനുവദനീയമല്ല" എന്ന് നബി(സ) വിധിച്ചു. ഹദീസ് മുൻഖതിഅ് ആണ്. (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي هُرَيْرَةَ رَضِي اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اجْعَلُوا الطَّرِيقَ سَبْعَةَ أَذْرُعٍ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ വഴി ഏഴ് മുഴമാക്കുക." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنِ ابْنِ عَبَّاسٍ رَضِي اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اخْتَلَفْتُمْ فِي الطَّرِيقِ فَاجْعَلُوهُ سَبْعَةَ أَذْرُعٍ". (ق,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വഴിയുടെ കാര്യത്തിൽ നിങ്ങൾ തർക്കിക്കുകയാണെങ്കിൽ നിങ്ങളതിനെ ഏഴ് മുഴമാക്കുക." (ബു,മു,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=3 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
